{"command":"mkdir -p /workspace/src && cat > /workspace/src/cli.rs <<'EOF'
//! Command-line argument parsing, mimicking the behaviour of the original
//! clap-based interface (including its error messages).

use std::process;

pub const VERSION: &str = "0.17.0";

pub const HELP: &str = "crowbook 0.17.0 by Élisabeth Henry <liz.henry@ouvaton.org>
Render a Markdown book in EPUB, PDF or HTML.

USAGE:
    {bin} [OPTIONS] [BOOK]

OPTIONS:
  -f, --force-emoji
          Force emoji usage even if it might not work on your system
  -s, --single
          Use a single Markdown file instead of a book configuration file
  -n, --no-fancy
          Disably fancy UI
  -v, --verbose
          Print warnings in parsing/rendering
  -a, --autograph
          Prompts for an autograph for this book
  -q, --quiet
          Don't print info/error messages
  -c, --create <files>...
          Create a new book with existing Markdown files
  -o, --output <output>
          Specify output file
  -t, --to <to>
          Generate specific format
      --set <set> <set>...
          Set a list of book options
  -l, --list-options
          List all possible options
  -L, --lang <lang>
          Set the runtime language used by Crowbook
      --print-template <print-template>
          Prints the default content of a template
  -S, --stats
          Print some project statistics
  -h, --help
          Print help
  -V, --version
          Print version

ARGS:
  [BOOK]  File containing the book configuration file, or a Markdown file when called with --single
";

pub const TO_VALUES: &[&str] = &["epub", "pdf", "html", "tex", "odt", "html.dir"];

#[derive(Debug, Default, Clone)]
pub struct Args {
    pub force_emoji: bool,
    pub single: bool,
    pub no_fancy: bool,
    pub verbose: bool,
    pub autograph: bool,
    pub quiet: bool,
    pub create: Option<Vec<String>>,
    pub output: Option<String>,
    pub to: Option<String>,
    pub set: Option<Vec<String>>,
    pub list_options: bool,
    pub lang: Option<String>,
    pub print_template: Option<String>,
    pub stats: bool,
    pub book: Option<String>,
}

struct OptDef {
    short: Option<char>,
    long: &'static str,
    /// display name used in error messages
    display: &'static str,
    /// kind: 0 = flag, 1 = single value, 2 = multiple values (>=1), 3 = at least 2 values
    kind: u8,
}

const OPTS: &[OptDef] = &[
    OptDef { short: Some('f'), long: "force-emoji", display: "--force-emoji", kind: 0 },
    OptDef { short: Some('s'), long: "single", display: "--single", kind: 0 },
    OptDef { short: Some('n'), long: "no-fancy", display: "--no-fancy", kind: 0 },
    OptDef { short: Some('v'), long: "verbose", display: "--verbose", kind: 0 },
    OptDef { short: Some('a'), long: "autograph", display: "--autograph", kind: 0 },
    OptDef { short: Some('q'), long: "quiet", display: "--quiet", kind: 0 },
    OptDef { short: Some('c'), long: "create", display: "--create <files>...", kind: 2 },
    OptDef { short: Some('o'), long: "output", display: "--output <output>", kind: 1 },
    OptDef { short: Some('t'), long: "to", display: "--to <to>", kind: 1 },
    OptDef { short: None, long: "set", display: "--set <set> <set>...", kind: 3 },
    OptDef { short: Some('l'), long: "list-options", display: "--list-options", kind: 0 },
    OptDef { short: Some('L'), long: "lang", display: "--lang <lang>", kind: 1 },
    OptDef { short: None, long: "print-template", display: "--print-template <print-template>", kind: 1 },
    OptDef { short: Some('S'), long: "stats", display: "--stats", kind: 0 },
    OptDef { short: Some('h'), long: "help", display: "--help", kind: 0 },
    OptDef { short: Some('V'), long: "version", display: "--version", kind: 0 },
];

fn bin_name() -> String {
    let arg0 = std::env::args().next().unwrap_or_else(|| "crowbook".to_string());
    std::path::Path::new(&arg0)
        .file_name()
        .map(|s| s.to_string_lossy().to_string())
        .unwrap_or(arg0)
}

fn usage_line() -> String {
    format!("Usage: {} [OPTIONS] [BOOK]", bin_name())
}

fn error_with_usage(msg: &str) -> ! {
    eprintln!("error: {}\n\n{}\n\nFor more information, try '--help'.", msg, usage_line());
    process::exit(2);
}

fn error_no_usage(msg: &str) -> ! {
    eprintln!("error: {}\n\nFor more information, try '--help'.", msg);
    process::exit(2);
}

fn print_help() -> ! {
    print!("{}", HELP.replace("{bin}", &bin_name()));
    process::exit(0);
}

fn print_version() -> ! {
    println!("crowbook {}", VERSION);
    process::exit(0);
}

fn find_long(name: &str) -> Option<&'static OptDef> {
    OPTS.iter().find(|o| o.long == name)
}

fn find_short(c: char) -> Option<&'static OptDef> {
    OPTS.iter().find(|o| o.short == Some(c))
}

fn is_flag_like(s: &str) -> bool {
    s.starts_with('-') && s != "-"
}

/// Parse command line arguments. Exits the process on error, like clap does.
pub fn parse() -> Args {
    let raw: Vec<String> = std::env::args().skip(1).collect();
    let mut args = Args::default();
    let mut seen: Vec<&'static str> = Vec::new();
    let mut i = 0;
    let mut positional_only = false;

    // Helper closures replaced by nested fns for borrow reasons.
    fn check_multiple(seen: &mut Vec<&'static str>, opt: &'static OptDef) {
        if seen.contains(&opt.long) {
            error_with_usage(&format!("the argument '{}' cannot be used multiple times", opt.display));
        }
        seen.push(opt.long);
    }

    fn apply_flag(args: &mut Args, opt: &'static OptDef) {
        match opt.long {
            "force-emoji" => args.force_emoji = true,
            "single" => args.single = true,
            "no-fancy" => args.no_fancy = true,
            "verbose" => args.verbose = true,
            "autograph" => args.autograph = true,
            "quiet" => args.quiet = true,
            "list-options" => args.list_options = true,
            "stats" => args.stats = true,
            "help" => print_help(),
            "version" => print_version(),
            _ => {}
        }
    }

    fn set_value(args: &mut Args, opt: &'static OptDef, value: String) {
        if opt.long == "to" && !TO_VALUES.contains(&value.as_str()) {
            error_no_usage(&format!(
                "invalid value '{}' for '--to <to>'\n  [possible values: epub, pdf, html, tex, odt, html.dir]",
                value
            ));
        }
        match opt.long {
            "output" => args.output = Some(value),
            "to" => args.to = Some(value),
            "lang" => args.lang = Some(value),
            "print-template" => args.print_template = Some(value),
            _ => {}
        }
    }

    // Collect values for a multi-valued option starting at index i.
    fn collect_values(raw: &[String], i: &mut usize) -> Vec<String> {
        let mut vals = Vec::new();
        while *i < raw.len() {
            let a = &raw[*i];
            if a == "--" || is_flag_like(a) {
                break;
            }
            vals.push(a.clone());
            *i += 1;
        }
        vals
    }

    while i < raw.len() {
        let a = raw[i].clone();
        i += 1;
        if positional_only {
            if args.book.is_none() {
                args.book = Some(a);
            } else {
                error_with_usage(&format!("unexpected argument '{}' found", a));
            }
            continue;
        }
        if a == "--" {
            positional_only = true;
            continue;
        }
        if a.starts_with("--") {
            let body = &a[2..];
            let (name, inline_val) = match body.find('=') {
                Some(p) => (&body[..p], Some(body[p + 1..].to_string())),
                None => (body, None),
            };
            let opt = match find_long(name) {
                Some(o) => o,
                None => {
                    let mut msg = format!("unexpected argument '{}' found", a);
                    if is_flag_like(&a) {
                        msg.push_str(&format!("\n\n  tip: to pass '{}' as a value, use '-- {}'", a, a));
                    }
                    error_with_usage(&msg);
                }
            };
            check_multiple(&mut seen, opt);
            match opt.kind {
                0 => {
                    if inline_val.is_some() {
                        error_with_usage(&format!(
                            "unexpected value '{}' for '{}' found; no more were expected",
                            inline_val.unwrap(),
                            opt.display
                        ));
                    }
                    apply_flag(&mut args, opt);
                }
                1 => {
                    let v = match inline_val {
                        Some(v) => v,
                        None => {
                            if i < raw.len() && !(is_flag_like(&raw[i]) && raw[i] != "-") {
                                let v = raw[i].clone();
                                i += 1;
                                v
                            } else {
                                error_no_usage(&format!(
                                    "a value is required for '{}' but none was supplied",
                                    opt.display
                                ));
                            }
                        }
                    };
                    set_value(&mut args, opt, v);
                }
                _ => {
                    let mut vals = Vec::new();
                    if let Some(v) = inline_val {
                        vals.push(v);
                    }
                    vals.extend(collect_values(&raw, &mut i));
                    if vals.is_empty() {
                        error_no_usage(&format!(
                            "a value is required for '{}' but none was supplied",
                            opt.display
                        ));
                    }
                    if opt.kind == 3 && vals.len() < 2 {
                        error_with_usage(&format!(
                            "2 values required by '{}'; only {} was provided",
                            opt.display,
                            vals.len()
                        ));
                    }
                    match opt.long {
                        "create" => args.create = Some(vals),
                        "set" => args.set = Some(vals),
                        _ => {}
                    }
                }
            }
        } else if a.starts_with('-') && a.len() > 1 {
            // short flags, possibly combined
            let chars: Vec<char> = a[1..].chars().collect();
            let mut k = 0;
            while k < chars.len() {
                let c = chars[k];
                k += 1;
                let opt = match find_short(c) {
                    Some(o) => o,
                    None => {
                        error_with_usage(&format!("unexpected argument '-{}' found", c));
                    }
                };
                check_multiple(&mut seen, opt);
                if opt.kind == 0 {
                    apply_flag(&mut args, opt);
                    continue;
                }
                // value-taking option: the rest of the token is the value, if any
                let rest: String = chars[k..].iter().collect();
                let rest = if let Some(stripped) = rest.strip_prefix('=') {
                    stripped.to_string()
                } else {
                    rest
                };
                k = chars.len();
                if opt.kind == 1 {
                    let v = if !rest.is_empty() {
                        rest
                    } else if i < raw.len() && !(is_flag_like(&raw[i]) && raw[i] != "-") {
                        let v = raw[i].clone();
                        i += 1;
                        v
                    } else {
                        error_no_usage(&format!(
                            "a value is required for '{}' but none was supplied",
                            opt.display
                        ));
                    };
                    set_value(&mut args, opt, v);
                } else {
                    let mut vals = Vec::new();
                    if !rest.is_empty() {
                        vals.push(rest);
                    }
                    vals.extend(collect_values(&raw, &mut i));
                    if vals.is_empty() {
                        error_no_usage(&format!(
                            "a value is required for '{}' but none was supplied",
                            opt.display
                        ));
                    }
                    match opt.long {
                        "create" => args.create = Some(vals),
                        "set" => args.set = Some(vals),
                        _ => {}
                    }
                }
            }
        } else {
            if args.book.is_none() {
                args.book = Some(a);
            } else {
                error_with_usage(&format!("unexpected argument '{}' found", a));
            }
        }
    }
    args
}
EOF
echo done"}

