                        "set" => args.set = Some(vals),
                        _ => {}
                    }
                }
            }
        } else {
            if args.book.is_none() {
                args.book = Some(a);
            } else {
                error_with_usage(&format!("unexpected argument '{}' found", a));
            }
        }
    }
    args
}
