//! A small YAML subset parser, modelled after the behaviour of the
//! `yaml-rust` crate (including its `Debug` representation of values).

use std::fmt;

#[derive(Clone, PartialEq)]
pub enum Yaml {
    Real(String),
    Integer(i64),
    String(String),
    Boolean(bool),
    Array(Vec<Yaml>),
    Hash(Vec<(Yaml, Yaml)>),
    Null,
}

impl fmt::Debug for Yaml {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Yaml::Real(s) => write!(f, "Real({:?})", s),
            Yaml::Integer(i) => write!(f, "Integer({})", i),
            Yaml::String(s) => write!(f, "String({:?})", s),
            Yaml::Boolean(b) => write!(f, "Boolean({})", b),
            Yaml::Array(v) => {
                write!(f, "Array(")?;
                f.debug_list().entries(v.iter()).finish()?;
                write!(f, ")")
            }
            Yaml::Hash(h) => {
                write!(f, "Hash(")?;
                f.debug_map().entries(h.iter().map(|(k, v)| (k, v))).finish()?;
                write!(f, ")")
            }
            Yaml::Null => write!(f, "Null"),
        }
    }
}

impl Yaml {
    pub fn as_str(&self) -> Option<&str> {
        match self {
            Yaml::String(s) => Some(s),
            _ => None,
        }
    }
    pub fn as_bool(&self) -> Option<bool> {
        match self {
            Yaml::Boolean(b) => Some(*b),
            _ => None,
        }
    }
    pub fn as_i64(&self) -> Option<i64> {
        match self {
            Yaml::Integer(i) => Some(*i),
            _ => None,
        }
    }
    pub fn as_f64(&self) -> Option<f64> {
        match self {
            Yaml::Real(s) => parse_f64(s),
            _ => None,
        }
    }
    pub fn as_vec(&self) -> Option<&Vec<Yaml>> {
        match self {
            Yaml::Array(v) => Some(v),
            _ => None,
        }
    }
    pub fn as_hash(&self) -> Option<&Vec<(Yaml, Yaml)>> {
        match self {
            Yaml::Hash(h) => Some(h),
            _ => None,
        }
    }
    pub fn is_null(&self) -> bool {
        matches!(self, Yaml::Null)
    }

    /// Resolve a plain scalar into a typed value, like yaml-rust does.
    pub fn from_plain(v: &str) -> Yaml {
        if v.starts_with("0x") {
            if let Ok(i) = i64::from_str_radix(&v[2..], 16) {
                return Yaml::Integer(i);
            }
        }
        if v.starts_with("0o") {
            if let Ok(i) = i64::from_str_radix(&v[2..], 8) {
                return Yaml::Integer(i);
            }
        }
        if let Some(stripped) = v.strip_prefix('+') {
            if let Ok(i) = stripped.parse::<i64>() {
                return Yaml::Integer(i);
            }
        }
        match v {
            "~" | "null" => return Yaml::Null,
            "true" => return Yaml::Boolean(true),
            "false" => return Yaml::Boolean(false),
            _ => {}
        }
        if let Ok(i) = v.parse::<i64>() {
            return Yaml::Integer(i);
        }
        if parse_f64(v).is_some() {
            return Yaml::Real(v.to_string());
        }
        Yaml::String(v.to_string())
    }

    /// A short description of the type, used in error messages.
    pub fn type_name(&self) -> &'static str {
        match self {
            Yaml::Real(_) => "real",
            Yaml::Integer(_) => "integer",
            Yaml::String(_) => "string",
            Yaml::Boolean(_) => "boolean",
            Yaml::Array(_) => "array",
            Yaml::Hash(_) => "hash",
            Yaml::Null => "null",
        }
    }
}

fn parse_f64(v: &str) -> Option<f64> {
    match v {
        ".inf" | ".Inf" | ".INF" | "+.inf" | "+.Inf" | "+.INF" => Some(f64::INFINITY),
        "-.inf" | "-.Inf" | "-.INF" => Some(f64::NEG_INFINITY),
        ".nan" | ".NaN" | ".NAN" => Some(f64::NAN),
        _ => {
            // Rust accepts things like "inf", "nan", "infinity" which YAML does not.
            let lower = v.to_ascii_lowercase();
            if lower.contains("inf") || lower.contains("nan") {
                return None;
            }
            v.parse::<f64>().ok()
        }
    }
}

#[derive(Debug)]
pub struct YamlError {
    pub msg: String,
}

impl fmt::Display for YamlError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.msg)
    }
}

fn err<T>(msg: &str, line: usize, col: usize) -> Result<T, YamlError> {
    Err(YamlError {
        msg: format!("{} at line {} column {}", msg, line, col),
    })
}

struct Line {
    indent: usize,
    /// content without indentation
    text: String,
    /// 1-based line number
    nb: usize,
}

struct Parser {
    lines: Vec<Line>,
    pos: usize,
}

fn strip_comment(s: &str) -> &str {
    // A comment starts with '#' preceded by whitespace (or at start).
    let bytes = s.as_bytes();
    let mut in_single = false;
    let mut in_double = false;
    let mut i = 0;
    while i < bytes.len() {
        let c = bytes[i];
        if in_double {
            if c == b'\\' {
                i += 2;
                continue;
            }
            if c == b'"' {
                in_double = false;
            }
        } else if in_single {
            if c == b'\'' {
                in_single = false;
            }
        } else {
            if c == b'"' && (i == 0 || is_ws(bytes[i - 1]) || bytes[i - 1] == b':' || bytes[i - 1] == b'[' || bytes[i - 1] == b',' || bytes[i - 1] == b'-') {
                in_double = true;
            } else if c == b'\'' && (i == 0 || is_ws(bytes[i - 1]) || bytes[i - 1] == b':' || bytes[i - 1] == b'[' || bytes[i - 1] == b',' || bytes[i - 1] == b'-') {
                in_single = true;
            } else if c == b'#' && (i == 0 || is_ws(bytes[i - 1])) {
                return s[..i].trim_end();
            }
        }
        i += 1;
    }
    s.trim_end()
}

fn is_ws(c: u8) -> bool {
    c == b' ' || c == b'\t'
}

/// Find the position of the mapping indicator ": " (or ":" at end) in a line,
/// taking care of quoted keys. Returns byte index of ':'.
fn find_mapping_colon(s: &str) -> Option<usize> {
    let bytes = s.as_bytes();
    if bytes.is_empty() {
        return None;
    }
    if bytes[0] == b'"' || bytes[0] == b'\'' {
        let q = bytes[0];
        let mut i = 1;
        while i < bytes.len() {
            if q == b'"' && bytes[i] == b'\\' {
                i += 2;
                continue;
            }
            if bytes[i] == q {
                break;
            }
            i += 1;
        }
        // i at closing quote
        let mut j = i + 1;
        while j < bytes.len() && is_ws(bytes[j]) {
            j += 1;
        }
        if j < bytes.len() && bytes[j] == b':' && (j + 1 == bytes.len() || is_ws(bytes[j + 1])) {
            return Some(j);
        }
        return None;
    }
    if bytes[0] == b'[' || bytes[0] == b'{' {
        return None;
    }
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b':' && (i + 1 == bytes.len() || is_ws(bytes[i + 1])) {
            return Some(i);
        }
        if bytes[i] == b'#' && i > 0 && is_ws(bytes[i - 1]) {
            return None;
        }
        i += 1;
    }
    None
}

pub fn load_from_str(src: &str) -> Result<Vec<Yaml>, YamlError> {
    let mut lines = Vec::new();
    for (i, raw) in src.lines().enumerate() {
        let raw = raw.trim_end_matches('\r');
        let indent = raw.chars().take_while(|c| *c == ' ').count();
        lines.push(Line {
            indent,
            text: raw[indent..].to_string(),
            nb: i + 1,
        });
    }
    let mut p = Parser { lines, pos: 0 };
    let mut docs = Vec::new();
    loop {
        p.skip_blank();
        if p.pos >= p.lines.len() {
            break;
        }
        // document markers
        let t = p.lines[p.pos].text.trim_end().to_string();
        if t == "---" || t.starts_with("--- ") {
            p.pos += 1;
            p.skip_blank();
            if p.pos >= p.lines.len() {
                docs.push(Yaml::Null);
                break;
            }
            let t2 = p.lines[p.pos].text.trim_end().to_string();
            if t2 == "---" || t2.starts_with("--- ") || t2 == "..." {
                docs.push(Yaml::Null);
                continue;
            }
        }
        if t == "..." {
            p.pos += 1;
            continue;
        }
        let node = p.parse_node(0, true)?;
        docs.push(node);
        p.skip_blank();
        if p.pos < p.lines.len() {
            let t = p.lines[p.pos].text.trim_end().to_string();
            if t == "..." {
                p.pos += 1;
                continue;
            }
            if t == "---" || t.starts_with("--- ") {
                continue;
            }
            // Unexpected content
            let l = &p.lines[p.pos];
            return err(
                "while parsing a block mapping, did not find expected key",
                l.nb,
                l.indent + 1,
            );
        }
    }
    Ok(docs)
}

impl Parser {
    fn skip_blank(&mut self) {
        while self.pos < self.lines.len() {
            let t = strip_comment(&self.lines[self.pos].text);
            if t.is_empty() {
                self.pos += 1;
            } else {
                break;
            }
        }
    }

    fn is_seq_item(text: &str) -> bool {
        text == "-" || text.starts_with("- ") || text.starts_with("-\t")
    }

    /// Parse a node whose first line is the current line.
    /// `min_indent`: the indentation at which this node lives.
    fn parse_node(&mut self, min_indent: usize, top: bool) -> Result<Yaml, YamlError> {
        self.skip_blank();
        if self.pos >= self.lines.len() {
            return Ok(Yaml::Null);
        }
        let indent = self.lines[self.pos].indent;
        if !top && indent < min_indent {
            return Ok(Yaml::Null);
        }
        let text = strip_comment(&self.lines[self.pos].text).to_string();
        if Self::is_seq_item(&text) {
            return self.parse_sequence(indent);
        }
        if find_mapping_colon(&text).is_some() {
            return self.parse_mapping(indent);
        }
        // scalar or flow collection
        self.parse_scalar_lines(indent)
    }

    fn parse_sequence(&mut self, indent: usize) -> Result<Yaml, YamlError> {
        let mut items = Vec::new();
        loop {
            self.skip_blank();
            if self.pos >= self.lines.len() {
                break;
            }
            let l = &self.lines[self.pos];
            if l.indent != indent {
                if l.indent > indent {
                    return err(
                        "while parsing a block collection, did not find expected '-' indicator",
                        l.nb,
                        l.indent + 1,
                    );
                }
                break;
            }
            let text = strip_comment(&l.text).to_string();
            if !Self::is_seq_item(&text) {
                break;
            }
            let nb = l.nb;
            let rest = text[1..].trim_start();
            if rest.is_empty() {
                self.pos += 1;
                // nested node on following lines (must be more indented)
                self.skip_blank();
                if self.pos < self.lines.len() && self.lines[self.pos].indent > indent {
                    let v = self.parse_node(self.lines[self.pos].indent, false)?;
                    items.push(v);
                } else {
                    items.push(Yaml::Null);
                }
            } else {
                // inline content: could be a nested sequence/mapping starting on the same line
                let sub_indent = indent + (text.len() - rest.len());
                // Replace current line with the rest, at the deeper indentation
                self.lines[self.pos].indent = sub_indent;
                self.lines[self.pos].text = rest.to_string();
                let _ = nb;
                let v = self.parse_node(sub_indent, false)?;
                items.push(v);
            }
        }
        Ok(Yaml::Array(items))
    }

    fn parse_mapping(&mut self, indent: usize) -> Result<Yaml, YamlError> {
        let mut map: Vec<(Yaml, Yaml)> = Vec::new();
        loop {
            self.skip_blank();
            if self.pos >= self.lines.len() {
                break;
            }
            let l = &self.lines[self.pos];
            if l.indent != indent {
                if l.indent > indent {
                    return err(
                        "while parsing a block mapping, did not find expected key",
                        l.nb,
                        l.indent + 1,
                    );
                }
                break;
            }
            let text = strip_comment(&l.text).to_string();
            if text == "---" || text == "..." {
                break;
            }
            let nb = l.nb;
            let colon = match find_mapping_colon(&text) {
                Some(c) => c,
                None => {
                    if Self::is_seq_item(&text) {
                        return err(
                            "while parsing a block mapping, did not find expected key",
                            nb,
                            indent + 1,
                        );
                    }
                    return err(
                        "while parsing a block mapping, did not find expected key",
                        nb,
                        indent + 1,
                    );
                }
            };
            let key_text = text[..colon].trim_end();
            let key = self.scalar_from_text(key_text, nb)?;
            let rest = text[colon + 1..].trim_start();
            if rest.is_empty() {
                self.pos += 1;
                self.skip_blank();
                if self.pos < self.lines.len() {
                    let nl = &self.lines[self.pos];
                    if nl.indent > indent {
                        let v = self.parse_node(nl.indent, false)?;
                        map.push((key, v));
                        continue;
                    }
                    let ntext = strip_comment(&nl.text).to_string();
                    if nl.indent == indent && Self::is_seq_item(&ntext) {
                        let v = self.parse_sequence(indent)?;
                        map.push((key, v));
                        continue;
                    }
                }
                map.push((key, Yaml::Null));
            } else if rest.starts_with('|') || rest.starts_with('>') {
                let v = self.parse_block_scalar(rest, indent)?;
                map.push((key, v));
            } else {
                let sub_indent = indent + (text.len() - rest.len());
                self.lines[self.pos].indent = sub_indent;
                self.lines[self.pos].text = rest.to_string();
                let v = self.parse_scalar_lines(sub_indent)?;
                map.push((key, v));
            }
        }
        Ok(Yaml::Hash(map))
    }

    /// Parse a block scalar (`|` or `>`), the header being `header`.
    fn parse_block_scalar(&mut self, header: &str, parent_indent: usize) -> Result<Yaml, YamlError> {
        let folded = header.starts_with('>');
        let mut chomp = 0i32; // 0 clip, -1 strip, 1 keep
        for c in header[1..].chars() {
            match c {
                '-' => chomp = -1,
                '+' => chomp = 1,
                _ => {}
            }
        }
        self.pos += 1;
        // determine indentation from first non-empty line
        let mut block_indent = None;
        let mut raw_lines: Vec<(usize, String)> = Vec::new();
        while self.pos < self.lines.len() {
            let l = &self.lines[self.pos];
            if l.text.trim().is_empty() {
                raw_lines.push((l.indent, String::new()));
                self.pos += 1;
                continue;
            }
            if block_indent.is_none() {
                if l.indent <= parent_indent {
                    break;
                }
                block_indent = Some(l.indent);
            }
            if l.indent < block_indent.unwrap() {
                break;
            }
            raw_lines.push((l.indent, l.text.clone()));
            self.pos += 1;
        }
        // remove trailing empty lines (keep count for chomping)
        let mut trailing = 0;
        while let Some((_, t)) = raw_lines.last() {
            if t.is_empty() {
                raw_lines.pop();
                trailing += 1;
            } else {
                break;
            }
        }
        let bi = block_indent.unwrap_or(parent_indent + 1);
        let mut out = String::new();
        if folded {
            let mut prev_empty = false;
            let mut first = true;
            let mut prev_more_indented = false;
            for (ind, t) in &raw_lines {
                if t.is_empty() {
                    out.push('\n');
                    prev_empty = true;
                    continue;
                }
                let more_indented = *ind > bi;
                if !first && !prev_empty {
                    if more_indented || prev_more_indented {
                        out.push('\n');
                    } else {
                        out.push(' ');
                    }
                }
                if *ind > bi {
                    out.push_str(&" ".repeat(ind - bi));
                }
                out.push_str(t);
                first = false;
                prev_empty = false;
                prev_more_indented = more_indented;
            }
        } else {
            for (i, (ind, t)) in raw_lines.iter().enumerate() {
                if i > 0 {
                    out.push('\n');
                }
                if !t.is_empty() && *ind > bi {
                    out.push_str(&" ".repeat(ind - bi));
                }
                out.push_str(t);
            }
        }
        match chomp {
            -1 => {}
            0 => {
                if !raw_lines.is_empty() {
                    out.push('\n');
                }
            }
            _ => {
                if !raw_lines.is_empty() {
                    out.push('\n');
                }
                for _ in 0..trailing {
                    out.push('\n');
                }
            }
        }
        Ok(Yaml::String(out))
    }

    /// Parse a scalar (plain, quoted) or flow collection starting at the
    /// current line, possibly spanning several lines.
    fn parse_scalar_lines(&mut self, indent: usize) -> Result<Yaml, YamlError> {
        let first_nb = self.lines[self.pos].nb;
        let first_text = self.lines[self.pos].text.clone();
        let first_trim = first_text.trim_start();
        if first_trim.starts_with('"') || first_trim.starts_with('\'') {
            // quoted scalar, possibly multi-line
            let q = first_trim.chars().next().unwrap();
            let mut buf = String::new();
            let mut cur = first_trim.to_string();
            let mut nb = first_nb;
            loop {
                buf.push_str(&cur);
                if quoted_terminated(&buf, q) {
                    break;
                }
                self.pos += 1;
                if self.pos >= self.lines.len() {
                    return err("while scanning a quoted scalar, found unexpected end of stream", nb, 1 + first_text.len().min(usize::MAX));
                }
                nb = self.lines[self.pos].nb;
                cur = format!("\n{}", self.lines[self.pos].text.trim());
            }
            self.pos += 1;
            let (val, rest) = parse_quoted(&buf, q);
            let rest = strip_comment(rest.trim_start());
            if !rest.is_empty() {
                return err("while scanning a plain scalar, found unexpected ':'", nb, 1);
            }
            return Ok(Yaml::String(val));
        }
        if first_trim.starts_with('[') || first_trim.starts_with('{') {
            // flow collection, possibly multi-line
            let mut buf = String::new();
            let mut nb = first_nb;
            loop {
                let t = strip_comment(&self.lines[self.pos].text).to_string();
                if !buf.is_empty() {
                    buf.push(' ');
                }
                buf.push_str(t.trim());
                self.pos += 1;
                if flow_balanced(&buf) {
                    break;
                }
                if self.pos >= self.lines.len() {
                    return err("while parsing a node, did not find expected node content", nb + 1, 1);
                }
                nb = self.lines[self.pos].nb;
            }
            let mut fp = FlowParser { chars: buf.chars().collect(), pos: 0, line: first_nb };
            let v = fp.parse_value()?;
            fp.skip_ws();
            if fp.pos < fp.chars.len() {
                return err("did not find expected <document start>", first_nb, fp.pos + 1);
            }
            return Ok(v);
        }
        // plain multi-line scalar
        let mut parts: Vec<String> = Vec::new();
        let mut text = strip_comment(first_trim).to_string();
        parts.push(text.clone());
        self.pos += 1;
        let mut pending_blank = 0;
        while self.pos < self.lines.len() {
            let l = &self.lines[self.pos];
            let t = strip_comment(&l.text);
            if t.is_empty() {
                pending_blank += 1;
                self.pos += 1;
                continue;
            }
            if l.indent < indent || (l.indent == indent && pending_blank == 0 && false) {
                break;
            }
            // Continuation lines must be more indented than the parent (we
            // approximate: at least `indent`). Lines that look like a new
            // mapping key at the same level end the scalar.
            if l.indent <= indent {
                break;
            }
            if t == "---" || t == "..." {
                break;
            }
            for _ in 0..pending_blank {
                parts.push(String::new());
            }
            pending_blank = 0;
            parts.push(t.to_string());
            self.pos += 1;
        }
        // rewind blank lines so that they are skipped by the caller
        // (they don't matter)
        if parts.len() == 1 {
            return self.scalar_from_text(&text, first_nb);
        }
        text = String::new();
        let mut prev_blank = false;
        for (i, p) in parts.iter().enumerate() {
            if p.is_empty() {
                text.push('\n');
                prev_blank = true;
                continue;
            }
            if i > 0 && !prev_blank {
                text.push(' ');
            }
            text.push_str(p);
            prev_blank = false;
        }
        Ok(Yaml::String(text))
    }

    fn scalar_from_text(&self, text: &str, nb: usize) -> Result<Yaml, YamlError> {
        let t = text.trim();
        if t.is_empty() {
            return Ok(Yaml::Null);
        }
        let first = t.chars().next().unwrap();
        if first == '"' || first == '\'' {
            if !quoted_terminated(t, first) {
                return err(
                    "while scanning a quoted scalar, found unexpected end of stream",
                    nb,
                    t.len() + 1,
                );
            }
            let (val, _) = parse_quoted(t, first);
            return Ok(Yaml::String(val));
        }
        if first == '[' || first == '{' {
            let mut fp = FlowParser { chars: t.chars().collect(), pos: 0, line: nb };
            return fp.parse_value();
        }
        Ok(Yaml::from_plain(t))
    }
}

fn quoted_terminated(s: &str, q: char) -> bool {
    let chars: Vec<char> = s.chars().collect();
    let mut i = 1;
    while i < chars.len() {
        if q == '"' && chars[i] == '\\' {
            i += 2;
            continue;
        }
        if chars[i] == q {
            if q == '\'' && i + 1 < chars.len() && chars[i + 1] == '\'' {
                i += 2;
                continue;
            }
            return true;
        }
        i += 1;
    }
    false
}

/// Parse a quoted scalar; returns the value and the remaining text after the closing quote.
fn parse_quoted(s: &str, q: char) -> (String, &str) {
    let mut out = String::new();
    let mut iter = s.char_indices();
    iter.next(); // opening quote
    let mut end = s.len();
    // handle line folding inside quoted scalars
    let raw: Vec<(usize, char)> = iter.collect();
    let mut i = 0;
    while i < raw.len() {
        let (idx, c) = raw[i];
        if q == '"' && c == '\\' {
            if i + 1 < raw.len() {
                let (_, n) = raw[i + 1];
                match n {
                    'n' => out.push('\n'),
                    't' => out.push('\t'),
                    'r' => out.push('\r'),
                    '0' => out.push('\0'),
                    'a' => out.push('\x07'),
                    'b' => out.push('\x08'),
                    'e' => out.push('\x1b'),
                    'f' => out.push('\x0c'),
                    'v' => out.push('\x0b'),
                    ' ' => out.push(' '),
                    '"' => out.push('"'),
                    '/' => out.push('/'),
                    '\\' => out.push('\\'),
                    'N' => out.push('\u{85}'),
                    '_' => out.push('\u{a0}'),
                    'L' => out.push('\u{2028}'),
                    'P' => out.push('\u{2029}'),
                    'x' | 'u' | 'U' => {
                        let len = match n {
                            'x' => 2,
                            'u' => 4,
                            _ => 8,
                        };
                        let mut code = 0u32;
                        let mut k = 0;
                        while k < len && i + 2 + k < raw.len() {
                            if let Some(d) = raw[i + 2 + k].1.to_digit(16) {
                                code = code * 16 + d;
                            }
                            k += 1;
                        }
                        if let Some(ch) = char::from_u32(code) {
                            out.push(ch);
                        }
                        i += 2 + len;
                        continue;
                    }
                    '\n' => {
                        // escaped line break: join lines
                        i += 2;
                        while i < raw.len() && (raw[i].1 == ' ' || raw[i].1 == '\t') {
                            i += 1;
                        }
                        continue;
                    }
                    other => {
                        out.push('\\');
                        out.push(other);
                    }
                }
                i += 2;
                continue;
            }
        }
        if c == q {
            if q == '\'' && i + 1 < raw.len() && raw[i + 1].1 == '\'' {
                out.push('\'');
                i += 2;
                continue;
            }
            end = idx + c.len_utf8();
            break;
        }
        if c == '\n' {
            // folding: a single newline becomes a space, multiple become newlines
            let mut count = 0;
            while i < raw.len() && raw[i].1 == '\n' {
                count += 1;
                i += 1;
            }
            // trailing spaces before the newline are removed
            while out.ends_with(' ') || out.ends_with('\t') {
                out.pop();
            }
            if count == 1 {
                out.push(' ');
            } else {
                for _ in 0..count - 1 {
                    out.push('\n');
                }
            }
            continue;
        }
        out.push(c);
        i += 1;
    }
    (out, &s[end..])
}

fn flow_balanced(s: &str) -> bool {
    let mut depth = 0i32;
    let mut in_single = false;
    let mut in_double = false;
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if in_double {
            if c == '\\' {
                i += 2;
                continue;
            }
            if c == '"' {
                in_double = false;
            }
        } else if in_single {
            if c == '\'' {
                in_single = false;
            }
        } else {
            match c {
                '"' => in_double = true,
                '\'' => in_single = true,
                '[' | '{' => depth += 1,
                ']' | '}' => depth -= 1,
                _ => {}
            }
        }
        i += 1;
    }
    depth <= 0 && !in_single && !in_double
}

struct FlowParser {
    chars: Vec<char>,
    pos: usize,
    line: usize,
}

impl FlowParser {
    fn skip_ws(&mut self) {
        while self.pos < self.chars.len() && (self.chars[self.pos] == ' ' || self.chars[self.pos] == '\t' || self.chars[self.pos] == '\n') {
            self.pos += 1;
        }
    }

    fn parse_value(&mut self) -> Result<Yaml, YamlError> {
        self.skip_ws();
        if self.pos >= self.chars.len() {
            return err("while parsing a node, did not find expected node content", self.line + 1, 1);
        }
        match self.chars[self.pos] {
            '[' => {
                self.pos += 1;
                let mut items = Vec::new();
                loop {
                    self.skip_ws();
                    if self.pos >= self.chars.len() {
                        return err("while parsing a flow sequence, did not find expected ',' or ']'", self.line, self.pos + 1);
                    }
                    if self.chars[self.pos] == ']' {
                        self.pos += 1;
                        break;
                    }
                    let v = self.parse_value()?;
                    items.push(v);
                    self.skip_ws();
                    if self.pos < self.chars.len() && self.chars[self.pos] == ',' {
                        self.pos += 1;
                        continue;
                    }
                    if self.pos < self.chars.len() && self.chars[self.pos] == ']' {
                        self.pos += 1;
                        break;
                    }
                    return err("while parsing a flow sequence, did not find expected ',' or ']'", self.line, self.pos + 1);
                }
                Ok(Yaml::Array(items))
            }
            '{' => {
                self.pos += 1;
                let mut map = Vec::new();
                loop {
                    self.skip_ws();
                    if self.pos >= self.chars.len() {
                        return err("while parsing a flow mapping, did not find expected ',' or '}'", self.line, self.pos + 1);
                    }
                    if self.chars[self.pos] == '}' {
                        self.pos += 1;
                        break;
                    }
                    let k = self.parse_value()?;
                    self.skip_ws();
                    let v = if self.pos < self.chars.len() && self.chars[self.pos] == ':' {
                        self.pos += 1;
                        self.parse_value()?
                    } else {
                        Yaml::Null
                    };
                    map.push((k, v));
                    self.skip_ws();
                    if self.pos < self.chars.len() && self.chars[self.pos] == ',' {
                        self.pos += 1;
                        continue;
                    }
                    if self.pos < self.chars.len() && self.chars[self.pos] == '}' {
                        self.pos += 1;
                        break;
                    }
                    return err("while parsing a flow mapping, did not find expected ',' or '}'", self.line, self.pos + 1);
                }
                Ok(Yaml::Hash(map))
            }
            '"' | '\'' => {
                let q = self.chars[self.pos];
                let start = self.pos;
                let mut i = self.pos + 1;
                while i < self.chars.len() {
                    if q == '"' && self.chars[i] == '\\' {
                        i += 2;
                        continue;
                    }
                    if self.chars[i] == q {
                        if q == '\'' && i + 1 < self.chars.len() && self.chars[i + 1] == '\'' {
                            i += 2;
                            continue;
                        }
                        break;
                    }
                    i += 1;
                }
                if i >= self.chars.len() {
                    return err("while scanning a quoted scalar, found unexpected end of stream", self.line, self.pos + 1);
                }
                let s: String = self.chars[start..=i].iter().collect();
                self.pos = i + 1;
                let (val, _) = parse_quoted(&s, q);
                Ok(Yaml::String(val))
            }
            _ => {
                let start = self.pos;
                while self.pos < self.chars.len() {
                    let c = self.chars[self.pos];
                    if c == ',' || c == ']' || c == '}' {
                        break;
                    }
                    if c == ':' && (self.pos + 1 >= self.chars.len() || self.chars[self.pos + 1] == ' ' || self.chars[self.pos + 1] == ',' || self.chars[self.pos + 1] == ']' || self.chars[self.pos + 1] == '}') {
                        break;
                    }
                    self.pos += 1;
                }
                let s: String = self.chars[start..self.pos].iter().collect();
                let s = s.trim();
                if s.is_empty() {
                    return Ok(Yaml::Null);
                }
                Ok(Yaml::from_plain(s))
            }
        }
    }
}
