//! Error type, mimicking the original's `Error`/`Source` display.

use std::fmt;

#[derive(Debug, Clone, Default, PartialEq)]
pub struct Source {
    pub file: Option<String>,
    pub line: Option<u32>,
}

impl Source {
    pub fn empty() -> Source {
        Source { file: None, line: None }
    }
    pub fn new(file: &str) -> Source {
        Source { file: Some(file.to_string()), line: None }
    }
    pub fn with_line(file: &str, line: u32) -> Source {
        Source { file: Some(file.to_string()), line: Some(line) }
    }
    pub fn set_line(&mut self, line: u32) {
        self.line = Some(line);
    }
    pub fn unset_line(&mut self) {
        self.line = None;
    }
}

impl fmt::Display for Source {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        if let Some(ref file) = self.file {
            write!(f, "{}", file)?;
            if let Some(line) = self.line {
                write!(f, ":{}", line)?;
            }
            write!(f, ": ")?;
        }
        Ok(())
    }
}

#[derive(Debug, Clone, PartialEq)]
pub enum Inner {
    Default(String),
    Parser(String),
    ConfigParser(String),
    FileNotFound(String, String),
    Render(String),
    Zipper(String),
    BookOption(String),
    InvalidOption(String),
    Template(String),
    Syntect(String),
    GrammarCheck(String),
}

#[derive(Debug, Clone, PartialEq)]
pub struct Error {
    pub source: Source,
    pub inner: Inner,
}

pub type Result<T> = std::result::Result<T, Error>;

impl Error {
    pub fn new(source: Source, inner: Inner) -> Error {
        Error { source, inner }
    }
    pub fn default(source: Source, msg: impl Into<String>) -> Error {
        Error::new(source, Inner::Default(msg.into()))
    }
    pub fn parser(source: Source, msg: impl Into<String>) -> Error {
        Error::new(source, Inner::Parser(msg.into()))
    }
    pub fn config_parser(source: Source, msg: impl Into<String>) -> Error {
        Error::new(source, Inner::ConfigParser(msg.into()))
    }
    pub fn file_not_found(source: Source, msg: impl Into<String>, file: impl Into<String>) -> Error {
        Error::new(source, Inner::FileNotFound(msg.into(), file.into()))
    }
    pub fn render(source: Source, msg: impl Into<String>) -> Error {
        Error::new(source, Inner::Render(msg.into()))
    }
    pub fn zipper(source: Source, msg: impl Into<String>) -> Error {
        Error::new(source, Inner::Zipper(msg.into()))
    }
    pub fn book_option(source: Source, msg: impl Into<String>) -> Error {
        Error::new(source, Inner::BookOption(msg.into()))
    }
    pub fn invalid_option(source: Source, msg: impl Into<String>) -> Error {
