//! Runtime localization of messages (English and French).

use std::cell::RefCell;

thread_local! {
    static LANG: RefCell<String> = RefCell::new("en".to_string());
}

pub fn set_lang(lang: &str) {
    LANG.with(|l| *l.borrow_mut() = lang.to_string());
}

pub fn get_lang() -> String {
    LANG.with(|l| l.borrow().clone())
}

/// French translations of runtime messages (English text -> French text).
const FR: &[(&str, &str)] = &[
    ("Could not find file '{file}' for {msg}", "Impossible de trouver le fichier '{file}' pour {msg}"),
    ("Error parsing markdown: ", "Erreur à l'analyse du markdown : "),
    ("Error parsing configuration file: ", "Erreur à l'analyse du fichier de configuration : "),
    ("Error during rendering: ", "Erreur au rendu : "),
    ("Error during temporary files editing: ", "Erreur à l'édition de fichiers temporaires : "),
    ("Error converting BookOption: ", "Erreur à la conversion de BookOption : "),
    ("Error compiling template: ", "Erreur à la compilation du template : "),
    ("You must pass the name of a book configuration file.\nFor more information try --help.\n",
     "Vous devez passer le nom d'un fichier de configuration.\nPour plus d'informations essayez --help.\n"),
    ("book", "book"),
];

/// Translate a message template into the current runtime language.
pub fn lformat(msg: &str) -> String {
    let lang = get_lang();
    if lang.starts_with("fr") {
        for (en, fr) in FR {
            if *en == msg {
                return fr.to_string();
            }
        }
    }
    msg.to_string()
}

/// Translate and substitute `{name}` placeholders.
pub fn lformat2(msg: &str, args: &[(&str, &str)]) -> String {
    let mut s = lformat(msg);
    for (k, v) in args {
        s = s.replace(&format!("{{{}}}", k), v);
    }
    s
}
