    ("html_dir.css", "html.css"),
    ("html_dir.index.html", "html.dir.template"),
    ("html_dir.chapter.html", "html.dir.template"),
    ("epub.template", "epub.chapter.xhtml"),
    ("html.css.colours", "html.css.colors"),
    ("html.highlight_code", "rendering.highlight"),
    ("import_config", "import"),
];

/// Keys that have been removed
pub const DEPRECATED: &[&str] = &["crowbook.verbose", "tex.short", "nb_char", "html.crowbook_link"];

#[derive(Debug, Clone, PartialEq)]
pub enum BookOption {
    Str(String),
    Bool(bool),
    Int(i32),
    Float(f32),
    Path(String),
    StrVec(Vec<String>),
}

#[derive(Debug, Clone)]
pub struct BookOptions {
    options: HashMap<String, BookOption>,
    pub root: std::path::PathBuf,
    pub source: Source,
    /// warnings collected while setting options (renamed keys)
    pub warnings: Vec<String>,
}

pub fn find_def(key: &str) -> Option<&'static OptDef> {
    OPTIONS.iter().find(|o| o.key == key)
}

impl Default for BookOptions {
    fn default() -> Self {
        BookOptions::new()
    }
}

impl BookOptions {
    pub fn new() -> BookOptions {
        let mut options = HashMap::new();
        for def in OPTIONS {
            if let Some(d) = def.default {
                let value = match def.typ {
                    OptType::Meta | OptType::Str | OptType::Path | OptType::Tpl => {
                        // defaults are YAML literals
                        let y = yaml::load_from_str(d).ok().and_then(|mut v| v.pop());
                        let s = match y {
                            Some(Yaml::String(s)) => s,
                            Some(Yaml::Null) | None => String::new(),
                            Some(Yaml::Integer(i)) => i.to_string(),
                            Some(Yaml::Real(r)) => r,
                            Some(Yaml::Boolean(b)) => b.to_string(),
                            _ => d.to_string(),
                        };
                        if def.typ == OptType::Path {
                            BookOption::Path(s)
                        } else {
                            BookOption::Str(s)
                        }
                    }
                    OptType::Bool => BookOption::Bool(d == "true"),
                    OptType::Int => BookOption::Int(d.parse().unwrap_or(0)),
                    OptType::Float => BookOption::Float(d.parse().unwrap_or(0.0)),
                    OptType::StrVec => BookOption::StrVec(Vec::new()),
                };
                options.insert(def.key.to_string(), value);
            }
        }
        BookOptions {
            options,
            root: std::path::PathBuf::new(),
            source: Source::empty(),
            warnings: Vec::new(),
        }
    }

    /// Set an option from a key and a YAML value.
    /// Returns the previous value if any (unused).
    pub fn set_yaml(&mut self, key: &str, value: Yaml) -> Result<Option<BookOption>> {
        self.set_yaml_inner(key, value)
    }

    fn set_yaml_inner(&mut self, key: &str, value: Yaml) -> Result<Option<BookOption>> {
        if let Some((_, new)) = RENAMED.iter().find(|(old, _)| *old == key) {
            self.warnings.push(crate::lang::lformat2(
                "'{old_key}' has been deprecated, you should now use '{new_key}'",
                &[("old_key", key), ("new_key", new)],
            ));
            return self.set_yaml_inner(new, value);
        }
        if DEPRECATED.contains(&key) {
            return Err(Error::book_option(
                self.source.clone(),
                crate::lang::lformat2("key '{key}' has been deprecated.", &[("key", key)]),
            ));
        }
        if key == "import" {
            // handled by the caller (Book)
            return match value {
                Yaml::String(s) => Ok(self.options.insert(key.to_string(), BookOption::Path(s))),
                _ => Err(Error::book_option(
                    self.source.clone(),
                    format!("Expected a string as value for key {}, found {:?}", key, value),
                )),
            };
        }
        let def = match find_def(key) {
            Some(d) => d,
            None => {
                return Err(Error::book_option(
                    self.source.clone(),
                    crate::lang::lformat2("unrecognized key '{key}'", &[("key", key)]),
                ))
            }
        };
        let opt = match def.typ {
            OptType::Meta | OptType::Str | OptType::Path | OptType::Tpl => match value {
                Yaml::String(s) => {
                    if def.typ == OptType::Path {
                        BookOption::Path(s)
                    } else {
                        BookOption::Str(s)
                    }
                }
                _ => {
                    return Err(Error::book_option(
                        self.source.clone(),
                        format!("Expected a string as value for key {}, found {:?}", key, value),
                    ))
                }
            },
            OptType::StrVec => match value {
                Yaml::Array(ref v) => {
                    let mut res = Vec::new();
                    for item in v {
                        match item {
                            Yaml::String(s) => res.push(s.clone()),
                            _ => {
                                return Err(Error::book_option(
                                    self.source.clone(),
                                    format!("Expected a list of strings as value for key {}, found {:?}", key, value),
                                ))
                            }
                        }
                    }
                    BookOption::StrVec(res)
                }
                _ => {
                    return Err(Error::book_option(
                        self.source.clone(),
                        format!("Expected a list as value for key {}, found {:?}", key, value),
                    ))
                }
            },
            OptType::Bool => match value {
                Yaml::Boolean(b) => BookOption::Bool(b),
                _ => {
                    return Err(Error::book_option(
                        self.source.clone(),
                        format!("expected a boolean as value for key '{}', found {:?}", key, value),
                    ))
                }
            },
            OptType::Int => match value {
                Yaml::Integer(i) => BookOption::Int(i as i32),
                _ => {
                    return Err(Error::book_option(
                        self.source.clone(),
                        format!("expected an integer as value for key '{}', found {:?}", key, value),
                    ))
                }
            },
            OptType::Float => match value {
                Yaml::Real(ref r) => BookOption::Float(r.parse().unwrap_or(0.0)),
                Yaml::Integer(i) => BookOption::Float(i as f32),
                _ => {
                    return Err(Error::book_option(
                        self.source.clone(),
                        format!("expected a floating point number as value for key '{}', found {:?}", key, value),
                    ))
                }
            },
        };
        Ok(self.options.insert(key.to_string(), opt))
    }

    /// Set an option from a string value (parsed as YAML), as done by `--set`.
    pub fn set(&mut self, key: &str, value: &str) -> Result<Option<BookOption>> {
        let docs = yaml::load_from_str(value);
        match docs {
            Ok(mut docs) if docs.len() == 1 => {
                let v = docs.pop().unwrap();
                self.set_yaml(key, v)
            }
            _ => Err(Error::book_option(
                self.source.clone(),
                format!("value '{}' for key '{}' does not contain one and only one YAML value", value, key),
            )),
        }
    }

    pub fn get(&self, key: &str) -> Result<&BookOption> {
        self.options.get(key).ok_or_else(|| {
            Error::invalid_option(self.source.clone(), format!("option '{}' is not present", key))
        })
    }

    pub fn get_str(&self, key: &str) -> Result<&str> {
        match self.get(key)? {
            BookOption::Str(s) | BookOption::Path(s) => Ok(s),
            _ => Err(Error::invalid_option(self.source.clone(), format!("option '{}' is not a string", key))),
        }
    }

    pub fn get_path(&self, key: &str) -> Result<String> {
        match self.get(key)? {
            BookOption::Path(s) => {
                let p = std::path::Path::new(s);
                if p.is_absolute() || s.is_empty() {
                    Ok(s.clone())
                } else {
                    let full = self.root.join(s);
                    Ok(full.to_string_lossy().to_string())
                }
            }
            BookOption::Str(s) => Ok(s.clone()),
            _ => Err(Error::invalid_option(self.source.clone(), format!("option '{}' is not a path", key))),
        }
    }

    /// Get a path without joining with the root
    pub fn get_relative_path(&self, key: &str) -> Result<&str> {
        match self.get(key)? {
            BookOption::Path(s) | BookOption::Str(s) => Ok(s),
            _ => Err(Error::invalid_option(self.source.clone(), format!("option '{}' is not a path", key))),
        }
    }

    pub fn get_bool(&self, key: &str) -> Result<bool> {
        match self.get(key)? {
            BookOption::Bool(b) => Ok(*b),
            _ => Err(Error::invalid_option(self.source.clone(), format!("option '{}' is not a boolean", key))),
        }
    }

    pub fn get_i32(&self, key: &str) -> Result<i32> {
        match self.get(key)? {
            BookOption::Int(i) => Ok(*i),
            _ => Err(Error::invalid_option(self.source.clone(), format!("option '{}' is not an integer", key))),
        }
    }

    pub fn get_f32(&self, key: &str) -> Result<f32> {
        match self.get(key)? {
            BookOption::Float(f) => Ok(*f),
            _ => Err(Error::invalid_option(self.source.clone(), format!("option '{}' is not a float", key))),
        }
    }

    pub fn get_str_vec(&self, key: &str) -> Result<&Vec<String>> {
        match self.get(key)? {
            BookOption::StrVec(v) => Ok(v),
            _ => Err(Error::invalid_option(self.source.clone(), format!("option '{}' is not a list", key))),
        }
    }

    pub fn is_set(&self, key: &str) -> bool {
        self.options.contains_key(key)
    }

    pub fn remove(&mut self, key: &str) {
        self.options.remove(key);
    }

    /// Returns the type of an option, if it is a template path.
    pub fn is_template(key: &str) -> bool {
        find_def(key).map(|d| d.typ == OptType::Tpl).unwrap_or(false)
    }

    pub fn is_metadata(key: &str) -> bool {
        find_def(key).map(|d| d.typ == OptType::Meta).unwrap_or(false)
    }
}
''' % defs.rstrip('\n')
open('src/bookoptions.rs','w').write(src)
EOF
echo ok"}

