//! The AST produced by the Markdown parser.

#[derive(Debug, Clone, PartialEq)]
pub enum Token {
    /// Plain text
    Str(String),
    Paragraph(Vec<Token>),
    /// Header with level (1-6)
    Header(i32, Vec<Token>),
    Emphasis(Vec<Token>),
    Strong(Vec<Token>),
    Strikethrough(Vec<Token>),
    Superscript(Vec<Token>),
    Subscript(Vec<Token>),
    /// Inline code
    Code(String),
    BlockQuote(Vec<Token>),
    /// Code block: language, content
    CodeBlock(String, String),
    List(Vec<Token>),
    /// Ordered list with start number
    OrderedList(usize, Vec<Token>),
    Item(Vec<Token>),
    /// Task list item (checked, content)
    TaskItem(bool, Vec<Token>),
    /// Table: number of columns, rows
    Table(i32, Vec<Token>),
    TableHead(Vec<Token>),
    TableRow(Vec<Token>),
    TableCell(Vec<Token>),
    /// Footnote reference whose content has been resolved
    Footnote(Vec<Token>),
    Rule,
    SoftBreak,
    HardBreak,
    /// Link: url, title, content
    Link(String, String, Vec<Token>),
    /// Image: url, title, alt content
    Image(String, String, Vec<Token>),
    /// Image alone in its paragraph
    StandaloneImage(String, String, Vec<Token>),
    /// A description list
    DescriptionList(Vec<Token>),
    DescriptionItem(Vec<Token>),
    DescriptionTerm(Vec<Token>),
    DescriptionDetails(Vec<Token>),
    /// Annotation (used for proofreading); we never produce it
    Annotation(String, Vec<Token>),
}

impl Token {
    /// Returns the inner tokens, if any
    pub fn inner(&self) -> Option<&[Token]> {
        use Token::*;
        match self {
            Paragraph(v) | Header(_, v) | Emphasis(v) | Strong(v) | Strikethrough(v) | Superscript(v)
            | Subscript(v) | BlockQuote(v) | List(v) | OrderedList(_, v) | Item(v) | TaskItem(_, v)
            | Table(_, v) | TableHead(v) | TableRow(v) | TableCell(v) | Footnote(v) | Link(_, _, v)
            | Image(_, _, v) | StandaloneImage(_, _, v) | DescriptionList(v) | DescriptionItem(v)
            | DescriptionTerm(v) | DescriptionDetails(v) | Annotation(_, v) => Some(v),
            _ => None,
        }
    }

    pub fn inner_mut(&mut self) -> Option<&mut Vec<Token>> {
        use Token::*;
        match self {
            Paragraph(v) | Header(_, v) | Emphasis(v) | Strong(v) | Strikethrough(v) | Superscript(v)
            | Subscript(v) | BlockQuote(v) | List(v) | OrderedList(_, v) | Item(v) | TaskItem(_, v)
            | Table(_, v) | TableHead(v) | TableRow(v) | TableCell(v) | Footnote(v) | Link(_, _, v)
            | Image(_, _, v) | StandaloneImage(_, _, v) | DescriptionList(v) | DescriptionItem(v)
            | DescriptionTerm(v) | DescriptionDetails(v) | Annotation(_, v) => Some(v),
            _ => None,
        }
    }

    pub fn is_str(&self) -> bool {
        matches!(self, Token::Str(_))
    }

    pub fn is_image(&self) -> bool {
        matches!(self, Token::Image(..) | Token::StandaloneImage(..))
    }

    pub fn is_header(&self) -> bool {
        matches!(self, Token::Header(..))
    }

    pub fn is_code(&self) -> bool {
        matches!(self, Token::Code(_) | Token::CodeBlock(..))
    }

    /// Whether this token is a "container" (block that contains blocks)
    pub fn is_container(&self) -> bool {
        use Token::*;
        matches!(
            self,
            BlockQuote(_) | List(_) | OrderedList(..) | Item(_) | TaskItem(..) | Table(..) | TableHead(_) | TableRow(_)
                | TableCell(_) | Footnote(_) | DescriptionList(_) | DescriptionItem(_) | DescriptionTerm(_)
                | DescriptionDetails(_)
        )
    }
}
