/// Try to decode an entity reference starting at `s` (which starts with '&').
/// Returns the decoded string and the number of bytes consumed.
pub fn decode_entity(s: &str) -> Option<(String, usize)> {
    let bytes = s.as_bytes();
    if bytes.first() != Some(&b'&') {
        return None;
    }
    if bytes.get(1) == Some(&b'#') {
        // numeric
        let (hex, start) = if matches!(bytes.get(2), Some(b'x') | Some(b'X')) {
            (true, 3)
        } else {
            (false, 2)
        };
        let mut i = start;
        let mut value: u32 = 0;
        let mut ndigits = 0;
        while i < bytes.len() {
            let c = bytes[i];
            let d = if hex {
                (c as char).to_digit(16)
            } else {
                (c as char).to_digit(10)
            };
            match d {
                Some(d) => {
                    value = value.saturating_mul(if hex { 16 } else { 10 }).saturating_add(d);
                    ndigits += 1;
                    i += 1;
                }
                None => break,
            }
        }
        let max = if hex { 6 } else { 7 };
        if ndigits == 0 || ndigits > max || bytes.get(i) != Some(&b';') {
            return None;
        }
        let ch = if value == 0 || value > 0x10FFFF {
            '\u{FFFD}'
        } else {
            char::from_u32(value).unwrap_or('\u{FFFD}')
        };
        return Some((ch.to_string(), i + 1));
    }
    // named
    let mut i = 1;
    while i < bytes.len() && i < 40 && bytes[i].is_ascii_alphanumeric() {
        i += 1;
    }
    if i == 1 || bytes.get(i) != Some(&b';') {
        return None;
    }
    let name = &s[1..i];
    for (n, v) in ENTITIES {
        if *n == name {
            return Some((v.to_string(), i + 1));
        }
    }
    None
}
