                        content_indent = (p2.col - marker_col_start) + 1;
                        p2.skip_ws();
                    } else {
                        let ws = p2.indent();
                        if ws >= 5 {
                            p2.advance_cols(1);
                            content_indent = (p2.col - marker_col_start);
                        } else {
                            p2.advance_cols(ws);
                            content_indent = p2.col - marker_col_start;
                        }
                    }
                    let _ = spaces_after;
                    let indent_before = marker_col_start - line.col;
                    let content_indent = content_indent + indent_before;
                    // task list?
                    let mut task = None;
                    {
                        let r = p2.rest();
                        if r.len() >= 3 && r.as_bytes()[0] == b'[' && r.as_bytes()[2] == b']' {
                            let c = r.as_bytes()[1];
                            if (c == b' ' || c == b'x' || c == b'X')
                                && (r.len() == 3 || r.as_bytes()[3] == b' ' || r.as_bytes()[3] == b'\t')
                            {
                                task = Some(c != b' ');
                                p2.advance_bytes(3);
                                if p2.peek().is_some() {
                                    p2.skip_ws();
                                }
                            }
                        }
                    }
                    line = p2;
                    close_open_children_except_list(container);
                    // need a list container?
                    let need_new_list = match container.children.last() {
                        Some(Block {
                            kind:
                                Kind::List {
                                    ordered: o,
                                    marker: m,
                                    ..
                                },
                            open: true,
                            ..
                        }) => !(*o == ordered && *m == marker),
                        _ => true,
                    };
                    if need_new_list {
                        close_open_children(container);
                        container.children.push(Block::new(Kind::List {
                            ordered,
                            start,
                            marker,
                            tight: true,
                        }));
                    }
                    let list_idx = container.children.len() - 1;
                    let list = &mut container.children[list_idx];
                    // if there was a blank line between items, the list is loose
                    if list.last_line_blank && !list.children.is_empty() {
                        if let Kind::List { tight, .. } = &mut list.kind {
                            *tight = false;
                        }
                    }
                    list.last_line_blank = false;
                    close_open_children(list);
                    let mut item = Block::new(Kind::ListItem { content_indent, task });
                    if empty_item {
                        item.last_line_blank = true;
                    }
                    list.children.push(item);
                    path.push(list_idx);
                    path.push(list.children.len() - 1);
                    continue;
                }
            }
            // ATX heading
            if first == b'#' {
                if let Some((level, text)) = scan_atx_heading(rest) {
                    close_open_children(container);
                    container.children.push(Block::new(Kind::Heading { level, text }));
                    container.children.last_mut().unwrap().open = false;
                    return;
                }
            }
            // fenced code
            if first == b'`' || first == b'~' {
                let n = rest.bytes().take_while(|&b| b == first).count();
                if n >= 3 {
                    let info = rest[n..].trim();
                    if first == b'~' || !info.contains('`') {
                        close_open_children(container);
                        let info = unescape_info(info);
                        container.children.push(Block::new(Kind::FencedCode {
                            fence_char: first,
                            fence_len: n,
                            indent: probe.col - line.col,
                            info,
                            lines: Vec::new(),
                        }));
                        return;
                    }
                }
            }
            // HTML block
            if first == b'<' {
                let paragraph_open = container
                    .children
                    .last()
                    .map(|b| b.open && matches!(b.kind, Kind::Paragraph { .. }))
                    .unwrap_or(false);
                if let Some(kind) = scan_html_block_start(rest, paragraph_open) {
                    close_open_children(container);
                    let content = line.content();
                    let mut blk = Block::new(Kind::HtmlBlock {
                        kind,
                        lines: vec![content.clone()],
                    });
                    if kind < 6 && html_block_end(kind, &content) {
                        blk.open = false;
                    }
                    container.children.push(blk);
                    return;
                }
            }
            // setext heading underline (only if a paragraph is open in this container)
            if first == b'=' || first == b'-' {
                let paragraph_idx = container
                    .children
                    .iter()
                    .rposition(|b| b.open && matches!(b.kind, Kind::Paragraph { .. }));
                if let Some(pi) = paragraph_idx {
                    if pi == container.children.len() - 1 && !has_unmatched {
                        let n = rest.bytes().take_while(|&b| b == first).count();
                        if n > 0 && rest[n..].bytes().all(|b| b == b' ' || b == b'\t') {
                            // It's a setext heading
                            let para = container.children.pop().unwrap();
                            if let Kind::Paragraph { lines } = para.kind {
                                // link reference definitions at the start are extracted later;
                                // here we need to handle the case where the paragraph is only defs.
                                let (defs, remaining) = self.split_link_defs(&lines);
                                for (k, v) in defs {
                                    self.link_defs.entry(k).or_insert(v);
                                }
                                if remaining.is_empty() {
                                    // the underline becomes a paragraph (or thematic break for -)
                                    if first == b'-' && is_thematic_break(rest) {
                                        container.children.push(Block::new(Kind::ThematicBreak));
                                        container.children.last_mut().unwrap().open = false;
                                        return;
                                    }
                                    let mut p = Block::new(Kind::Paragraph {
                                        lines: vec![rest.trim().to_string()],
                                    });
                                    p.open = true;
                                    container.children.push(p);
                                    return;
                                }
                                let level = if first == b'=' { 1 } else { 2 };
                                let text = remaining.join("\n").trim().to_string();
                                let mut h = Block::new(Kind::Heading { level, text });
                                h.open = false;
                                container.children.push(h);
                                return;
                            }
                        }
                    }
                }
            }
            // thematic break
            if (first == b'*' || first == b'-' || first == b'_') && is_thematic_break(rest) {
                close_open_children(container);
                let mut b = Block::new(Kind::ThematicBreak);
                b.open = false;
                container.children.push(b);
                return;
            }
            break;
        }

        // Phase 3: add the line to a leaf
        let container = get_block_mut(doc, &path);
        let blank = line.is_blank();
        if blank {
            // blank line: close paragraph, mark
            if let Some(last) = container.children.last_mut() {
                if last.open && matches!(last.kind, Kind::Paragraph { .. }) {
                    last.open = false;
                }
            }
            mark_blank(doc, &path);
            return;
        }
        // paragraph continuation (possibly lazy)
        if line.indent() >= 4 {
            // indented code or lazy continuation
            let para_open = container
                .children
                .last()
                .map(|b| b.open && matches!(b.kind, Kind::Paragraph { .. }))
                .unwrap_or(false);
            if para_open {
                let mut l = Line { ..line };
                l.skip_ws();
                if let Some(Block {
                    kind: Kind::Paragraph { lines },
                    ..
                }) = container.children.last_mut()
                {
                    lines.push(l.rest().to_string());
                }
                clear_blank(doc, &path);
                return;
            }
            // lazy continuation into a deeper paragraph?
            if let Some(lines) = find_lazy_paragraph(doc) {
                if lazy_ok || true {
                    let mut l = Line { ..line };
                    l.skip_ws();
                    lines.push(l.rest().to_string());
                    return;
                }
            }
            line.advance_cols(4);
            close_open_children(container);
            container.children.push(Block::new(Kind::IndentedCode {
                lines: vec![line.content()],
            }));
            clear_blank(doc, &path);
            return;
        }
        let mut l = Line { ..line };
        l.skip_ws();
        let text = l.rest().to_string();
        // table start? (paragraph with one line followed by delimiter row)
        {
            let para_single = match container.children.last() {
                Some(Block {
                    kind: Kind::Paragraph { lines },
                    open: true,
                    ..
                }) if lines.len() == 1 => Some(lines[0].clone()),
                _ => None,
            };
            if let Some(header) = para_single {
                if let Some(aligns) = scan_table_delimiter(&text) {
                    let cells = split_table_row(&header);
                    if cells.len() == aligns.len() {
                        container.children.pop();
                        let mut t = Block::new(Kind::Table {
                            aligns,
                            rows: vec![cells],
                        });
                        t.open = true;
                        container.children.push(t);
                        return;
                    }
                }
            }
        }
        let para_open = container
            .children
            .last()
            .map(|b| b.open && matches!(b.kind, Kind::Paragraph { .. }))
            .unwrap_or(false);
        if para_open {
            if let Some(Block {
                kind: Kind::Paragraph { lines },
                ..
            }) = container.children.last_mut()
            {
                lines.push(text);
            }
            clear_blank(doc, &path);
            return;
        }
        // lazy continuation: is there an open paragraph deeper in an unmatched container?
        if let Some(lines) = find_lazy_paragraph(doc) {
            lines.push(text);
            return;
        }
        close_open_children(container);
        container.children.push(Block::new(Kind::Paragraph { lines: vec![text] }));
        clear_blank(doc, &path);
    }

    fn finalize_all(&mut self, b: &mut Block) {
        b.open = false;
        for c in b.children.iter_mut() {
            self.finalize_all(c);
        }
    }

    /// Extract link reference definitions from paragraphs
    fn extract_link_defs(&mut self, b: &mut Block) {
        let mut i = 0;
        while i < b.children.len() {
            let remove = {
                let child = &mut b.children[i];
                if let Kind::Paragraph { lines } = &child.kind {
                    let (defs, remaining) = self.split_link_defs(lines);
                    for (k, v) in defs {
                        self.link_defs.entry(k).or_insert(v);
                    }
                    if remaining.is_empty() {
                        true
                    } else {
                        child.kind = Kind::Paragraph { lines: remaining };
                        false
                    }
                } else {
                    false
                }
            };
            if remove {
                b.children.remove(i);
            } else {
                self.extract_link_defs(&mut b.children[i]);
                i += 1;
            }
        }
    }

    /// Split leading link reference definitions out of paragraph lines.
    fn split_link_defs(&self, lines: &[String]) -> (Vec<(String, LinkDef)>, Vec<String>) {
        let text = lines.join("\n");
        let mut defs = Vec::new();
        let mut pos = 0;
        loop {
            match scan_link_def(&text[pos..]) {
                Some((label, def, consumed)) => {
                    let key = normalize_label(&label);
                    if !key.is_empty() {
                        defs.push((key, def));
                    }
                    pos += consumed;
                    if pos >= text.len() {
                        break;
                    }
                }
                None => break,
            }
        }
        let remaining: Vec<String> = if pos >= text.len() {
            Vec::new()
        } else {
            text[pos..].split('\n').map(|s| s.to_string()).collect()
        };
        (defs, remaining)
    }

    fn collect_footnotes(&mut self, b: &mut Block, out: &mut Vec<(String, Block)>) {
        let mut i = 0;
        while i < b.children.len() {
            if matches!(b.children[i].kind, Kind::FootnoteDef { .. }) {
                let blk = b.children.remove(i);
                let label = if let Kind::FootnoteDef { label } = &blk.kind {
                    label.clone()
                } else {
                    unreachable!()
                };
                out.push((label, blk));
            } else {
                self.collect_footnotes(&mut b.children[i], out);
                i += 1;
            }
        }
    }

    // ----------------------------------------------------------------
    // Conversion to tokens
    // ----------------------------------------------------------------

    fn blocks_to_tokens(&self, blocks: &[Block], tight: bool) -> Vec<Token> {
        let mut out = Vec::new();
        for b in blocks {
            match &b.kind {
                Kind::Document => {}
                Kind::Paragraph { lines } => {
                    let text = lines.iter().map(|l| l.trim_start()).collect::<Vec<_>>().join("\n");
                    let inlines = self.parse_inlines(&text);
                    if tight {
                        out.extend(inlines);
                    } else {
                        out.push(Token::Paragraph(inlines));
                    }
                }
                Kind::Heading { level, text } => {
                    let inlines = self.parse_inlines(text);
                    out.push(Token::Header(*level as i32, inlines));
                }
                Kind::ThematicBreak => out.push(Token::Rule),
                Kind::IndentedCode { lines } => {
                    // remove trailing blank lines
                    let mut ls = lines.clone();
                    while ls.last().map(|l| l.trim().is_empty()).unwrap_or(false) {
                        ls.pop();
                    }
                    let mut code = ls.join("\n");
                    code.push('\n');
                    out.push(Token::CodeBlock(String::new(), code));
                }
                Kind::FencedCode { info, lines, .. } => {
                    let mut code = lines.join("\n");
                    if !lines.is_empty() {
                        code.push('\n');
                    }
                    let lang = info.split_whitespace().next().unwrap_or("").to_string();
                    out.push(Token::CodeBlock(lang, code));
                }
                Kind::HtmlBlock { lines, .. } => {
                    let mut html = lines.join("\n");
                    html.push('\n');
                    if self.opts.html_as_text {
                        out.push(Token::Str(html));
                    } else {
                        out.push(Token::Str(html));
                    }
                }
                Kind::BlockQuote => {
                    let inner = self.blocks_to_tokens(&b.children, false);
                    out.push(Token::BlockQuote(inner));
                }
                Kind::List {
                    ordered,
                    start,
                    tight: list_tight,
                    ..
                } => {
                    let mut items = Vec::new();
                    for item in &b.children {
                        if let Kind::ListItem { task, .. } = &item.kind {
                            let inner = self.blocks_to_tokens(&item.children, *list_tight);
                            match task {
                                Some(checked) => items.push(Token::TaskItem(*checked, inner)),
                                None => items.push(Token::Item(inner)),
                            }
                        }
                    }
                    if *ordered {
                        out.push(Token::OrderedList(*start, items));
                    } else {
                        out.push(Token::List(items));
                    }
                }
                Kind::ListItem { .. } => {}
                Kind::Table { aligns, rows } => {
                    let mut trows = Vec::new();
                    for (i, row) in rows.iter().enumerate() {
                        let mut cells = Vec::new();
                        for cell in row {
                            cells.push(Token::TableCell(self.parse_inlines(cell.trim())));
                        }
                        if i == 0 {
                            trows.push(Token::TableHead(cells));
                        } else {
                            trows.push(Token::TableRow(cells));
                        }
                    }
                    out.push(Token::Table(aligns.len() as i32, trows));
                }
                Kind::FootnoteDef { .. } => {}
            }
        }
        out
    }

    // ----------------------------------------------------------------
    // Inline parsing
    // ----------------------------------------------------------------

    pub fn parse_inlines(&self, text: &str) -> Vec<Token> {
        let mut ip = InlineParser::new(text, self);
        ip.run()
    }
}

fn get_block_mut<'a>(doc: &'a mut Block, path: &[usize]) -> &'a mut Block {
    let mut cur = doc;
    for &i in path {
        cur = &mut cur.children[i];
    }
    cur
}

fn close_open_children(b: &mut Block) {
    for c in b.children.iter_mut() {
        if c.open {
            close_recursive(c);
        }
    }
}

fn close_recursive(b: &mut Block) {
    b.open = false;
    for c in b.children.iter_mut() {
        if c.open {
            close_recursive(c);
        }
    }
}

/// Close open children except a trailing open list (so that a new item can be added)
fn close_open_children_except_list(b: &mut Block) {
    let n = b.children.len();
    for (i, c) in b.children.iter_mut().enumerate() {
        if c.open {
            if i == n - 1 && matches!(c.kind, Kind::List { .. }) {
                // keep list open but close its items' deep open children later
                continue;
            }
            close_recursive(c);
        }
    }
}

fn mark_blank(doc: &mut Block, path: &[usize]) {
    // mark last_line_blank on the deepest matched container and its open descendants' lists
    let mut cur = &mut *doc;
    for &i in path {
        cur.last_line_blank = true;
        cur = &mut cur.children[i];
    }
    cur.last_line_blank = true;
    // also mark open lists inside (so that following items are loose)
    fn mark_open(b: &mut Block) {
        b.last_line_blank = true;
        for c in b.children.iter_mut() {
            if c.open {
                mark_open(c);
            }
        }
    }
    for c in cur.children.iter_mut() {
        if c.open {
            mark_open(c);
        }
    }
}

fn clear_blank(doc: &mut Block, path: &[usize]) {
    let mut cur = &mut *doc;
    for &i in path {
        cur.last_line_blank = false;
        cur = &mut cur.children[i];
    }
    cur.last_line_blank = false;
}

/// Find an open paragraph at the deepest open position (for lazy continuation)
fn find_lazy_paragraph(doc: &mut Block) -> Option<&mut Vec<String>> {
    let mut cur = doc;
    loop {
        let idx = cur.children.iter().rposition(|c| c.open)?;
        let child = &mut cur.children[idx];
        if let Kind::Paragraph { .. } = child.kind {
            if let Kind::Paragraph { lines } = &mut child.kind {
                return Some(lines);
            }
        }
        if !child.is_container() {
            return None;
        }
        cur = child;
    }
}

fn is_thematic_break(s: &str) -> bool {
    let s = s.trim_end();
    let first = match s.bytes().next() {
        Some(b) => b,
        None => return false,
    };
    if first != b'*' && first != b'-' && first != b'_' {
        return false;
    }
    let mut count = 0;
    for b in s.bytes() {
        if b == first {
            count += 1;
        } else if b != b' ' && b != b'\t' {
            return false;
        }
    }
    count >= 3
}

/// Returns (ordered, start, marker, marker_len_bytes, spaces_after)
fn scan_list_marker(s: &str) -> Option<(bool, usize, u8, usize, usize)> {
    let bytes = s.as_bytes();
    if bytes.is_empty() {
        return None;
    }
    let c = bytes[0];
    if c == b'-' || c == b'*' || c == b'+' {
        if bytes.len() == 1 || bytes[1] == b' ' || bytes[1] == b'\t' {
            return Some((false, 0, c, 1, 0));
        }
        return None;
    }
    if c.is_ascii_digit() {
        let mut i = 0;
        while i < bytes.len() && bytes[i].is_ascii_digit() && i < 10 {
            i += 1;
        }
        if i > 9 {
            return None;
        }
        if i < bytes.len() && (bytes[i] == b'.' || bytes[i] == b')') {
            if i + 1 == bytes.len() || bytes[i + 1] == b' ' || bytes[i + 1] == b'\t' {
                let start: usize = s[..i].parse().unwrap_or(0);
                return Some((true, start, bytes[i], i + 1, 0));
            }
        }
    }
    None
}

fn scan_atx_heading(s: &str) -> Option<(usize, String)> {
    let bytes = s.as_bytes();
    let mut level = 0;
    while level < bytes.len() && bytes[level] == b'#' {
        level += 1;
    }
    if level == 0 || level > 6 {
        return None;
    }
    if level < bytes.len() && bytes[level] != b' ' && bytes[level] != b'\t' {
        return None;
    }
    let rest = s[level..].trim();
    // remove closing sequence
    let mut text = rest.to_string();
    let trimmed = text.trim_end_matches('#');
    if trimmed.len() != text.len() {
        if trimmed.is_empty() {
            text = String::new();
        } else if trimmed.ends_with(' ') || trimmed.ends_with('\t') {
            text = trimmed.trim_end().to_string();
        }
    }
    Some((level, text))
}

fn unescape_info(s: &str) -> String {
    // backslash escapes and entities in info strings
    let mut out = String::new();
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'\\' && i + 1 < bytes.len() && bytes[i + 1].is_ascii_punctuation() {
            out.push(bytes[i + 1] as char);
            i += 2;
        } else if bytes[i] == b'&' {
            if let Some((v, n)) = decode_entity(&s[i..]) {
                out.push_str(&v);
                i += n;
            } else {
                out.push('&');
                i += 1;
            }
        } else {
            let ch = s[i..].chars().next().unwrap();
            out.push(ch);
            i += ch.len_utf8();
        }
    }
    out
}

const HTML_BLOCK_TAGS: &[&str] = &[
    "address", "article", "aside", "base", "basefont", "blockquote", "body", "caption", "center", "col",
    "colgroup", "dd", "details", "dialog", "dir", "div", "dl", "dt", "fieldset", "figcaption", "figure",
    "footer", "form", "frame", "frameset", "h1", "h2", "h3", "h4", "h5", "h6", "head", "header", "hr",
    "html", "iframe", "legend", "li", "link", "main", "menu", "menuitem", "nav", "noframes", "ol",
    "optgroup", "option", "p", "param", "search", "section", "summary", "table", "tbody", "td", "tfoot", "th",
    "thead", "title", "tr", "track", "ul",
];

fn scan_html_block_start(s: &str, paragraph_open: bool) -> Option<u8> {
    let lower = s.to_ascii_lowercase();
    let lb = lower.as_bytes();
    if lb.len() < 2 {
        return None;
    }
    // type 1
    for tag in &["<script", "<pre", "<style", "<textarea"] {
        if lower.starts_with(tag) {
            let after = lb.get(tag.len()).copied();
            if after.is_none() || after == Some(b' ') || after == Some(b'\t') || after == Some(b'>') {
                return Some(1);
            }
        }
    }
    if lower.starts_with("<!--") {
        return Some(2);
    }
    if lower.starts_with("<?") {
        return Some(3);
    }
    if s.starts_with("<!") && s.len() > 2 && s.as_bytes()[2].is_ascii_alphabetic() {
        return Some(4);
    }
    if lower.starts_with("<![cdata[") {
        return Some(5);
    }
    // type 6
    let mut i = 1;
    let closing = lb.get(1) == Some(&b'/');
    if closing {
        i = 2;
    }
    let start = i;
    while i < lb.len() && (lb[i].is_ascii_alphanumeric()) {
        i += 1;
    }
    if i > start {
        let name = &lower[start..i];
        let after = lb.get(i).copied();
        let ok_after = after.is_none()
            || after == Some(b' ')
            || after == Some(b'\t')
            || after == Some(b'>')
            || (after == Some(b'/') && lb.get(i + 1) == Some(&b'>'));
        if ok_after && HTML_BLOCK_TAGS.contains(&name) {
            return Some(6);
        }
        // type 7: complete open or closing tag alone on the line, not interrupting a paragraph
        if !paragraph_open {
            if let Some(end) = scan_html_tag(s) {
                if s[end..].bytes().all(|b| b == b' ' || b == b'\t') {
                    return Some(7);
                }
            }
        }
    }
    None
}

fn html_block_end(kind: u8, line: &str) -> bool {
    let lower = line.to_ascii_lowercase();
    match kind {
        1 => lower.contains("</script>") || lower.contains("</pre>") || lower.contains("</style>") || lower.contains("</textarea>"),
        2 => lower.contains("-->"),
        3 => lower.contains("?>"),
        4 => lower.contains('>'),
        5 => lower.contains("]]>"),
        _ => false,
    }
}

/// Scan an HTML tag (open or closing) at the start of `s`; returns the end offset.
pub fn scan_html_tag(s: &str) -> Option<usize> {
    let b = s.as_bytes();
    if b.first() != Some(&b'<') {
        return None;
    }
    let mut i = 1;
    let closing = b.get(1) == Some(&b'/');
    if closing {
        i = 2;
    }
    // tag name
    if i >= b.len() || !b[i].is_ascii_alphabetic() {
        return None;
    }
    while i < b.len() && (b[i].is_ascii_alphanumeric() || b[i] == b'-') {
        i += 1;
    }
    if closing {
        // optional whitespace then >
        while i < b.len() && (b[i] == b' ' || b[i] == b'\t' || b[i] == b'\n') {
            i += 1;
        }
        if b.get(i) == Some(&b'>') {
            return Some(i + 1);
        }
        return None;
    }
    // attributes
    loop {
        let ws_start = i;
        while i < b.len() && (b[i] == b' ' || b[i] == b'\t' || b[i] == b'\n') {
            i += 1;
        }
        if i >= b.len() {
            return None;
        }
        if b[i] == b'>' {
            return Some(i + 1);
        }
        if b[i] == b'/' {
            if b.get(i + 1) == Some(&b'>') {
                return Some(i + 2);
            }
            return None;
        }
        if i == ws_start {
            return None; // attribute must be preceded by whitespace
        }
        // attribute name
        if !(b[i].is_ascii_alphabetic() || b[i] == b'_' || b[i] == b':') {
            return None;
        }
        i += 1;
        while i < b.len() && (b[i].is_ascii_alphanumeric() || b[i] == b'_' || b[i] == b':' || b[i] == b'.' || b[i] == b'-') {
            i += 1;
        }
        // optional value
        let mut j = i;
        while j < b.len() && (b[j] == b' ' || b[j] == b'\t' || b[j] == b'\n') {
            j += 1;
        }
        if b.get(j) == Some(&b'=') {
            j += 1;
            while j < b.len() && (b[j] == b' ' || b[j] == b'\t' || b[j] == b'\n') {
                j += 1;
            }
            if j >= b.len() {
                return None;
            }
            match b[j] {
                b'"' => {
                    j += 1;
                    while j < b.len() && b[j] != b'"' {
                        j += 1;
                    }
                    if j >= b.len() {
                        return None;
                    }
                    j += 1;
                }
                b'\'' => {
                    j += 1;
                    while j < b.len() && b[j] != b'\'' {
                        j += 1;
                    }
                    if j >= b.len() {
                        return None;
                    }
                    j += 1;
                }
                _ => {
                    let start = j;
                    while j < b.len()
                        && !matches!(b[j], b' ' | b'\t' | b'\n' | b'"' | b'\'' | b'=' | b'<' | b'>' | b'`')
                    {
                        j += 1;
                    }
                    if j == start {
                        return None;
                    }
                }
            }
            i = j;
        }
    }
}

fn scan_table_delimiter(s: &str) -> Option<Vec<Align>> {
    let s = s.trim();
    if !s.contains('-') {
        return None;
    }
    let cells = split_table_row(s);
    if cells.is_empty() {
        return None;
    }
    let mut aligns = Vec::new();
    for c in cells {
        let c = c.trim();
        if c.is_empty() {
            return None;
        }
        let left = c.starts_with(':');
        let right = c.ends_with(':');
        let inner = c.trim_start_matches(':').trim_end_matches(':');
        if inner.is_empty() || !inner.bytes().all(|b| b == b'-') {
            return None;
        }
        aligns.push(match (left, right) {
            (true, true) => Align::Center,
            (true, false) => Align::Left,
            (false, true) => Align::Right,
            _ => Align::None,
        });
    }
    // a delimiter row must contain a pipe or be a single column with dashes? GFM requires pipes
    // unless... we require at least one pipe for multi-col; single col without pipes is ambiguous
    if !s.contains('|') {
        return None;
    }
    Some(aligns)
}

/// Split a table row into cells (handling escaped pipes and code spans)
fn split_table_row(s: &str) -> Vec<String> {
    let mut s = s.trim();
    if s.starts_with('|') {
        s = &s[1..];
    }
    if s.ends_with('|') && !s.ends_with("\\|") {
        s = &s[..s.len() - 1];
    }
    let mut cells = Vec::new();
    let mut cur = String::new();
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        let c = bytes[i];
        if c == b'\\' && i + 1 < bytes.len() && bytes[i + 1] == b'|' {
            cur.push('|');
            i += 2;
            continue;
        }
        if c == b'|' {
            cells.push(cur.trim().to_string());
            cur = String::new();
            i += 1;
            continue;
        }
        let ch = s[i..].chars().next().unwrap();
        cur.push(ch);
        i += ch.len_utf8();
    }
    cells.push(cur.trim().to_string());
    cells
}

fn starts_block(probe: &Line) -> bool {
    let rest = probe.rest();
    let first = match probe.peek() {
        Some(b) => b,
        None => return true,
    };
    if first == b'>' {
        return true;
    }
    if first == b'#' && scan_atx_heading(rest).is_some() {
        return true;
    }
    if (first == b'`' || first == b'~') && rest.bytes().take_while(|&b| b == first).count() >= 3 {
        return true;
    }
    if is_thematic_break(rest) {
        return true;
    }
    if scan_list_marker(rest).is_some() {
        return true;
    }
    if first == b'<' && scan_html_block_start(rest, false).is_some() {
        return true;
    }
    false
}

/// Scan a link reference definition at the start of `s`. Returns (label, def, bytes consumed).
fn scan_link_def(s: &str) -> Option<(String, LinkDef, usize)> {
    let b = s.as_bytes();
    let mut i = 0;
    // up to 3 spaces
    while i < b.len() && b[i] == b' ' && i < 3 {
        i += 1;
    }
    if b.get(i) != Some(&b'[') {
        return None;
    }
    // label
    let label_start = i + 1;
    let mut j = label_start;
    let mut depth_ok = true;
    while j < b.len() {
        match b[j] {
            b'\\' => {
                j += 2;
                continue;
            }
            b'[' => {
                depth_ok = false;
                break;
            }
            b']' => break,
            _ => j += 1,
        }
    }
    if !depth_ok || j >= b.len() || j - label_start > 999 {
        return None;
    }
    let label = &s[label_start..j];
    if label.trim().is_empty() {
        return None;
    }
    if label.starts_with('^') {
        return None;
    }
    i = j + 1;
    if b.get(i) != Some(&b':') {
        return None;
    }
    i += 1;
    // whitespace incl. at most one newline
    let mut newlines = 0;
    while i < b.len() && (b[i] == b' ' || b[i] == b'\t' || b[i] == b'\n') {
        if b[i] == b'\n' {
            newlines += 1;
            if newlines > 1 {
                return None;
            }
        }
        i += 1;
    }
    // destination
    let (url, end) = scan_link_destination(&s[i..])?;
    if end == 0 && !s[i..].starts_with("<>") {
        return None;
    }
    i += end;
    let after_dest = i;
    // optional title
    let mut j = i;
    let mut nl = 0;
    while j < b.len() && (b[j] == b' ' || b[j] == b'\t' || b[j] == b'\n') {
        if b[j] == b'\n' {
            nl += 1;
        }
        j += 1;
    }
    let mut title = String::new();
    let mut consumed_title = false;
    if j > i && j < b.len() && nl <= 1 && (b[j] == b'"' || b[j] == b'\'' || b[j] == b'(') {
        if let Some((t, tend)) = scan_link_title(&s[j..]) {
            // after title: only whitespace until end of line
            let k = j + tend;
            let mut m = k;
            while m < b.len() && (b[m] == b' ' || b[m] == b'\t') {
                m += 1;
            }
            if m >= b.len() || b[m] == b'\n' {
                title = t;
                i = m;
                consumed_title = true;
            }
        }
    }
    if !consumed_title {
        // rest of line after destination must be blank
        let mut m = after_dest;
        while m < b.len() && (b[m] == b' ' || b[m] == b'\t') {
            m += 1;
        }
        if m < b.len() && b[m] != b'\n' {
            return None;
        }
        i = m;
    }
    // consume the newline
    if i < b.len() && b[i] == b'\n' {
        i += 1;
    }
    Some((label.to_string(), LinkDef { url: unescape_string(&url), title: unescape_string(&title) }, i))
}

/// Scan a link destination. Returns (raw destination, bytes consumed).
fn scan_link_destination(s: &str) -> Option<(String, usize)> {
    let b = s.as_bytes();
    if b.is_empty() {
        return None;
    }
    if b[0] == b'<' {
        let mut i = 1;
        while i < b.len() {
            match b[i] {
                b'\\' => i += 2,
                b'>' => return Some((s[1..i].to_string(), i + 1)),
                b'<' | b'\n' => return None,
                _ => i += 1,
            }
        }
        return None;
    }
    let mut i = 0;
    let mut depth = 0i32;
    while i < b.len() {
        let c = b[i];
        if c == b'\\' && i + 1 < b.len() && b[i + 1].is_ascii_punctuation() {
            i += 2;
            continue;
        }
        if c == b'(' {
            depth += 1;
            if depth > 32 {
                return None;
            }
        } else if c == b')' {
            if depth == 0 {
                break;
            }
            depth -= 1;
        } else if c <= b' ' || c == 0x7f {
            break;
        }
        i += 1;
    }
    if depth != 0 {
        return None;
    }
    Some((s[..i].to_string(), i))
}

fn scan_link_title(s: &str) -> Option<(String, usize)> {
    let b = s.as_bytes();
    let open = *b.first()?;
    let close = match open {
        b'"' => b'"',
        b'\'' => b'\'',
        b'(' => b')',
        _ => return None,
    };
    let mut i = 1;
    while i < b.len() {
        let c = b[i];
        if c == b'\\' && i + 1 < b.len() && b[i + 1].is_ascii_punctuation() {
            i += 2;
            continue;
        }
        if c == close {
            return Some((s[1..i].to_string(), i + 1));
        }
        if open == b'(' && c == b'(' {
            return None;
        }
        i += 1;
    }
    None
}

/// Process backslash escapes and entities in a string (used for URLs and titles)
pub fn unescape_string(s: &str) -> String {
    let mut out = String::new();
    let b = s.as_bytes();
    let mut i = 0;
    while i < b.len() {
        if b[i] == b'\\' && i + 1 < b.len() && b[i + 1].is_ascii_punctuation() {
            out.push(b[i + 1] as char);
            i += 2;
        } else if b[i] == b'&' {
            if let Some((v, n)) = decode_entity(&s[i..]) {
                out.push_str(&v);
                i += n;
            } else {
                out.push('&');
                i += 1;
            }
        } else {
            let ch = s[i..].chars().next().unwrap();
            out.push(ch);
            i += ch.len_utf8();
        }
    }
    out
}

// ====================================================================
// Inline parser
// ====================================================================

#[derive(Debug, Clone)]
enum Inline {
    Text(String),
    Code(String),
    SoftBreak,
    HardBreak,
    /// delimiter run: char, count, can_open, can_close, original position (node index)
    Delim {
        ch: u8,
        count: usize,
        orig_count: usize,
        can_open: bool,
        can_close: bool,
        active: bool,
    },
    /// Opening bracket for link/image: is_image, active
    Bracket {
        image: bool,
        active: bool,
        /// byte position in source just after the bracket
        pos: usize,
    },
    Link(String, String, Vec<Inline>),
    Image(String, String, Vec<Inline>),
    FootnoteRef(String),
    Emph(Vec<Inline>),
    Strong(Vec<Inline>),
    Strike(Vec<Inline>),
    Sup(Vec<Inline>),
    Sub(Vec<Inline>),
}

struct InlineParser<'a> {
    text: &'a str,
    bytes: &'a [u8],
    pos: usize,
    nodes: Vec<Inline>,
    parser: &'a Parser,
}

fn is_punctuation(c: char) -> bool {
    c.is_ascii_punctuation()
        || matches!(
            c,
            '\u{2010}'..='\u{2027}' | '\u{2030}'..='\u{205E}' | '\u{00A1}' | '\u{00A7}' | '\u{00AB}' | '\u{00B6}' | '\u{00B7}' | '\u{00BB}' | '\u{00BF}' | '\u{3000}'..='\u{303F}' | '\u{FF01}'..='\u{FF0F}' | '\u{FF1A}'..='\u{FF20}' | '\u{FF3B}'..='\u{FF40}' | '\u{FF5B}'..='\u{FF65}' | '\u{2E00}'..='\u{2E7F}' | '\u{00A2}'..='\u{00A9}' | '\u{00AC}' | '\u{00AE}'..='\u{00B1}' | '\u{00B4}' | '\u{00B8}' | '\u{00D7}' | '\u{00F7}' | '\u{2190}'..='\u{23FF}' | '\u{2500}'..='\u{27BF}' | '\u{2900}'..='\u{2BFF}'
        )
        || (!c.is_alphanumeric() && !c.is_whitespace() && (c as u32) > 127 && is_symbol_or_punct(c))
}

fn is_symbol_or_punct(c: char) -> bool {
    // approximation for general categories P* and S*
    !c.is_alphanumeric() && !c.is_whitespace() && !c.is_control()
}

impl<'a> InlineParser<'a> {
    fn new(text: &'a str, parser: &'a Parser) -> InlineParser<'a> {
        InlineParser {
            text,
            bytes: text.as_bytes(),
            pos: 0,
            nodes: Vec::new(),
            parser,
        }
    }

    fn push_text(&mut self, s: &str) {
        if s.is_empty() {
            return;
        }
        if let Some(Inline::Text(t)) = self.nodes.last_mut() {
            t.push_str(s);
        } else {
            self.nodes.push(Inline::Text(s.to_string()));
        }
    }

    fn run(&mut self) -> Vec<Token> {
        self.parse_all();
        self.process_emphasis(0);
        let nodes = std::mem::take(&mut self.nodes);
        self.to_tokens(nodes)
    }

    fn parse_all(&mut self) {
        let n = self.bytes.len();
        let mut text_start = self.pos;
        while self.pos < n {
            let c = self.bytes[self.pos];
            match c {
                b'\\' => {
                    self.flush_text(text_start);
                    if self.pos + 1 < n && self.bytes[self.pos + 1] == b'\n' {
                        // hard break
                        self.nodes.push(Inline::HardBreak);
                        self.pos += 2;
                        self.skip_line_start_ws();
                    } else if self.pos + 1 < n && self.bytes[self.pos + 1].is_ascii_punctuation() {
                        let ch = self.bytes[self.pos + 1] as char;
                        self.push_text(&ch.to_string());
                        self.pos += 2;
                    } else {
                        self.push_text("\\");
                        self.pos += 1;
                    }
                    text_start = self.pos;
                }
                b'`' => {
                    self.flush_text(text_start);
                    self.parse_code_span();
                    text_start = self.pos;
                }
                b'*' | b'_' | b'~' | b'^' => {
                    if c == b'^' && !self.parser.opts.superscript {
                        self.pos += 1;
                        continue;
                    }
                    if c == b'~' && self.parser.opts.superscript {
                        // with superscript option, ~ is subscript (single) — but ~~ still strike
                    }
                    self.flush_text(text_start);
                    self.parse_delim(c);
                    text_start = self.pos;
                }
                b'[' => {
                    self.flush_text(text_start);
                    // footnote reference?
                    if self.pos + 1 < n && self.bytes[self.pos + 1] == b'^' {
                        if let Some(end) = self.scan_footnote_label(self.pos + 2) {
                            let label = &self.text[self.pos + 2..end];
                            // only if not followed by ':' (that'd be a definition, handled at block level)
                            self.nodes.push(Inline::FootnoteRef(label.to_string()));
                            self.pos = end + 1;
                            text_start = self.pos;
                            continue;
                        }
                    }
                    self.nodes.push(Inline::Bracket {
                        image: false,
                        active: true,
                        pos: self.pos + 1,
                    });
                    self.pos += 1;
                    text_start = self.pos;
                }
                b'!' => {
                    if self.pos + 1 < n && self.bytes[self.pos + 1] == b'[' {
                        self.flush_text(text_start);
                        self.nodes.push(Inline::Bracket {
                            image: true,
                            active: true,
                            pos: self.pos + 2,
                        });
                        self.pos += 2;
                        text_start = self.pos;
                    } else {
                        self.pos += 1;
                    }
                }
                b']' => {
                    self.flush_text(text_start);
                    self.pos += 1;
                    self.close_bracket();
                    text_start = self.pos;
                }
                b'<' => {
                    self.flush_text(text_start);
                    if !self.parse_angle() {
                        self.push_text("<");
                        self.pos += 1;
                    }
                    text_start = self.pos;
                }
                b'&' => {
                    self.flush_text(text_start);
                    if let Some((v, len)) = decode_entity(&self.text[self.pos..]) {
                        self.push_text(&v);
                        self.pos += len;
                    } else {
                        self.push_text("&");
                        self.pos += 1;
                    }
                    text_start = self.pos;
                }
                b'\n' => {
                    // soft or hard break
                    let mut end = self.pos;
                    // count trailing spaces
                    let mut spaces = 0;
                    while end > text_start && self.bytes[end - 1] == b' ' {
                        end -= 1;
                        spaces += 1;
                    }
                    self.flush_text_range(text_start, end);
                    if spaces >= 2 {
                        self.nodes.push(Inline::HardBreak);
                    } else {
                        self.nodes.push(Inline::SoftBreak);
                    }
                    self.pos += 1;
                    self.skip_line_start_ws();
                    text_start = self.pos;
                }
                b'h' | b'w' | b'm' | b'f' | b'x' | b'H' | b'W' | b'M' | b'F' | b'X' => {
                    // possible extended autolink
                    if let Some((url, display_len, kind)) = self.scan_extended_autolink() {
                        self.flush_text(text_start);
                        let disp = &self.text[self.pos..self.pos + display_len];
                        let href = match kind {
                            0 => url.clone(),
                            1 => format!("http://{}", url),
                            _ => url.clone(),
                        };
                        self.nodes.push(Inline::Link(href, String::new(), vec![Inline::Text(disp.to_string())]));
                        self.pos += display_len;
                        text_start = self.pos;
                    } else {
                        self.pos += 1;
                    }
                }
                b'@' => {
                    // email autolink: look back for the start of the email
                    if let Some((start, end)) = self.scan_email_autolink(text_start) {
                        self.flush_text_range(text_start, start);
                        let email = &self.text[start..end];
                        self.nodes.push(Inline::Link(
                            format!("mailto:{}", email),
                            String::new(),
                            vec![Inline::Text(email.to_string())],
                        ));
                        self.pos = end;
                        text_start = self.pos;
                    } else {
                        self.pos += 1;
                    }
                }
                _ => {
                    self.pos += 1;
                }
            }
        }
        // trailing text: strip trailing spaces at end of paragraph
        let mut end = n;
        while end > text_start && (self.bytes[end - 1] == b' ' || self.bytes[end - 1] == b'\t') {
            end -= 1;
        }
        self.flush_text_range(text_start, end);
    }

    fn skip_line_start_ws(&mut self) {
        while self.pos < self.bytes.len() && (self.bytes[self.pos] == b' ' || self.bytes[self.pos] == b'\t') {
            self.pos += 1;
        }
    }

    fn flush_text(&mut self, start: usize) {
        let end = self.pos;
        self.flush_text_range(start, end);
    }

    fn flush_text_range(&mut self, start: usize, end: usize) {
        if end > start {
            let s = &self.text[start..end];
            self.push_text(s);
        }
    }

    fn scan_footnote_label(&self, start: usize) -> Option<usize> {
        let mut i = start;
        while i < self.bytes.len() {
            let c = self.bytes[i];
            if c == b']' {
                return if i > start { Some(i) } else { None };
            }
            if c == b'[' || c == b' ' || c == b'\t' || c == b'\n' {
                return None;
            }
            i += 1;
        }
        None
    }

    fn parse_code_span(&mut self) {
        let n = self.bytes.len();
        let start = self.pos;
        let mut ticks = 0;
        while self.pos < n && self.bytes[self.pos] == b'`' {
            ticks += 1;
            self.pos += 1;
        }
        // find closing run of the same length
        let mut i = self.pos;
        while i < n {
            if self.bytes[i] == b'`' {
                let mut j = i;
                while j < n && self.bytes[j] == b'`' {
                    j += 1;
                }
                if j - i == ticks {
                    let mut content = self.text[self.pos..i].replace('\n', " ");
                    if content.len() >= 2
                        && content.starts_with(' ')
                        && content.ends_with(' ')
                        && !content.bytes().all(|b| b == b' ')
                    {
                        content = content[1..content.len() - 1].to_string();
                    }
                    self.nodes.push(Inline::Code(content));
                    self.pos = j;
                    return;
                }
                i = j;
            } else {
                i += 1;
            }
        }
        // no closing: literal backticks
        let s = self.text[start..self.pos].to_string();
        self.push_text(&s);
    }

    fn parse_delim(&mut self, c: u8) {
        let n = self.bytes.len();
        let start = self.pos;
        while self.pos < n && self.bytes[self.pos] == c {
            self.pos += 1;
        }
        let count = self.pos - start;
        let before = if start == 0 {
            '\n'
        } else {
            self.text[..start].chars().next_back().unwrap()
        };
        let after = if self.pos >= n {
            '\n'
        } else {
            self.text[self.pos..].chars().next().unwrap()
        };
        let before_ws = before.is_whitespace();
        let after_ws = after.is_whitespace();
        let before_punct = is_punctuation(before);
        let after_punct = is_punctuation(after);
        let left_flanking = !after_ws && (!after_punct || before_ws || before_punct);
        let right_flanking = !before_ws && (!before_punct || after_ws || after_punct);
        let (can_open, can_close) = if c == b'_' {
            (
                left_flanking && (!right_flanking || before_punct),
                right_flanking && (!left_flanking || after_punct),
            )
        } else if c == b'~' {
            // strikethrough: at most 2
            if count > 2 {
                (false, false)
            } else {
                (left_flanking, right_flanking)
            }
        } else {
            (left_flanking, right_flanking)
        };
        if (c == b'~' && count > 2) || (c == b'^' && count > 1) {
            let s = self.text[start..self.pos].to_string();
            self.push_text(&s);
            return;
        }
        self.nodes.push(Inline::Delim {
            ch: c,
            count,
            orig_count: count,
            can_open,
            can_close,
            active: true,
        });
    }

    /// Handle a closing bracket. self.pos is just after ']'.
    fn close_bracket(&mut self) {
        // find the last active bracket opener
        let opener_idx = self.nodes.iter().rposition(|n| matches!(n, Inline::Bracket { .. }));
        let opener_idx = match opener_idx {
            Some(i) => i,
            None => {
                self.push_text("]");
                return;
            }
        };
        let (is_image, active, label_start) = match &self.nodes[opener_idx] {
            Inline::Bracket { image, active, pos } => (*image, *active, *pos),
            _ => unreachable!(),
        };
        if !active {
            self.nodes.remove(opener_idx);
            // replace by text
            let txt = if is_image { "![" } else { "[" };
            self.insert_text_at(opener_idx, txt);
            self.push_text("]");
            return;
        }
        let label_end = self.pos - 1;
        let n = self.bytes.len();
        // inline link?
        let mut link: Option<(String, String, usize)> = None;
        if self.pos < n && self.bytes[self.pos] == b'(' {
            if let Some((url, title, end)) = self.scan_inline_link(self.pos) {
                link = Some((url, title, end));
            }
        }
        if link.is_none() {
            // reference link: full, collapsed or shortcut
            let mut ref_label: Option<String> = None;
            let mut consumed = self.pos;
            if self.pos < n && self.bytes[self.pos] == b'[' {
                if let Some(end) = self.scan_link_label(self.pos) {
                    let lab = &self.text[self.pos + 1..end - 1];
                    if lab.trim().is_empty() {
                        // collapsed
                        ref_label = Some(self.text[label_start..label_end].to_string());
                        consumed = end;
                    } else {
                        ref_label = Some(lab.to_string());
                        consumed = end;
                    }
                } else {
                    // `[` not a valid label — shortcut
                    ref_label = Some(self.text[label_start..label_end].to_string());
                }
            } else {
                ref_label = Some(self.text[label_start..label_end].to_string());
            }
            if let Some(lab) = ref_label {
                let key = normalize_label(&lab);
                if let Some(def) = self.parser.link_defs.get(&key) {
                    // Label must not contain unescaped brackets for shortcut/collapsed
                    link = Some((def.url.clone(), def.title.clone(), consumed));
                }
            }
        }
        match link {
            Some((url, title, end)) => {
                let children: Vec<Inline> = self.nodes.drain(opener_idx + 1..).collect();
                self.nodes.pop(); // remove bracket
                // process emphasis within the children
                let mut sub = InlineParser {
                    text: self.text,
                    bytes: self.bytes,
                    pos: 0,
                    nodes: children,
                    parser: self.parser,
                };
                sub.process_emphasis(0);
                let children = sub.nodes;
                if is_image {
                    self.nodes.push(Inline::Image(url, title, children));
                } else {
                    self.nodes.push(Inline::Link(url, title, children));
                    // deactivate earlier link openers
                    for node in self.nodes.iter_mut() {
                        if let Inline::Bracket { image: false, active, .. } = node {
                            *active = false;
                        }
                    }
                }
                self.pos = end;
            }
            None => {
                self.nodes.remove(opener_idx);
                let txt = if is_image { "![" } else { "[" };
                self.insert_text_at(opener_idx, txt);
                self.push_text("]");
            }
        }
    }

    fn insert_text_at(&mut self, idx: usize, txt: &str) {
        // merge with neighbours if text
        if idx > 0 {
            if let Inline::Text(t) = &mut self.nodes[idx - 1] {
                t.push_str(txt);
                // also merge with following text node
                if idx < self.nodes.len() {
                    if let Inline::Text(next) = &self.nodes[idx] {
                        let next = next.clone();
                        if let Inline::Text(t) = &mut self.nodes[idx - 1] {
                            t.push_str(&next);
                        }
                        self.nodes.remove(idx);
                    }
                }
                return;
            }
        }
        if idx < self.nodes.len() {
            if let Inline::Text(t) = &mut self.nodes[idx] {
                t.insert_str(0, txt);
                return;
            }
        }
        self.nodes.insert(idx, Inline::Text(txt.to_string()));
    }

    /// Scan a link label `[...]` at position `pos`; returns the end (after `]`).
    fn scan_link_label(&self, pos: usize) -> Option<usize> {
        let b = self.bytes;
        if b.get(pos) != Some(&b'[') {
            return None;
        }
        let mut i = pos + 1;
        while i < b.len() {
            match b[i] {
                b'\\' => i += 2,
                b'[' => return None,
                b']' => {
                    if i - pos - 1 > 999 {
                        return None;
                    }
                    return Some(i + 1);
                }
                _ => i += 1,
            }
        }
        None
    }

    /// Scan `(dest "title")` at `pos` (pointing at '('). Returns (url, title, end).
    fn scan_inline_link(&self, pos: usize) -> Option<(String, String, usize)> {
        let b = self.bytes;
        let mut i = pos + 1;
        while i < b.len() && (b[i] == b' ' || b[i] == b'\t' || b[i] == b'\n') {
            i += 1;
        }
        if i >= b.len() {
            return None;
        }
        if b[i] == b')' {
            return Some((String::new(), String::new(), i + 1));
        }
        let (dest, dlen) = scan_link_destination(&self.text[i..])?;
        i += dlen;
        let mut j = i;
        while j < b.len() && (b[j] == b' ' || b[j] == b'\t' || b[j] == b'\n') {
            j += 1;
        }
        let mut title = String::new();
        if j < b.len() && j > i && (b[j] == b'"' || b[j] == b'\'' || b[j] == b'(') {
            if let Some((t, tlen)) = scan_link_title(&self.text[j..]) {
                title = t;
                j += tlen;
                while j < b.len() && (b[j] == b' ' || b[j] == b'\t' || b[j] == b'\n') {
                    j += 1;
                }
            } else {
                return None;
            }
        }
        if j < b.len() && b[j] == b')' {
            return Some((unescape_string(&dest), unescape_string(&title), j + 1));
        }
        None
    }

    /// Parse autolink `<...>` or raw HTML `<tag>` at self.pos. Returns true if consumed.
    fn parse_angle(&mut self) -> bool {
        let rest = &self.text[self.pos..];
        let b = rest.as_bytes();
        // autolink: scheme:...
        if let Some(end) = rest.find('>') {
            let inner = &rest[1..end];
            if is_uri_autolink(inner) {
                self.nodes.push(Inline::Link(
                    inner.to_string(),
                    String::new(),
                    vec![Inline::Text(inner.to_string())],
                ));
                self.pos += end + 1;
                return true;
            }
            if is_email_autolink(inner) {
                self.nodes.push(Inline::Link(
                    format!("mailto:{}", inner),
                    String::new(),
                    vec![Inline::Text(inner.to_string())],
                ));
                self.pos += end + 1;
                return true;
            }
        }
        // raw HTML: comment, processing instruction, declaration, cdata, tag
        let html_end = if rest.starts_with("<!--") {
            rest[4..].find("-->").map(|e| 4 + e + 3).filter(|_| {
                let inner = &rest[4..];
                !inner.starts_with('>') && !inner.starts_with("->")
            })
        } else if rest.starts_with("<?") {
            rest[2..].find("?>").map(|e| 2 + e + 2)
        } else if rest.starts_with("<![CDATA[") {
            rest[9..].find("]]>").map(|e| 9 + e + 3)
        } else if b.len() > 2 && b[1] == b'!' && b[2].is_ascii_alphabetic() {
            rest.find('>').map(|e| e + 1)
        } else {
            scan_html_tag(rest)
        };
        if let Some(end) = html_end {
            let html = &rest[..end];
            // HTML is treated as text
            self.push_text(html);
            self.pos += end;
            return true;
        }
        false
    }

    /// GFM extended autolink starting at self.pos (www., http://, https://, mailto:, xmpp:).
    /// Returns (url, display length, kind) where kind 1 means www (prefix http://).
    fn scan_extended_autolink(&self) -> Option<(String, usize, u8)> {
        let rest = &self.text[self.pos..];
        // must be preceded by start, whitespace, or one of * _ ~ (
        if self.pos > 0 {
            let prev = self.text[..self.pos].chars().next_back().unwrap();
            if !(prev.is_whitespace() || prev == '*' || prev == '_' || prev == '~' || prev == '(') {
                return None;
            }
        }
        let kind;
        let scheme_len;
        if rest.starts_with("www.") {
            kind = 1;
            scheme_len = 4;
        } else if rest.starts_with("http://") {
            kind = 0;
            scheme_len = 7;
        } else if rest.starts_with("https://") {
            kind = 0;
            scheme_len = 8;
        } else if rest.starts_with("ftp://") {
            kind = 0;
            scheme_len = 6;
        } else if rest.starts_with("mailto:") {
            kind = 2;
            scheme_len = 7;
        } else if rest.starts_with("xmpp:") {
            kind = 2;
            scheme_len = 5;
        } else {
            return None;
        }
        if kind == 2 {
            // mailto:user@domain
            let after = &rest[scheme_len..];
            let mut i = 0;
            let ab = after.as_bytes();
            while i < ab.len() && (ab[i].is_ascii_alphanumeric() || matches!(ab[i], b'.' | b'-' | b'_' | b'+')) {
                i += 1;
            }
            if i == 0 || ab.get(i) != Some(&b'@') {
                return None;
            }
            let dom_start = i + 1;
            let mut j = dom_start;
            while j < ab.len() && (ab[j].is_ascii_alphanumeric() || ab[j] == b'.' || ab[j] == b'-' || ab[j] == b'_') {
                j += 1;
            }
            let domain = &after[dom_start..j];
            if domain.is_empty() || !domain.contains('.') || domain.ends_with('-') || domain.ends_with('_') {
                return None;
            }
            // trailing '.' excluded
            let mut end = j;
            if after[..end].ends_with('.') {
                end -= 1;
            }
            let total = scheme_len + end;
            return Some((rest[..total].to_string(), total, 2));
        }
        // domain: alphanumerics, '_', '-', '.' ; must contain at least one '.'
        let after = &rest[scheme_len..];
        let ab = after.as_bytes();
        let mut i = 0;
        while i < ab.len() && (ab[i].is_ascii_alphanumeric() || ab[i] == b'_' || ab[i] == b'-' || ab[i] == b'.') {
            i += 1;
        }
        let domain = &after[..i];
        if kind == 1 {
            // www. already has a dot; domain must have at least one more segment
            if domain.is_empty() {
                return None;
            }
        } else if !domain.contains('.') {
            return None;
        }
        // last two segments must not contain '_'
        {
            let full = if kind == 1 { &rest[..scheme_len + i] } else { domain };
            let segs: Vec<&str> = full.split('.').collect();
            let n = segs.len();
            if n >= 1 && segs[n - 1].contains('_') {
                return None;
            }
            if n >= 2 && segs[n - 2].contains('_') {
                return None;
            }
        }
        // path: until whitespace or '<'
        let mut j = i;
        while j < ab.len() {
            let c = ab[j];
            if c == b' ' || c == b'\t' || c == b'\n' || c == b'<' {
                break;
            }
            j += 1;
        }
        // trailing punctuation handling
        let mut end = j;
        loop {
            if end == 0 {
                break;
            }
            let last = ab[end - 1];
            if matches!(last, b'?' | b'!' | b'.' | b',' | b':' | b'*' | b'_' | b'~' | b'\'' | b'"') {
                end -= 1;
                continue;
            }
            if last == b')' {
                // count parens
                let seg = &after[..end];
                let opens = seg.bytes().filter(|&b| b == b'(').count();
                let closes = seg.bytes().filter(|&b| b == b')').count();
                if closes > opens {
                    end -= 1;
                    continue;
                }
            }
            if last == b';' {
                // entity reference?
                let seg = &after[..end - 1];
                if let Some(amp) = seg.rfind('&') {
                    if seg[amp + 1..].bytes().all(|b| b.is_ascii_alphanumeric()) && seg[amp + 1..].len() > 0 {
                        end = amp;
                        continue;
                    }
                }
            }
            break;
        }
        if end <= i && kind == 0 && domain.is_empty() {
            return None;
        }
        let total = scheme_len + end;
        let url = rest[..total].to_string();
        Some((url, total, kind))
    }

    /// Email autolink around an '@' at self.pos. Returns (start, end).
    fn scan_email_autolink(&self, text_start: usize) -> Option<(usize, usize)> {
        let b = self.bytes;
        let at = self.pos;
        // scan backwards for local part
        let mut s = at;
        while s > text_start {
            let c = b[s - 1];
            if c.is_ascii_alphanumeric() || matches!(c, b'.' | b'-' | b'_' | b'+') {
                s -= 1;
            } else {
                break;
            }
        }
        if s == at {
            return None;
        }
        // the char before must be whitespace/start or punctuation delimiter
        if s > 0 {
            let prev = self.text[..s].chars().next_back().unwrap();
            if !(prev.is_whitespace() || prev == '*' || prev == '_' || prev == '~' || prev == '(') {
                return None;
            }
        }
        let mut e = at + 1;
        while e < b.len() && (b[e].is_ascii_alphanumeric() || b[e] == b'.' || b[e] == b'-' || b[e] == b'_') {
            e += 1;
        }
        let domain = &self.text[at + 1..e];
        if !domain.contains('.') {
            return None;
        }
        let mut end = e;
        while end > at + 1 && matches!(b[end - 1], b'.' | b'-' | b'_') {
            end -= 1;
        }
        if end == at + 1 {
            return None;
        }
        if !self.text[at + 1..end].contains('.') {
            return None;
        }
        // last char of domain must be alnum
        Some((s, end))
    }

    /// Process emphasis delimiters (the CommonMark algorithm) on self.nodes[from..]
    fn process_emphasis(&mut self, from: usize) {
        // openers_bottom per (char, can_open, count%3)
        let mut i = from;
        loop {
            // find next closer
            while i < self.nodes.len() {
                if let Inline::Delim { can_close: true, active: true, .. } = &self.nodes[i] {
                    break;
                }
                i += 1;
            }
            if i >= self.nodes.len() {
                break;
            }
            let (ch, closer_count, closer_orig, closer_can_open) = match &self.nodes[i] {
                Inline::Delim { ch, count, orig_count, can_open, .. } => (*ch, *count, *orig_count, *can_open),
                _ => unreachable!(),
            };
            // look back for an opener
            let mut j = i;
            let mut found = None;
            while j > from {
                j -= 1;
                if let Inline::Delim {
                    ch: och,
                    count: ocount,
                    orig_count: oorig,
                    can_open: true,
                    can_close: ocan_close,
                    active: true,
                } = &self.nodes[j]
                {
                    if *och == ch && *ocount > 0 {
                        // rule of 3
                        let odd_match = (closer_can_open || *ocan_close) && (closer_orig + oorig) % 3 == 0 && !(closer_orig % 3 == 0 && oorig % 3 == 0);
                        if ch == b'~' || ch == b'^' {
                            // strikethrough: counts must match (1 or 2)
                            if *ocount == closer_count {
                                found = Some(j);
                                break;
                            }
                            continue;
                        }
                        if !odd_match {
                            found = Some(j);
                            break;
                        }
                    }
                }
            }
            match found {
                None => {
                    // no opener: if it can't open, deactivate as closer
                    if !closer_can_open {
                        if let Inline::Delim { can_close, .. } = &mut self.nodes[i] {
                            *can_close = false;
                        }
                    }
                    i += 1;
                }
                Some(j) => {
                    let opener_count = match &self.nodes[j] {
                        Inline::Delim { count, .. } => *count,
                        _ => unreachable!(),
                    };
                    let use_count = if ch == b'~' || ch == b'^' {
                        opener_count
                    } else if opener_count >= 2 && closer_count >= 2 {
                        2
                    } else {
                        1
                    };
                    // children are nodes between j and i
                    let children: Vec<Inline> = self.nodes.drain(j + 1..i).collect();
                    let wrapped = match ch {
                        b'~' => {
                            if self.parser.opts.superscript && use_count == 1 {
                                Inline::Sub(children)
                            } else {
                                Inline::Strike(children)
                            }
                        }
                        b'^' => Inline::Sup(children),
                        _ => {
                            if use_count == 2 {
                                Inline::Strong(children)
                            } else {
                                Inline::Emph(children)
                            }
                        }
                    };
                    // update opener
                    let mut remove_opener = false;
                    if let Inline::Delim { count, .. } = &mut self.nodes[j] {
                        *count -= use_count;
                        if *count == 0 {
                            remove_opener = true;
                        }
                    }
                    // insert wrapped after opener (at j+1); closer is now at j+1
                    self.nodes.insert(j + 1, wrapped);
                    let closer_idx = j + 2;
                    let mut remove_closer = false;
                    if let Inline::Delim { count, .. } = &mut self.nodes[closer_idx] {
                        *count -= use_count;
                        if *count == 0 {
                            remove_closer = true;
                        }
                    }
                    let mut new_i = closer_idx;
                    if remove_closer {
                        self.nodes.remove(closer_idx);
                    }
                    if remove_opener {
                        self.nodes.remove(j);
                        new_i -= 1;
                    }
                    i = new_i;
                    if remove_closer {
                        // closer consumed; continue searching from i
                    }
                }
            }
        }
        // convert remaining delimiters to text
        let mut k = from;
        while k < self.nodes.len() {
            if let Inline::Delim { ch, count, .. } = &self.nodes[k] {
                let s: String = std::iter::repeat(*ch as char).take(*count).collect();
                self.nodes[k] = Inline::Text(s);
            }
            if let Inline::Bracket { image, .. } = &self.nodes[k] {
                let s = if *image { "![" } else { "[" };
                self.nodes[k] = Inline::Text(s.to_string());
            }
            k += 1;
        }
        // merge adjacent texts
        let mut merged: Vec<Inline> = Vec::new();
        for node in self.nodes.drain(..) {
            if let Inline::Text(t) = &node {
                if let Some(Inline::Text(prev)) = merged.last_mut() {
                    prev.push_str(t);
                    continue;
                }
            }
            merged.push(node);
        }
        self.nodes = merged;
    }

    fn to_tokens(&self, nodes: Vec<Inline>) -> Vec<Token> {
        let mut out = Vec::new();
        for n in nodes {
            match n {
                Inline::Text(t) => out.push(Token::Str(t)),
                Inline::Code(c) => out.push(Token::Code(c)),
                Inline::SoftBreak => out.push(Token::SoftBreak),
                Inline::HardBreak => out.push(Token::HardBreak),
                Inline::Delim { ch, count, .. } => {
                    out.push(Token::Str(std::iter::repeat(ch as char).take(count).collect()))
                }
                Inline::Bracket { image, .. } => out.push(Token::Str(if image { "![".into() } else { "[".into() })),
                Inline::Link(u, t, c) => out.push(Token::Link(u, t, self.to_tokens(c))),
                Inline::Image(u, t, c) => out.push(Token::Image(u, t, self.to_tokens(c))),
                Inline::FootnoteRef(label) => {
                    if let Some(content) = self.parser.footnote_defs.get(&label) {
                        out.push(Token::Footnote(vec![Token::Str(label.clone()), Token::Paragraph(content.clone())]));
                        // Note: we encode the label as the first Str token; renderers unpack it.
                    } else {
                        out.push(Token::Str(format!("[^{}]", label)));
                    }
                }
                Inline::Emph(c) => out.push(Token::Emphasis(self.to_tokens(c))),
                Inline::Strong(c) => out.push(Token::Strong(self.to_tokens(c))),
                Inline::Strike(c) => out.push(Token::Strikethrough(self.to_tokens(c))),
                Inline::Sup(c) => out.push(Token::Superscript(self.to_tokens(c))),
                Inline::Sub(c) => out.push(Token::Subscript(self.to_tokens(c))),
            }
        }
        // merge adjacent Str tokens
        let mut merged: Vec<Token> = Vec::new();
        for t in out {
            if let Token::Str(s) = &t {
                if let Some(Token::Str(prev)) = merged.last_mut() {
                    prev.push_str(s);
                    continue;
                }
            }
            merged.push(t);
        }
        merged
    }
}

fn is_uri_autolink(s: &str) -> bool {
    // scheme: 2-32 chars, letter followed by letters/digits/+.-; then ':' then no spaces/<>
    let colon = match s.find(':') {
        Some(c) => c,
        None => return false,
    };
    let scheme = &s[..colon];
    if scheme.len() < 2 || scheme.len() > 32 {
        return false;
    }
    let mut chars = scheme.chars();
    if !chars.next().unwrap().is_ascii_alphabetic() {
        return false;
    }
    if !chars.all(|c| c.is_ascii_alphanumeric() || c == '+' || c == '.' || c == '-') {
        return false;
    }
    !s.bytes().any(|b| b == b' ' || b == b'<' || b == b'>' || b < 0x20 || b == 0x7f)
}

fn is_email_autolink(s: &str) -> bool {
    let at = match s.find('@') {
        Some(a) => a,
        None => return false,
    };
    let local = &s[..at];
    let domain = &s[at + 1..];
    if local.is_empty() || domain.is_empty() {
        return false;
    }
    if !local
        .bytes()
        .all(|b| b.is_ascii_alphanumeric() || b".!#$%&'*+/=?^_`{|}~-".contains(&b))
    {
        return false;
    }
    for (i, part) in domain.split('.').enumerate() {
        let _ = i;
        if part.is_empty() || part.len() > 63 {
            return false;
        }
        if !part.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'-') {
            return false;
        }
        if part.starts_with('-') || part.ends_with('-') {
            return false;
        }
    }
    true
}
