//! Typographic cleaning of text (whitespace collapsing, smart quotes,
//! French non-breaking spaces...).

pub const NB_CHAR: char = '\u{a0}';
pub const NB_CHAR_NARROW: char = '\u{202f}';
pub const NB_CHAR_EM: char = '\u{2002}';

#[derive(Debug, Clone)]
pub struct Cleaner {
    pub french: bool,
    pub smart_quotes: bool,
    pub ligature_dashes: bool,
    pub ligature_guillemets: bool,
    /// if true, no cleaning at all
    pub disabled: bool,
}

fn is_ws(c: char) -> bool {
    c == ' ' || c == NB_CHAR || c == NB_CHAR_NARROW
}

/// Collapse runs of (' ', nbsp, narrow nbsp) into their first character.
pub fn collapse_whitespace(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    let mut prev_ws = false;
    for c in s.chars() {
        if is_ws(c) {
            if prev_ws {
                continue;
            }
            prev_ws = true;
            out.push(c);
        } else {
            prev_ws = false;
            out.push(c);
        }
    }
    out
}

/// Replace straight quotes with curly ones.
pub fn smart_quotes(s: &str) -> String {
    if !s.contains('"') && !s.contains('\'') {
        return s.to_string();
    }
    let chars: Vec<char> = s.chars().collect();
    let n = chars.len();
    let mut out: Vec<char> = Vec::with_capacity(n);
    let mut pending_double: usize = 0;
    let mut pending_single: usize = 0;
    let get = |i: isize| -> char {
        if i < 0 || i as usize >= n {
            ' '
        } else {
            chars[i as usize]
        }
    };
    for i in 0..n {
        let c = chars[i];
        match c {
            '"' => {
                let prev = get(i as isize - 1);
                let next = get(i as isize + 1);
                let opener = !next.is_whitespace() && ((prev.is_whitespace() || i == 0) || (!prev.is_alphanumeric() && next.is_alphanumeric()));
                if opener {
                    out.push('“');
                    pending_double += 1;
                } else if pending_double > 0 {
                    out.push('”');
                    pending_double -= 1;
                } else {
                    out.push('"');
                }
            }
            '\'' => {
                let prev = get(i as isize - 1);
                let next = get(i as isize + 1);
                let prev_ws = prev.is_whitespace() || i == 0;
                let next_ws = next.is_whitespace() || i + 1 >= n;
                if prev_ws && next_ws {
                    out.push('\'');
                } else if prev.is_alphanumeric() {
                    out.push('’');
                    if pending_single > 0 {
                        pending_single -= 1;
