                        closing = Some(j);
                        break;
                    }
                    j += 1;
                }
                let paired = match closing {
                    Some(j) if j > 0 && is_ws(chars[j - 1]) => true,
                    _ => false,
                };
                if i == 0 || !paired {
                    chars[i + 1] = NB_CHAR;
                    if paired {
                        let j = closing.unwrap();
                        chars[j - 1] = NB_CHAR;
                    }
                } else {
