            None => true,
            Some(c) => !is_letter(c),
        };
    }
    if c1.is_uppercase() {
        // uppercase followed by non-letter or end: always ok
        match c2 {
            None => return true,
            Some(c) if !is_letter(c) => return true,
            _ => {}
        }
    }
    // Base patterns: Lu{1,3} or Ll L
    let mut bases: Vec<usize> = Vec::new(); // lengths of matching bases
    if c1.is_uppercase() {
        let mut k = 1;
        while k <= 3 && start + k <= n {
            // chars[start..start+k] all uppercase
            if chars[start..start + k].iter().all(|c| c.is_uppercase()) {
