impl Template {
    pub fn compile(src: &str, syn: &Syntax) -> Result<Template, TemplateError> {
        let toks = tokenize(src, syn);
        let mut pos = 0;
        let nodes = parse_nodes(&toks, &mut pos, false)?;
        if pos < toks.len() {
            return Err(TemplateError("unexpected block".to_string()));
        }
        Ok(Template { nodes })
    }

    pub fn render(&self, ctx: &Context) -> Result<String, TemplateError> {
        let mut out = String::new();
        render_nodes(&self.nodes, ctx, &mut out)?;
        Ok(out)
    }
