fn parse_nodes(toks: &[Tok], pos: &mut usize, in_if: bool) -> Result<Vec<Node>, TemplateError> {
    let mut nodes = Vec::new();
    while *pos < toks.len() {
        match &toks[*pos] {
            Tok::Text(t) => {
                nodes.push(Node::Text(t.clone()));
                *pos += 1;
            }
            Tok::Expr(e) => {
                nodes.push(Node::Var(e.clone()));
                *pos += 1;
            }
            Tok::Block(b) => {
                let words: Vec<&str> = b.split_whitespace().collect();
                match words.first().copied() {
                    Some("if") => {
                        *pos += 1;
                        let (negate, var) = if words.len() >= 3 && words[1] == "not" {
