                        let mut otherwise = Vec::new();
                        if *pos < toks.len() {
                            if let Tok::Block(b2) = &toks[*pos] {
                                if b2.trim() == "else" {
                                    *pos += 1;
                                    otherwise = parse_nodes(toks, pos, true)?;
                                }
                            }
                        }
                        // expect endif
                        if *pos < toks.len() {
