                    }
                    Some("else") | Some("endif") => {
                        if in_if {
                            return Ok(nodes);
                        }
                        return Err(TemplateError("unexpected block".to_string()));
                    }
                    _ => return Err(TemplateError(format!("unknown block '{}'", b))),
                }
            }
        }
    }
    Ok(nodes)
}

fn render_nodes(nodes: &[Node], ctx: &Context, out: &mut String) -> Result<(), TemplateError> {
    for n in nodes {
        match n {
            Node::Text(t) => out.push_str(t),
