//! syntax (HTML templates) and `<<var>>` / `<# if x #>...<# endif #>` (LaTeX templates).

use std::collections::HashMap;

#[derive(Debug, Clone)]
pub enum Value {
    Str(String),
    Bool(bool),
}

impl From<String> for Value {
    fn from(s: String) -> Value {
        Value::Str(s)
    }
}
impl From<&str> for Value {
    fn from(s: &str) -> Value {
        Value::Str(s.to_string())
    }
}
impl From<bool> for Value {
    fn from(b: bool) -> Value {
        Value::Bool(b)
    }
}

#[derive(Debug, Default, Clone)]
pub struct Context {
    pub vars: HashMap<String, Value>,
}

impl Context {
    pub fn new() -> Context {
        Context::default()
    }
    pub fn insert<V: Into<Value>>(&mut self, key: &str, v: V) {
        self.vars.insert(key.to_string(), v.into());
    }
    pub fn insert_bool(&mut self, key: &str, v: bool) {
        self.vars.insert(key.to_string(), Value::Bool(v));
    }
    fn truthy(&self, key: &str) -> Option<bool> {
        match self.vars.get(key) {
            Some(Value::Bool(b)) => Some(*b),
            Some(Value::Str(s)) => Some(!s.is_empty()),
            None => None,
        }
    }
}

#[derive(Debug, Clone, Copy)]
pub struct Syntax {
    pub expr_open: &'static str,
    pub expr_close: &'static str,
    pub block_open: &'static str,
    pub block_close: &'static str,
}

pub const HTML_SYNTAX: Syntax = Syntax {
    expr_open: "{{",
    expr_close: "}}",
    block_open: "{%",
    block_close: "%}",
};

pub const TEX_SYNTAX: Syntax = Syntax {
    expr_open: "<<",
    expr_close: ">>",
    block_open: "<#",
    block_close: "#>",
};

#[derive(Debug)]
enum Node {
    Text(String),
    Var(String),
    If(String, bool, Vec<Node>, Vec<Node>),
}

#[derive(Debug)]
pub struct Template {
    nodes: Vec<Node>,
}

#[derive(Debug)]
pub struct TemplateError(pub String);

impl std::fmt::Display for TemplateError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.0)
    }
}

enum Tok {
    Text(String),
    Expr(String),
    Block(String),
}

fn tokenize(src: &str, syn: &Syntax) -> Vec<Tok> {
    let mut toks = Vec::new();
    let mut rest = src;
    let mut text = String::new();
    while !rest.is_empty() {
        let pe = rest.find(syn.expr_open);
        let pb = rest.find(syn.block_open);
        let (pos, is_block) = match (pe, pb) {
            (None, None) => {
                text.push_str(rest);
                break;
            }
            (Some(e), None) => (e, false),
            (None, Some(b)) => (b, true),
            (Some(e), Some(b)) => {
                if b < e {
                    (b, true)
                } else {
                    (e, false)
                }
            }
        };
        text.push_str(&rest[..pos]);
        let after = &rest[pos..];
        let (open, close) = if is_block {
            (syn.block_open, syn.block_close)
        } else {
            (syn.expr_open, syn.expr_close)
        };
        let inner_start = open.len();
        match after[inner_start..].find(close) {
            Some(end) => {
                let inner = after[inner_start..inner_start + end].trim().to_string();
                if !text.is_empty() {
                    toks.push(Tok::Text(std::mem::take(&mut text)));
                }
                if is_block {
                    toks.push(Tok::Block(inner));
                } else {
                    toks.push(Tok::Expr(inner));
                }
                rest = &after[inner_start + end + close.len()..];
            }
            None => {
                text.push_str(open);
                rest = &after[inner_start..];
            }
        }
    }
    if !text.is_empty() {
        toks.push(Tok::Text(text));
    }
    toks
}

