//! Message logging, mimicking the original's output modes.

use std::cell::RefCell;
use std::io::Write;

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum Level {
    Debug,
    Info,
    Warn,
    Error,
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Mode {
    /// Collect warnings/errors and print them at the end
    Collect,
    /// Print everything immediately with timestamps (verbose)
    Verbose,
    /// Only print errors immediately, in `[ERROR] msg` form (quiet)
    Quiet,
}

thread_local! {
    static MODE: RefCell<Mode> = RefCell::new(Mode::Collect);
    static MESSAGES: RefCell<Vec<(Level, String)>> = RefCell::new(Vec::new());
    static COLOR: RefCell<bool> = RefCell::new(false);
    static EMOJI: RefCell<bool> = RefCell::new(false);
}

pub fn set_mode(m: Mode) {
    MODE.with(|x| *x.borrow_mut() = m);
}

pub fn mode() -> Mode {
    MODE.with(|x| *x.borrow())
}

pub fn set_color(c: bool) {
    COLOR.with(|x| *x.borrow_mut() = c);
}

pub fn color() -> bool {
    COLOR.with(|x| *x.borrow())
}

pub fn set_emoji(c: bool) {
    EMOJI.with(|x| *x.borrow_mut() = c);
}

pub fn emoji() -> bool {
    EMOJI.with(|x| *x.borrow())
}

fn timestamp() -> String {
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0);
    let secs = now % 86400;
    format!("{:02}:{:02}:{:02}", secs / 3600, (secs % 3600) / 60, secs % 60)
}

pub fn log(level: Level, module: &str, msg: &str) {
    match mode() {
        Mode::Verbose => {
            let lvl = match level {
                Level::Debug => "DEBUG",
                Level::Info => "INFO",
                Level::Warn => "WARN",
                Level::Error => "ERROR",
            };
            let thread = if level == Level::Debug { "(1) " } else { "" };
            eprintln!("{} [{}] {}crowbook::{}: {}", timestamp(), lvl, thread, module, msg);
        }
        Mode::Quiet => {
            if level == Level::Error {
                eprintln!("[ERROR] {}", msg);
            }
        }
        Mode::Collect => {
            if level >= Level::Warn {
                MESSAGES.with(|m| m.borrow_mut().push((level, msg.to_string())));
            }
        }
    }
}

pub fn debug(module: &str, msg: &str) {
    log(Level::Debug, module, msg);
}
pub fn info(module: &str, msg: &str) {
    log(Level::Info, module, msg);
}
pub fn warn(module: &str, msg: &str) {
    log(Level::Warn, module, msg);
}
pub fn error(module: &str, msg: &str) {
    log(Level::Error, module, msg);
}

pub fn take_messages() -> Vec<(Level, String)> {
    MESSAGES.with(|m| std::mem::take(&mut *m.borrow_mut()))
}

pub fn has_messages() -> bool {
    MESSAGES.with(|m| !m.borrow().is_empty())
}

/// Print the "CROWBOOK x.y.z" header (fancy UI)
pub fn print_header() {
    if mode() == Mode::Quiet {
        return;
    }
    if color() {
        eprintln!("\x1b[1m\x1b[35mCROWBOOK \x1b[0m\x1b[34m\x1b[49m{}\x1b[39m", crate::cli::VERSION);
    } else {
        eprintln!("CROWBOOK {}", crate::cli::VERSION);
    }
}

/// Print a WARNING line (fancy UI)
pub fn print_warning(msg: &str) {
    if color() {
        eprintln!("\x1b[1m\x1b[33mWARNING\x1b[0m\x1b[39m\x1b[49m {}", msg);
    } else {
        eprintln!("WARNING {}", msg);
    }
}

/// Print an ERROR line (fancy UI)
pub fn print_error(msg: &str) {
    if color() {
        eprintln!("\x1b[1m\x1b[31mERROR\x1b[0m\x1b[39m\x1b[49m {}", msg);
    } else {
        eprintln!("ERROR {}", msg);
    }
}

/// Print a success line (fancy UI, only on a terminal)
pub fn print_success(msg: &str) {
    if color() {
        let mark = if emoji() { "✔" } else { "V" };
        eprintln!("\x1b[1m\x1b[36m{}\x1b[0m\x1b[39m\x1b[49m {}", mark, msg);
    }
}

/// Flush stdout/stderr
pub fn flush() {
    let _ = std::io::stdout().flush();
    let _ = std::io::stderr().flush();
}
EOF
echo ok"}

