/// Print a success line (fancy UI, only on a terminal)
pub fn print_success(msg: &str) {
    if color() {
        let mark = if emoji() { "✔" } else { "V" };
        eprintln!("\x1b[1m\x1b[36m{}\x1b[0m\x1b[39m\x1b[49m {}", mark, msg);
    }
}

/// Flush stdout/stderr
pub fn flush() {
    let _ = std::io::stdout().flush();
    let _ = std::io::stderr().flush();
}
