//! The `Book` structure: configuration parsing, chapter loading and rendering.

use crate::bookoptions::BookOptions;
use crate::cleaner::Cleaner;
use crate::error::{Error, Result, Source};
use crate::lang::lformat2;
use crate::logger;
use crate::number::Number;
use crate::parser::{Options as ParserOptions, Parser};
use crate::token::Token;
use crate::yaml::{self, Yaml};
use std::path::{Path, PathBuf};

#[derive(Debug, Clone)]
pub struct Chapter {
    pub number: Number,
    pub filename: String,
    pub content: Vec<Token>,
}

#[derive(Debug, Clone, Default)]
pub struct Features {
    pub tables: bool,
    pub images: bool,
    pub codeblocks: bool,
    pub strikethrough: bool,
    pub taskitem: bool,
    pub footnotes: bool,
    pub superscript: bool,
    pub subscript: bool,
}

impl Features {
    fn scan(&mut self, tokens: &[Token]) {
        for t in tokens {
            match t {
                Token::Table(..) => self.tables = true,
                Token::Image(..) | Token::StandaloneImage(..) => self.images = true,
                Token::CodeBlock(..) => self.codeblocks = true,
                Token::Strikethrough(_) => self.strikethrough = true,
                Token::TaskItem(..) => self.taskitem = true,
                Token::Footnote(..) => self.footnotes = true,
                Token::Superscript(_) => self.superscript = true,
                Token::Subscript(_) => self.subscript = true,
                _ => {}
            }
            if let Some(inner) = t.inner() {
                self.scan(inner);
            }
        }
    }
}

#[derive(Debug, Clone)]
pub struct Book {
    pub options: BookOptions,
    pub chapters: Vec<Chapter>,
    pub root: PathBuf,
    pub source: Source,
    pub features: Features,
    /// Whether the book is loaded from a single markdown file
    pub single: bool,
}

fn is_chapter_line(line: &str) -> bool {
    match line.chars().next() {
        Some('+') | Some('-') | Some('!') | Some('@') => true,
        Some(c) if c.is_ascii_digit() => true,
        _ => false,
    }
}

fn is_continuation_line(line: &str) -> bool {
    line.is_empty() || line.starts_with(|c: char| c.is_whitespace()) || line.starts_with('#')
}

impl Book {
    pub fn new() -> Book {
        Book {
            options: BookOptions::new(),
            chapters: Vec::new(),
            root: PathBuf::new(),
            source: Source::empty(),
            features: Features::default(),
            single: false,
        }
    }

    pub fn is_proofread(&self) -> bool {
        false
    }

    /// Set the root path (directory of the configuration file)
    pub fn set_root(&mut self, root: &Path) {
        self.root = root.to_path_buf();
        self.options.root = root.to_path_buf();
    }

    /// Returns the cleaner for this book
    pub fn cleaner(&self) -> Cleaner {
        let lang = self.options.get_str("lang").unwrap_or("en").to_string();
        if !self.options.get_bool("input.clean").unwrap_or(true) {
            return Cleaner::none();
        }
        Cleaner::new(
            &lang,
            self.options.get_bool("input.clean.smart_quotes").unwrap_or(true),
            self.options.get_bool("input.clean.ligature.dashes").unwrap_or(false),
            self.options.get_bool("input.clean.ligature.guillemets").unwrap_or(false),
        )
    }

    /// Load a book configuration file
    pub fn load_file(&mut self, path: &str) -> Result<()> {
        let p = Path::new(path);
        let content = match std::fs::read_to_string(p) {
            Ok(c) => c,
            Err(_) => {
                return Err(Error::file_not_found(Source::empty(), crate::lang::lformat("book"), path));
            }
        };
        let root = p.parent().map(|x| x.to_path_buf()).unwrap_or_default();
        self.set_root(&root);
        let filename = p.file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or_else(|| path.to_string());
        self.source = Source::new(&filename);
        self.options.source = self.source.clone();
        self.set_from_config(&content)
    }

    /// Load a single markdown file as a book
    pub fn load_markdown_file(&mut self, path: &str) -> Result<()> {
        let p = Path::new(path);
        let root = p.parent().map(|x| x.to_path_buf()).unwrap_or_default();
        self.set_root(&root);
        self.single = true;
        self.options.set_yaml("tex.class", Yaml::String("article".to_string()))?;
        self.options.set_yaml("input.yaml_blocks", Yaml::Boolean(true))?;
        self.options.set_yaml("tex.title", Yaml::Boolean(false))?;
        let filename = p.file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or_else(|| path.to_string());
        self.source = Source::new(&filename);
        self.options.source = self.source.clone();
        let content = self.read_file(&filename, "book")?;
        self.add_chapter_from_source(Number::Default, &filename, &content)?;
        Ok(())
    }

    fn read_file(&self, filename: &str, what: &str) -> Result<String> {
        let full = self.root.join(filename);
        match std::fs::read(&full) {
            Ok(bytes) => match String::from_utf8(bytes) {
                Ok(s) => Ok(s),
                Err(_) => Err(Error::parser(
                    self.source.clone(),
                    lformat2("file {file} contains invalid UTF-8", &[("file", filename)]),
                )),
            },
            Err(_) => Err(Error::file_not_found(self.source.clone(), what.to_string(), filename.to_string())),
        }
    }

    /// Parse the configuration file content
    pub fn set_from_config(&mut self, s: &str) -> Result<()> {
        let mut yaml = String::new();
        let mut line_number: u32 = 0;
        let mut in_chapters = false;
        let mut yaml_parsed = false;
        let mut errors: Vec<Error> = Vec::new();

        for line in s.lines() {
            line_number += 1;
            if is_chapter_line(line) {
                if !yaml_parsed {
                    self.source.set_line(line_number - 1);
                    if line_number - 1 == 0 {
                        self.source.unset_line();
                    }
                    self.options.source = self.source.clone();
                    self.apply_yaml_block(&yaml, true, &mut errors)?;
                    yaml.clear();
                    yaml_parsed = true;
                }
                in_chapters = true;
                let source = Source::with_line(self.source.file.as_deref().unwrap_or(""), line_number);
                self.parse_chapter_line(line, source)?;
            } else if in_chapters {
                if line.trim().is_empty() || line.trim_start().starts_with('#') {
                    continue;
                }
                return Err(Error::config_parser(
                    Source::with_line(self.source.file.as_deref().unwrap_or(""), line_number),
                    crate::lang::lformat("found invalid chapter definition in the chapter list"),
                ));
            } else if is_continuation_line(line) {
                yaml.push_str(line);
                yaml.push('\n');
            } else {
                // potential new key
                let mut new = yaml.clone();
                new.push_str(line);
                new.push('\n');
                let new_ok = yaml::load_from_str(&new).is_ok();
                if new_ok && !yaml.trim().is_empty() {
                    if let Ok(docs) = yaml::load_from_str(&yaml) {
                        if docs.len() == 1 && docs[0].as_hash().is_some() {
                            self.source.set_line(line_number - 1);
                            self.options.source = self.source.clone();
                            self.apply_yaml_block(&yaml, false, &mut errors)?;
                            yaml.clear();
                        }
                    }
                }
                yaml.push_str(line);
                yaml.push('\n');
            }
        }
        if !yaml_parsed {
            // end of file without chapters
            self.source.set_line(line_number);
            if line_number == 0 {
                self.source.unset_line();
            }
            self.options.source = self.source.clone();
            self.apply_yaml_block(&yaml, true, &mut errors)?;
        }
        for e in errors {
            logger::error("book", &e.to_string());
        }
        Ok(())
    }

    /// Parse a yaml block and set options. `strict`: if the block is not a hash, error.
    fn apply_yaml_block(&mut self, yaml: &str, strict: bool, errors: &mut Vec<Error>) -> Result<()> {
        let docs = match yaml::load_from_str(yaml) {
            Ok(d) => d,
            Err(e) => {
                return Err(Error::config_parser(
                    self.source.clone(),
                    lformat2("YAML block was not valid YAML: {error}", &[("error", &e.to_string())]),
                ));
            }
        };
        if docs.len() == 1 {
            if let Some(hash) = docs[0].as_hash() {
                let hash = hash.clone();
                self.set_options_from_hash(&hash, errors)?;
                return Ok(());
            }
        }
        if strict {
            return Err(Error::config_parser(
                self.source.clone(),
                format!(
                    "{}\n{}",
                    crate::lang::lformat("\"could not parse %{file} as a book file.\""),
                    crate::lang::lformat("Maybe you meant to run crowbook with the --single argument?")
                ),
            ));
        }
        Ok(())
    }

    fn set_options_from_hash(&mut self, hash: &[(Yaml, Yaml)], errors: &mut Vec<Error>) -> Result<()> {
        for (k, v) in hash {
            let key = match k {
                Yaml::String(s) => s.clone(),
                other => format!("{:?}", other),
            };
            if key == "import" {
                if let Yaml::String(file) = v {
                    self.import_config(file)?;
                } else {
                    errors.push(Error::book_option(
                        self.source.clone(),
                        format!("Expected a string as value for key import, found {:?}", v),
                    ));
                }
                continue;
            }
            match self.options.set_yaml(&key, v.clone()) {
                Ok(_) => {}
                Err(e) => errors.push(e),
            }
            for w in self.options.warnings.drain(..) {
                logger::warn("bookoptions", &w);
            }
        }
        Ok(())
    }

    fn import_config(&mut self, file: &str) -> Result<()> {
        let full = self.root.join(file);
        let content = match std::fs::read_to_string(&full) {
            Ok(c) => c,
            Err(_) => {
                return Err(Error::file_not_found(Source::empty(), crate::lang::lformat("book"), file));
            }
        };
        // Parse only the yaml part of the imported file, with a temporary book
        let mut tmp = Book::new();
        tmp.set_root(&full.parent().map(|p| p.to_path_buf()).unwrap_or_default());
        tmp.source = Source::new(file);
        tmp.options.source = tmp.source.clone();
        tmp.set_from_config(&content)?;
        // copy options set in tmp (except output/import) — approximate: copy all set options
        for def in crate::bookoptions::OPTIONS {
            if def.key.starts_with("output") {
                continue;
            }
            if let Ok(v) = tmp.options.get(def.key) {
                let default = BookOptions::new();
                if default.get(def.key).ok() != Some(v) {
                    self.options.set_raw(def.key, v.clone());
                }
            }
        }
        Ok(())
    }

    fn parse_chapter_line(&mut self, line: &str, source: Source) -> Result<()> {
        let first = line.chars().next().unwrap();
        match first {
            '-' => {
                let file = line.trim_start_matches('-').trim();
                if file.is_empty() {
                    return Err(Error::config_parser(source, crate::lang::lformat("no chapter name specified")));
                }
                self.check_whitespace(file, &source)?;
                self.add_chapter_src(Number::Unnumbered, file, source)
            }
            '+' => {
                let file = line[1..].trim();
                if file.is_empty() {
                    return Err(Error::config_parser(source, crate::lang::lformat("no chapter name specified")));
                }
                self.check_whitespace(file, &source)?;
                self.add_chapter_src(Number::Default, file, source)
            }
            '!' => {
                let file = line[1..].trim();
                if file.is_empty() {
                    return Err(Error::config_parser(source, crate::lang::lformat("no chapter name specified")));
                }
                self.check_whitespace(file, &source)?;
                self.add_chapter_src(Number::Hidden, file, source)
            }
            '@' => {
                let rest = &line[1..];
                if !rest.starts_with(' ') || rest.trim().is_empty() {
                    return Err(Error::config_parser(
                        source,
                        crate::lang::lformat("found invalid part definition in the chapter list"),
                    ));
                }
                let title = rest.trim();
                // A part defined by a title only
                let mut parser = Parser::new(self.parser_options());
                let tokens = parser.parse(title);
                let content = vec![Token::Header(1, inline_of(tokens))];
                self.chapters.push(Chapter {
                    number: Number::DefaultPart,
                    filename: String::new(),
                    content,
                });
                Ok(())
            }
            _ => {
                // numbered chapter: "N. file"
                let dot = match line.find('.') {
                    Some(d) => d,
                    None => {
                        return Err(Error::config_parser(
                            source,
                            crate::lang::lformat("error parsing chapter number: invalid digit found in string"),
                        ));
                    }
                };
                let num_str = &line[..dot];
                let number: i32 = match num_str.parse::<i32>() {
                    Ok(n) => n,
                    Err(e) => {
                        return Err(Error::config_parser(
                            source,
                            lformat2("error parsing chapter number: {error}", &[("error", &e.to_string())]),
                        ));
                    }
                };
                if dot + 2 > line.len() {
                    // mimic the original's panic
                    eprintln!(
                        "\nthread 'main' panicked at src/lib/book.rs:446:38:\nbyte index 1 is out of bounds of ``\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace"
                    );
                    std::process::exit(101);
                }
                let file = line[dot + 2..].trim();
                if file.is_empty() {
                    return Err(Error::config_parser(source, crate::lang::lformat("no chapter name specified")));
                }
                self.check_whitespace(file, &source)?;
                self.add_chapter_src(Number::Specified(number), file, source)
            }
        }
    }

    fn check_whitespace(&self, file: &str, source: &Source) -> Result<()> {
        if file.contains(|c: char| c.is_whitespace()) {
            return Err(Error::config_parser(source.clone(), "error.chapter_whitespace".to_string()));
        }
        Ok(())
    }

    pub fn parser_options(&self) -> ParserOptions {
        ParserOptions {
            superscript: self.options.get_bool("crowbook.markdown.superscript").unwrap_or(false),
            html_as_text: self.options.get_bool("crowbook.html_as_text").unwrap_or(true),
        }
    }

    fn add_chapter_src(&mut self, number: Number, file: &str, source: Source) -> Result<()> {
        let full = self.root.join(file);
        let bytes = match std::fs::read(&full) {
            Ok(b) => b,
            Err(_) => {
                return Err(Error::file_not_found(source, crate::lang::lformat("book chapter"), file.to_string()));
            }
        };
        let content = match String::from_utf8(bytes) {
            Ok(s) => s,
            Err(_) => {
                return Err(Error::parser(
                    source,
                    lformat2("file {file} contains invalid UTF-8", &[("file", file)]),
                ));
            }
        };
        self.add_chapter_from_source(number, file, &content)
    }

    /// Add a chapter from its markdown source
    pub fn add_chapter_from_source(&mut self, number: Number, file: &str, content: &str) -> Result<()> {
        let content = self.handle_yaml_block(content)?;
        let mut parser = Parser::new(self.parser_options());
        let tokens = parser.parse(&content);
        self.features.scan(&tokens);
        self.chapters.push(Chapter {
            number,
            filename: file.to_string(),
            content: tokens,
        });
        Ok(())
    }

    /// Handle an inline YAML block at the beginning of a markdown file
    fn handle_yaml_block(&mut self, content: &str) -> Result<String> {
        let enabled = self.options.get_bool("input.yaml_blocks").unwrap_or(false);
        if !enabled {
            logger::debug("book", "Ignoring YAML block:\n");
            return Ok(content.to_string());
        }
        if !content.starts_with("---\n") {
            logger::debug("book", "Ignoring YAML block:\n");
            return Ok(content.to_string());
        }
        let rest = &content[4..];
        let end = match rest.find("\n---\n") {
            Some(e) => e,
            None => {
                if rest.ends_with("\n---") {
                    rest.len() - 4
                } else {
                    logger::debug("book", "Ignoring YAML block:\n");
                    return Ok(content.to_string());
                }
            }
        };
        let block = &rest[..end + 1];
        let after_start = (4 + end + 5).min(content.len());
        let after = &content[after_start..];
        let docs = yaml::load_from_str(block);
        let full_block = &content[..after_start.min(content.len())];
        match docs {
            Ok(docs) if docs.len() == 1 && docs[0].as_hash().is_some() => {
                let hash = docs[0].as_hash().unwrap().clone();
                for (k, v) in hash {
                    let key = match &k {
                        Yaml::String(s) => s.clone(),
                        other => format!("{:?}", other),
                    };
                    let old = self.options.get(&key).ok().cloned();
                    match self.options.set_yaml(&key, v.clone()) {
                        Ok(_) => {
                            let old_s = match old {
                                Some(crate::bookoptions::BookOption::Str(s))
                                | Some(crate::bookoptions::BookOption::Path(s)) => format!("String({:?})", s),
                                Some(crate::bookoptions::BookOption::Bool(b)) => format!("Boolean({})", b),
                                Some(crate::bookoptions::BookOption::Int(i)) => format!("Integer({})", i),
                                Some(crate::bookoptions::BookOption::Float(f)) => format!("Real({})", f),
                                Some(crate::bookoptions::BookOption::StrVec(v)) => format!("{:?}", v),
                                None => "None".to_string(),
                            };
                            logger::debug(
                                "book",
                                &format!(
                                    "Inline YAML block replaced {:?} previously set to {} to {:?}",
                                    k, old_s, v
                                ),
                            );
                        }
                        Err(e) => {
                            logger::error(
                                "book",
                                &format!("Inline YAML block could not set {:?} to {:?}: {}", k, v, e),
                            );
                        }
                    }
                    for w in self.options.warnings.drain(..) {
                        logger::warn("bookoptions", &w);
                    }
                }
            }
            _ => {
                logger::debug("book", &format!("Ignoring YAML block:\n{}", full_block));
            }
        }
        Ok(after.to_string())
    }

    /// Set options from `--set key value` pairs
    pub fn set_options_from_args(&mut self, pairs: &[String]) -> Result<()> {
        let mut i = 0;
        while i + 1 < pairs.len() {
            let key = &pairs[i];
            let value = &pairs[i + 1];
            match self.options.set(key, value) {
                Ok(_) => {}
                Err(e) => {
                    return Err(Error::default(
                        Source::empty(),
                        lformat2("Error in setting key {key}: {error}", &[("key", key), ("error", &e.to_string())]),
                    ));
                }
            }
            for w in self.options.warnings.drain(..) {
                logger::warn("bookoptions", &w);
            }
            i += 2;
        }
        Ok(())
    }

    /// Get metadata as tokens (parsed as markdown inline)
    pub fn get_metadata_tokens(&self, key: &str) -> Option<Vec<Token>> {
        let s = self.options.get_str(key).ok()?;
        let mut parser = Parser::new(self.parser_options());
        let tokens = parser.parse(s);
        Some(inline_of(tokens))
    }

    /// Returns the title of a chapter (first header), as tokens
    pub fn chapter_title_tokens(&self, chapter: &Chapter) -> Option<Vec<Token>> {
        for t in &chapter.content {
            if let Token::Header(1, inner) = t {
                return Some(inner.clone());
            }
        }
        None
    }

    /// Returns the list of all the formats to render according to options
    pub fn formats_to_render(&self) -> Vec<(String, String)> {
        let mut res = Vec::new();
        // "output" list
        if let Ok(list) = self.options.get_str_vec("output") {
            for fmt in list {
                let key = format!("output.{}", fmt);
                if self.options.is_set(&key) {
                    continue;
                }
                // default filename based on the book file name
                let base = self.source.file.clone().unwrap_or_else(|| "book".to_string());
                let stem = Path::new(&base)
                    .file_stem()
                    .map(|s| s.to_string_lossy().to_string())
                    .unwrap_or(base.clone());
                let ext = match fmt.as_str() {
                    "html.dir" => "".to_string(),
                    "proofread.html" => "proofread.html".to_string(),
                    "proofread.pdf" => "proofread.pdf".to_string(),
                    "proofread.html.dir" => "proofread".to_string(),
                    other => other.to_string(),
                };
                let name = if ext.is_empty() { stem.clone() } else { format!("{}.{}", stem, ext) };
                res.push((fmt.clone(), name));
            }
        }
        for fmt in &["epub", "html", "html.dir", "tex", "pdf", "odt", "proofread.html", "proofread.html.dir", "proofread.pdf"] {
            let key = format!("output.{}", fmt);
            if let Ok(path) = self.options.get_relative_path(&key) {
                res.push((fmt.to_string(), path.to_string()));
            }
        }
        res
    }

    /// Full output path (relative to base_path and root)
    pub fn output_path(&self, file: &str) -> PathBuf {
        let base = self.options.get_relative_path("output.base_path").unwrap_or("").to_string();
        self.root.join(base).join(file)
    }
}

/// Extract inline tokens from a parsed paragraph (used for metadata and part titles)
pub fn inline_of(tokens: Vec<Token>) -> Vec<Token> {
    if tokens.len() == 1 {
        if let Token::Paragraph(inner) = &tokens[0] {
            return inner.clone();
        }
    }
    tokens
}
