//! Miscellaneous helpers: base64, HTML escaping, mime types...

pub fn base64_encode(data: &[u8]) -> String {
    const TABLE: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = String::with_capacity((data.len() + 2) / 3 * 4);
    for chunk in data.chunks(3) {
        let b0 = chunk[0] as u32;
        let b1 = *chunk.get(1).unwrap_or(&0) as u32;
        let b2 = *chunk.get(2).unwrap_or(&0) as u32;
        let n = (b0 << 16) | (b1 << 8) | b2;
        out.push(TABLE[((n >> 18) & 63) as usize] as char);
        out.push(TABLE[((n >> 12) & 63) as usize] as char);
        if chunk.len() > 1 {
            out.push(TABLE[((n >> 6) & 63) as usize] as char);
        } else {
            out.push('=');
        }
        if chunk.len() > 2 {
            out.push(TABLE[(n & 63) as usize] as char);
        } else {
            out.push('=');
        }
    }
    out
}

/// Escape `<`, `>` and `&` (and nothing else), like the original's HTML escaping.
pub fn escape_html(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '&' => out.push_str("&amp;"),
            _ => out.push(c),
        }
    }
    out
}

/// Escape for syntect-like code output (also escapes quotes)
pub fn escape_html_full(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '&' => out.push_str("&amp;"),
            '"' => out.push_str("&quot;"),
            '\'' => out.push_str("&#39;"),
            _ => out.push(c),
        }
    }
    out
}

/// Escape narrow non-breaking spaces: words containing them are wrapped in a span.
pub fn escape_nb_spaces(s: &str) -> String {
    if !s.contains('\u{202f}') {
        return s.to_string();
    }
    let mut out = String::new();
    let mut first = true;
    for word in s.split(' ') {
        if !first {
            out.push(' ');
        }
        first = false;
        if word.contains('\u{202f}') {
            out.push_str("<span class = \"nnbsp\">");
            out.push_str(&word.replace('\u{202f}', "&#160;"));
            out.push_str("</span>");
        } else {
            out.push_str(word);
        }
    }
    out
}

/// Guess the mime type of a file from its extension
pub fn mime_type(path: &str) -> &'static str {
    let lower = path.to_lowercase();
    let ext = lower.rsplit('.').next().unwrap_or("");
    match ext {
        "png" => "image/png",
        "jpg" | "jpeg" => "image/jpeg",
        "gif" => "image/gif",
        "svg" => "image/svg+xml",
        "webp" => "image/webp",
        "bmp" => "image/bmp",
        "ico" => "image/x-icon",
        "tif" | "tiff" => "image/tiff",
        "css" => "text/css",
        "js" => "application/javascript",
        "html" | "htm" => "text/html",
        "xhtml" => "application/xhtml+xml",
        "txt" | "md" => "text/plain",
        "ttf" => "font/ttf",
        "otf" => "font/otf",
        "woff" => "font/woff",
        "woff2" => "font/woff2",
        "pdf" => "application/pdf",
        "json" => "application/json",
        "xml" => "application/xml",
        "mp3" => "audio/mpeg",
        "mp4" => "video/mp4",
        _ => "application/octet-stream",
    }
}

/// Is the url a local file (not a http(s)/mailto/... link)?
pub fn is_local(url: &str) -> bool {
    !(url.contains("://") || url.starts_with("mailto:") || url.starts_with('#') || url.starts_with("data:"))
}

/// Normalize a path by resolving `.` and `..` components (without touching the filesystem)
pub fn normalize_path(p: &str) -> String {
    let mut parts: Vec<&str> = Vec::new();
    let absolute = p.starts_with('/');
    for comp in p.split('/') {
        match comp {
            "" | "." => {}
            ".." => {
                if let Some(last) = parts.last() {
                    if *last != ".." {
                        parts.pop();
                        continue;
                    }
                }
                parts.push("..");
            }
            other => parts.push(other),
        }
    }
    let joined = parts.join("/");
    if absolute {
        format!("/{}", joined)
    } else {
        joined
    }
}
