//! Table of contents, rendered like epub-builder's `Toc`.

#[derive(Debug, Clone)]
pub struct TocElement {
    pub level: i32,
    pub url: String,
    pub title: String,
    /// title used in NCX for nested elements (unnumbered)
    pub raw_title: String,
    pub children: Vec<TocElement>,
}

impl TocElement {
    pub fn new(level: i32, url: &str, title: &str) -> TocElement {
        TocElement {
            level,
            url: url.to_string(),
            title: title.to_string(),
            raw_title: title.to_string(),
            children: Vec::new(),
        }
    }

    fn add(&mut self, elem: TocElement) {
        if let Some(last) = self.children.last_mut() {
            if last.level < elem.level {
                last.add(elem);
                return;
            }
        }
        self.children.push(elem);
    }

    fn render(&self, ol: bool, depth: usize, out: &mut String) {
        let indent = "    ".repeat(depth);
        let tag = if ol { "ol" } else { "ul" };
        if self.children.is_empty() {
            out.push_str(&format!("{}  <li><a href=\"{}\">{}</a></li>\n", indent, self.url, self.title));
        } else {
            out.push_str(&format!("{}  <li>\n{}    <a href=\"{}\">{}</a>\n{}    <{}>\n", indent, indent, self.url, self.title, indent, tag));
            for c in &self.children {
                c.render(ol, depth + 1, out);
            }
            out.push_str(&format!("{}    </{}>\n{}  </li>\n", indent, tag, indent));
        }
    }

    fn render_ncx(&self, depth: usize, counter: &mut usize, out: &mut String, numbered: bool) {
        let indent = "  ".repeat(depth);
        *counter += 1;
        let title = if numbered { &self.title } else { &self.raw_title };
        out.push_str(&format!(
            "{}    <navPoint playOrder=\"{}\" id=\"navPoint-{}\">\n{}      <navLabel>\n{}       <text>{}</text>\n{}      </navLabel>\n{}      <content src=\"{}\"/>\n",
            indent, counter, counter, indent, indent, title, indent, indent, self.url
        ));
        for c in &self.children {
            c.render_ncx(depth + 1, counter, out, false);
        }
        out.push_str(&format!("{}    </navPoint>\n", indent));
    }

    fn max_depth(&self) -> usize {
        1 + self.children.iter().map(|c| c.max_depth()).max().unwrap_or(0)
    }
}

#[derive(Debug, Clone, Default)]
pub struct Toc {
    pub elements: Vec<TocElement>,
}

impl Toc {
    pub fn new() -> Toc {
        Toc::default()
    }

    pub fn is_empty(&self) -> bool {
        self.elements.is_empty()
    }

    pub fn len(&self) -> usize {
        self.elements.len()
    }

    pub fn add(&mut self, elem: TocElement) {
        if let Some(last) = self.elements.last_mut() {
            if last.level < elem.level {
                last.add(elem);
                return;
            }
        }
        self.elements.push(elem);
    }

    /// Render as HTML list (`ul` if `ol` is false)
    pub fn render(&self, ol: bool) -> String {
        let tag = if ol { "ol" } else { "ul" };
        let mut out = format!("    <{}>\n", tag);
        for e in &self.elements {
            e.render(ol, 1, &mut out);
        }
        out.push_str(&format!("    </{}>\n", tag));
        out
    }

    /// Render the NCX navMap content
    pub fn render_ncx(&self) -> String {
        let mut out = String::new();
        let mut counter = 0;
        for e in &self.elements {
            e.render_ncx(0, &mut counter, &mut out, true);
        }
        out
    }

    pub fn depth(&self) -> usize {
        self.elements.iter().map(|e| e.max_depth()).max().unwrap_or(0)
    }
}
