//! Core HTML rendering of tokens, shared by the standalone HTML, multi-file HTML and EPUB renderers.

use crate::book::{Book, Chapter};
use crate::cleaner::Cleaner;
use crate::error::{Error, Result, Source};
use crate::lang::book_lformat;
use crate::misc::{base64_encode, escape_html, escape_html_full, escape_nb_spaces, is_local, mime_type};
use crate::number::{roman, Number};
use crate::templates::{Context, Template, HTML_SYNTAX};
use crate::toc::{Toc, TocElement};
use crate::token::Token;

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum ImageMode {
    /// Embed images as base64 data URIs
    Base64,
    /// Copy images to a directory and reference them
    Files,
}

pub struct HtmlRenderer<'a> {
    pub book: &'a Book,
    pub cleaner: Cleaner,
    pub current_chapter: [i32; 6],
    pub current_numbering: i32,
    pub current_part: i32,
    pub current_hide: bool,
    pub current_is_part: bool,
    pub current_numbered: bool,
    pub table_head: bool,
    pub footnotes: Vec<(String, String)>,
    pub footnote_chapter: usize,
    pub para_counter: usize,
    pub link_counter: usize,
    pub toc: Toc,
    pub verbatim: bool,
    pub first_paragraph: bool,
    pub epub3: bool,
    pub epub: bool,
    pub image_mode: ImageMode,
    /// (source path, destination path) of images to copy
    pub images: Vec<(String, String)>,
    pub image_counter: usize,
    pub filename: String,
    pub source: Source,
    pub chapter_template: Template,
    pub part_template: Template,
    pub initials: bool,
    pub escape_nb_spaces: bool,
    pub highlight: String,
    /// prefix for links to chapters (html.dir), e.g. "chapter_000.html"
    pub link_prefix: String,
    /// errors (e.g. missing images) encountered
    pub error: Option<Error>,
}

impl<'a> HtmlRenderer<'a> {
    pub fn new(book: &'a Book, image_mode: ImageMode) -> Result<HtmlRenderer<'a>> {
        let chapter_template = Template::compile(
            book.options.get_str("html.chapter.template").unwrap_or(""),
            &HTML_SYNTAX,
        )
        .map_err(|e| Error::template(book.source.clone(), e.to_string()))?;
        let part_template = Template::compile(book.options.get_str("html.part.template").unwrap_or(""), &HTML_SYNTAX)
            .map_err(|e| Error::template(book.source.clone(), e.to_string()))?;
        Ok(HtmlRenderer {
            book,
            cleaner: book.cleaner(),
            current_chapter: [0; 6],
            current_numbering: book.options.get_i32("rendering.num_depth").unwrap_or(1),
            current_part: 0,
            current_hide: false,
            current_is_part: false,
            current_numbered: true,
            table_head: false,
            footnotes: Vec::new(),
            footnote_chapter: 0,
            para_counter: 0,
            link_counter: 0,
            toc: Toc::new(),
            verbatim: false,
            first_paragraph: false,
            epub3: false,
            epub: false,
            image_mode,
            images: Vec::new(),
            image_counter: 0,
            filename: String::new(),
            source: book.source.clone(),
            chapter_template,
            part_template,
            initials: book.options.get_bool("rendering.initials").unwrap_or(false),
            escape_nb_spaces: book.options.get_bool("html.escape_nb_spaces").unwrap_or(true),
            highlight: book.options.get_str("rendering.highlight").unwrap_or("syntect").to_string(),
            link_prefix: String::new(),
            error: None,
        })
    }

    /// Set state for rendering chapter `i`
    pub fn start_chapter(&mut self, i: usize, chapter: &Chapter) {
        self.footnote_chapter = i + 1;
        self.filename = chapter.filename.clone();
        self.source = Source::new(&chapter.filename);
        self.current_hide = false;
        self.current_is_part = false;
        self.current_numbered = true;
        self.first_paragraph = false;
        match chapter.number {
            Number::Hidden => {
                self.current_hide = true;
                self.current_numbered = false;
            }
            Number::Unnumbered => {
                self.current_numbered = false;
            }
            Number::Default => {}
            Number::Specified(n) => {
                self.current_chapter[0] = n - 1;
            }
            Number::DefaultPart => {
                self.current_is_part = true;
            }
            Number::UnnumberedPart => {
                self.current_is_part = true;
                self.current_numbered = false;
            }
            Number::SpecifiedPart(n) => {
                self.current_is_part = true;
                self.current_part = n - 1;
            }
        }
    }

    fn chapter_word(&self) -> String {
        if let Ok(s) = self.book.options.get_str("rendering.chapter") {
            return s.to_string();
        }
        book_lformat(self.book, "Chapter")
    }

    fn part_word(&self) -> String {
        if let Ok(s) = self.book.options.get_str("rendering.part") {
            return s.to_string();
        }
        book_lformat(self.book, "Part")
    }

    /// Format the number of the current chapter (level 1)
    fn chapter_number_str(&self) -> String {
        let n = self.current_chapter[0];
        if self.book.options.get_bool("rendering.chapter.roman_numerals").unwrap_or(false) {
            roman(n)
        } else {
            n.to_string()
        }
    }

    fn part_number_str(&self) -> String {
        let n = self.current_part;
        if self.book.options.get_bool("rendering.part.roman_numerals").unwrap_or(true) {
            roman(n)
        } else {
            n.to_string()
        }
    }

    /// Render the numbering prefix for a header of level n (>= 2)
    fn number_prefix(&self, level: usize) -> String {
        let mut parts = Vec::new();
        parts.push(self.chapter_number_str());
        for i in 1..level {
            parts.push(self.current_chapter[i].to_string());
        }
        format!("{}. ", parts.join("."))
    }

    /// Render the title of a chapter for the TOC, from the rendering.chapter.template
    pub fn toc_chapter_title(&self, title_html: &str, number: &str, is_part: bool) -> String {
        let tpl_src = if is_part {
            self.book.options.get_str("rendering.part.template").unwrap_or("{{number}}. {{part_title}}")
        } else {
            self.book
                .options
                .get_str("rendering.chapter.template")
                .unwrap_or("{{number}}. {{chapter_title}}")
        };
        let mut ctx = Context::new();
        ctx.insert("number", number);
        ctx.insert("chapter_title", title_html);
        ctx.insert("part_title", title_html);
        match Template::compile(tpl_src, &HTML_SYNTAX).and_then(|t| t.render(&ctx)) {
            Ok(s) => s,
            Err(_) => title_html.to_string(),
        }
    }

    /// Render a list of tokens
    pub fn render_vec(&mut self, tokens: &[Token]) -> String {
        let mut out = String::new();
        for t in tokens {
            out.push_str(&self.render_token(t));
        }
        out
    }

    /// Render tokens as plain text (used for `_raw` values), without cleaning
    pub fn view_as_text(tokens: &[Token]) -> String {
        let mut out = String::new();
        for t in tokens {
            match t {
                Token::Str(s) => out.push_str(s),
                Token::Code(s) => out.push_str(s),
                Token::SoftBreak => out.push(' '),
                Token::HardBreak => out.push('\n'),
                Token::CodeBlock(_, s) => out.push_str(s),
                Token::Footnote(..) => {}
                other => {
                    if let Some(inner) = other.inner() {
                        out.push_str(&Self::view_as_text(inner));
                    }
                }
            }
        }
        out
    }

    fn clean_text(&self, s: &str) -> String {
        let cleaned = self.cleaner.clean(s, false);
        let escaped = escape_html(&cleaned);
        if self.escape_nb_spaces {
            escape_nb_spaces(&escaped)
        } else {
            escaped
        }
    }

    pub fn render_token(&mut self, token: &Token) -> String {
        match token {
            Token::Str(s) => {
                if self.verbatim {
                    escape_html(s)
                } else {
                    self.clean_text(s)
                }
            }
            Token::Paragraph(inner) => {
                self.para_counter += 1;
                let id = self.para_counter;
                let class = if self.initials && self.first_paragraph {
                    " class = \"first-para\""
                } else {
                    ""
                };
                self.first_paragraph = false;
                let content = self.render_vec(inner);
                format!("<p id = \"para-{}\"{}>{}</p>\n", id, class, content)
            }
            Token::Header(level, inner) => self.render_header(*level, inner),
            Token::Emphasis(inner) => format!("<em>{}</em>", self.render_vec(inner)),
            Token::Strong(inner) => format!("<b>{}</b>", self.render_vec(inner)),
            Token::Strikethrough(inner) => format!("<del>{}</del>", self.render_vec(inner)),
            Token::Superscript(inner) => format!("<sup>{}</sup>", self.render_vec(inner)),
            Token::Subscript(inner) => format!("<sub>{}</sub>", self.render_vec(inner)),
            Token::Code(s) => format!("<code>{}</code>", escape_html(s)),
            Token::BlockQuote(inner) => format!("<blockquote>{}</blockquote>\n", self.render_vec(inner)),
            Token::CodeBlock(lang, code) => self.render_code_block(lang, code),
            Token::Rule => "<p class = \"rule\">***</p>\n".to_string(),
            Token::SoftBreak => " ".to_string(),
            Token::HardBreak => "<br />\n".to_string(),
            Token::List(items) => format!("<ul>\n{}</ul>\n", self.render_vec(items)),
            Token::OrderedList(start, items) => {
                let attr = if *start == 1 { String::new() } else { format!(" start = \"{}\"", start) };
                format!("<ol{}>\n{}</ol>\n", attr, self.render_vec(items))
            }
            Token::Item(inner) => format!("<li>{}</li>\n", self.render_vec(inner)),
            Token::TaskItem(checked, inner) => {
                let checked_attr = if *checked { " checked = \"\"" } else { " " };
                format!(
                    "<input type = \"checkbox\" disabled = \"\"{}/>{}",
                    checked_attr,
                    self.render_vec(inner)
                )
            }
            Token::Table(_, rows) => {
                let inner = self.render_vec(rows);
                format!("<div class = \"table\">\n    <table>\n{}\n    </table>\n</div>\n", inner)
            }
            Token::TableHead(cells) => {
                self.table_head = true;
                let s = format!("<tr>\n{}</tr>\n", self.render_vec(cells));
                self.table_head = false;
                s
            }
            Token::TableRow(cells) => format!("<tr>\n{}</tr>\n", self.render_vec(cells)),
            Token::TableCell(inner) => {
                let tag = if self.table_head { "th" } else { "td" };
                format!("<{}>{}</{}>", tag, self.render_vec(inner), tag)
            }
            Token::Footnote(label, content) => self.render_footnote(label, content),
            Token::Link(url, title, inner) => {
                let content = self.render_vec(inner);
                let url = self.resolve_link(url);
                if title.is_empty() {
                    format!("<a href = \"{}\">{}</a>", escape_html(&url), content)
                } else {
                    format!("<a href = \"{}\" title = \"{}\">{}</a>", escape_html(&url), title, content)
                }
            }
            Token::Image(url, title, alt) => self.render_image(url, title, alt, false),
            Token::StandaloneImage(url, title, alt) => self.render_image(url, title, alt, true),
            Token::DescriptionList(inner) => format!("<dl>\n{}</dl>\n", self.render_vec(inner)),
            Token::DescriptionItem(inner) => self.render_vec(inner),
            Token::DescriptionTerm(inner) => format!("<dt>{}</dt>\n", self.render_vec(inner)),
            Token::DescriptionDetails(inner) => format!("<dd>{}</dd>\n", self.render_vec(inner)),
            Token::Annotation(_, inner) => self.render_vec(inner),
        }
    }

    fn resolve_link(&self, url: &str) -> String {
        url.to_string()
    }

    fn render_header(&mut self, level: i32, inner: &[Token]) -> String {
        if level == 1 {
            // new chapter or part
            if self.current_is_part {
                if self.current_numbered {
                    self.current_part += 1;
                    if self.book.options.get_bool("rendering.part.reset_counter").unwrap_or(true) {
                        self.current_chapter = [0; 6];
                    }
                }
            } else if self.current_numbered {
                self.current_chapter[0] += 1;
                for i in 1..6 {
                    self.current_chapter[i] = 0;
                }
            }
            self.link_counter += 1;
            let link = self.link_counter;
            let title_html = self.render_vec(inner);
            let title_raw = Self::view_as_text(inner);
            self.first_paragraph = true;
            let url = format!("{}#link-{}", self.link_prefix, link);
            if self.current_hide {
                self.toc.add(TocElement::new(1, &url, &title_html));
                let mut e = self.toc.elements.pop().unwrap();
                e.raw_title = title_raw;
                self.toc.add(e);
                return format!("<h1 id = \"link-{}\"></h1>", link);
            }
            if self.current_is_part {
                let number = self.part_number_str();
                let toc_title = if self.current_numbered {
                    self.toc_chapter_title(&title_html, &number, true)
                } else {
                    title_html.clone()
                };
                let toc_raw = if self.current_numbered {
                    self.toc_chapter_title(&title_raw, &number, true)
                } else {
                    title_raw.clone()
                };
                let mut e = TocElement::new(0, &url, &toc_title);
                e.raw_title = toc_raw;
                self.toc.add(e);
                let mut ctx = Context::new();
                ctx.insert("link", link.to_string());
                ctx.insert("header", self.part_word());
                ctx.insert("number", number);
                ctx.insert("title", title_html);
                ctx.insert_bool("has_number", self.current_numbered);
                ctx.insert_bool("has_title", !inner.is_empty());
                return match self.part_template.render(&ctx) {
                    Ok(s) => s,
                    Err(e) => {
                        self.error = Some(Error::template(self.source.clone(), e.to_string()));
                        String::new()
                    }
                };
            }
            let number = self.chapter_number_str();
            let toc_title = if self.current_numbered {
                self.toc_chapter_title(&title_html, &number, false)
            } else {
                title_html.clone()
            };
            let toc_raw = if self.current_numbered {
                self.toc_chapter_title(&title_raw, &number, false)
            } else {
                title_raw.clone()
            };
            let mut e = TocElement::new(1, &url, &toc_title);
            e.raw_title = toc_raw;
            self.toc.add(e);
            let mut ctx = Context::new();
            ctx.insert("link", link.to_string());
            ctx.insert("header", self.chapter_word());
            ctx.insert("number", number);
            ctx.insert("title", title_html);
            ctx.insert_bool("has_number", self.current_numbered);
            ctx.insert_bool("has_title", !inner.is_empty());
            match self.chapter_template.render(&ctx) {
                Ok(s) => s,
                Err(e) => {
                    self.error = Some(Error::template(self.source.clone(), e.to_string()));
                    String::new()
                }
            }
        } else {
            let lvl = level as usize;
            self.link_counter += 1;
            let link = self.link_counter;
            let numbered = (lvl as i32) <= self.current_numbering;
            if numbered {
                self.current_chapter[lvl - 1] += 1;
                for i in lvl..6 {
                    self.current_chapter[i] = 0;
                }
            }
            let title_html = self.render_vec(inner);
            let title_raw = Self::view_as_text(inner);
            let (title_html, title_raw) = if numbered {
                let prefix = self.number_prefix(lvl);
                (format!("{}{}", prefix, title_html), format!("{}{}", prefix, title_raw))
            } else {
                (title_html, title_raw)
            };
            if numbered {
                let url = format!("{}#link-{}", self.link_prefix, link);
                let mut e = TocElement::new(level, &url, &title_html);
                e.raw_title = title_raw;
                self.toc.add(e);
            }
            format!("<h{} id = \"link-{}\">{}</h{}>\n", level, link, title_html, level)
        }
    }

    fn render_code_block(&mut self, lang: &str, code: &str) -> String {
        match self.highlight.as_str() {
            "syntect" => {
                let highlighted = crate::syntax::highlight_html(lang, code);
                format!("<pre>{}</pre>", highlighted)
            }
            _ => {
                if lang.is_empty() {
                    format!("<pre><code>{}</code></pre>\n", code)
                } else {
                    format!("<pre><code class = \"language-{}\">{}</code></pre>\n", lang, code)
                }
            }
        }
    }

    fn render_footnote(&mut self, label: &str, content: &[Token]) -> String {
        let number = label.to_string();
        let was_first = self.first_paragraph;
        let rendered = self.render_vec(content);
        self.first_paragraph = was_first;
        if !self.footnotes.iter().any(|(l, _)| l == &number) {
            self.footnotes.push((number.clone(), rendered));
        }
        if self.epub {
            format!(
                "<a  href = \"#note-dest-{n}\"><sup id = \"note-source-{n}\">[{n}]</sup></a>",
                n = number
            )
        } else {
            format!(
                "<a class = \"footnote_reference\" href = \"#note-dest-{c}-{n}\" id = \"note-source-{c}-{n}\"><sup>[{n}]</sup></a>",
                c = self.footnote_chapter,
                n = number
            )
        }
    }

    /// Render accumulated footnotes for the current chapter
    pub fn render_footnotes(&mut self) -> String {
        if self.footnotes.is_empty() {
            return String::new();
        }
        let notes = std::mem::take(&mut self.footnotes);
        let mut out = String::new();
        let title = book_lformat(self.book, "Notes");
        if self.epub {
            out.push_str(&format!(
                "<div class = \"notes\" >\n <h2 class = \"notes\">{}</h2>\n<table class = \"notes\">\n",
                title
            ));
            for (n, content) in &notes {
                out.push_str(&format!(
                    "<tr class = \"notes\">\n <td class = \"note-number\">\n  <p class = \"note-number\">\n  <a href = \"#note-source-{n}\">[{n}]</a>\n</p>\n\n </td>\n <td class = \"note\">\n  <a id = \"note-dest-{n}\" />{content}\n  </td>\n</tr>\n",
                    n = n,
                    content = content
                ));
            }
            out.push_str("</table>\n</div>\n");
        } else {
            out.push_str(&format!(
                "<section class = \"notes\" >\n <h2 class = \"notes\">{}</h2>\n<table class = \"notes\">\n",
                title
            ));
            for (n, content) in &notes {
                out.push_str(&format!(
                    "<tr class = \"notes\">\n <td class = \"note-number\">\n  <p class = \"note-number\">\n  <a rel = \"footnote\" href = \"#note-source-{c}-{n}\">[{n}]</a>\n</p>\n\n </td>\n <td class = \"note\">\n  <aside class = \"footnote\" id = \"note-dest-{c}-{n}\">{content}</aside>\n  </td>\n</tr>\n",
                    c = self.footnote_chapter,
                    n = n,
                    content = content
                ));
            }
            out.push_str("</table>\n</section>\n");
        }
        out
    }

    /// Resolve an image: returns the src attribute value
    fn image_src(&mut self, url: &str) -> Option<String> {
        if !is_local(url) {
            return Some(url.to_string());
        }
        // find the file relative to the images base path
        let base = self
            .book
            .options
            .get_relative_path("resources.base_path")
            .ok()
            .filter(|s| !s.is_empty())
            .map(|s| s.to_string())
            .or_else(|| self.book.options.get_relative_path("resources.base_path.images").ok().map(|s| s.to_string()))
            .unwrap_or_else(|| ".".to_string());
        let rel = format!("{}/{}", base.trim_end_matches('/'), url);
        let full = self.book.root.join(&rel);
        let data = match std::fs::read(&full) {
            Ok(d) => d,
            Err(_) => {
                self.error = Some(Error::file_not_found(
                    self.source.clone(),
                    crate::lang::lformat("image"),
                    rel.clone(),
                ));
                return None;
            }
        };
        match self.image_mode {
            ImageMode::Base64 => {
                let mime = mime_type(url);
                Some(format!("data:{};base64,{}", mime, base64_encode(&data)))
            }
            ImageMode::Files => {
                // images/image_N.ext
                let ext = std::path::Path::new(url)
                    .extension()
                    .map(|e| format!(".{}", e.to_string_lossy()))
                    .unwrap_or_default();
                let dest = format!("images/image_{}{}", self.image_counter, ext);
                self.image_counter += 1;
                self.images.push((full.to_string_lossy().to_string(), dest.clone()));
                Some(dest)
            }
        }
    }

    fn render_image(&mut self, url: &str, title: &str, alt: &[Token], standalone: bool) -> String {
        let alt_text = self.render_vec(alt);
        let src = match self.image_src(url) {
            Some(s) => s,
            None => return String::new(),
        };
        let img = format!("<img src = \"{}\" title = \"{}\" alt = \"{}\" />", src, title, alt_text);
        if standalone {
            format!("<div class = \"image\">\n  {}\n</div>", img)
        } else {
            img
        }
    }

    /// Render a code block highlighted (helper for other renderers)
    pub fn escape_code(code: &str) -> String {
        escape_html_full(code)
    }
}

/// Convert paragraphs containing only an image into standalone images
pub fn mark_standalone_images(tokens: &mut Vec<Token>) {
    for t in tokens.iter_mut() {
        if let Token::Paragraph(inner) = t {
            let non_ws: Vec<&Token> = inner
                .iter()
                .filter(|x| match x {
                    Token::Str(s) => !s.trim().is_empty(),
                    Token::SoftBreak => false,
                    _ => true,
                })
                .collect();
            if non_ws.len() == 1 {
                if let Token::Image(u, ti, a) = non_ws[0] {
                    *t = Token::StandaloneImage(u.clone(), ti.clone(), a.clone());
                    continue;
                }
            }
        }
        if let Some(inner) = t.inner_mut() {
            mark_standalone_images(inner);
        }
    }
}
