//! Code highlighting. Real syntax highlighting (syntect) can't be reproduced
//! exactly; we render code as plain text in the same way syntect does for
//! unknown languages.

use crate::misc::escape_html_full;

/// Highlight code for HTML output: each line wrapped in a span with the default color.
pub fn highlight_html(_lang: &str, code: &str) -> String {
    let mut out = String::new();
    let mut lines: Vec<&str> = code.split('\n').collect();
    // code normally ends with '\n', giving a trailing empty segment
    if lines.last() == Some(&"") && code.ends_with('\n') {
        lines.pop();
        lines.push("");
    }
    for line in lines {
        if line.is_empty() {
            out.push('\n');
        } else {
            out.push_str("<span style=\"color:#323232;\">");
            out.push_str(&escape_html_full(line));
            out.push_str("</span>\n");
        }
    }
    out
}

/// Highlight code for LaTeX output
pub fn highlight_tex(_lang: &str, code: &str) -> String {
    let mut out = String::from("{\\sloppy ");
    let mut lines: Vec<&str> = code.split('\n').collect();
    if lines.last() == Some(&"") && code.ends_with('\n') {
        lines.pop();
        lines.push("");
    }
    for line in lines {
        if !line.is_empty() {
            out.push_str("\\textcolor[rgb]{0.19607843, 0.19607843, 0.19607843}{\\texttt{");
            out.push_str(&crate::latex::escape_tex_code(line));
            out.push_str("}}");
        }
        out.push_str("\\\\{}\n");
    }
    out.push_str("}\n");
    out
}
