//! Standalone HTML renderer

use crate::book::Book;
use crate::error::{Error, Result, Source};
use crate::html::{HtmlRenderer, ImageMode};
use crate::lang::book_lformat;
use crate::misc::{base64_encode, mime_type};
use crate::templates::{default_template, Context, Template, BOOK_SVG, HTML_SYNTAX, MENU_SVG, PAGES_SVG};

/// Get the content of a template: from the file set in options, or the default.
pub fn get_template(book: &Book, name: &str) -> Result<String> {
    if book.options.is_set(name) {
        if let Ok(path) = book.options.get_relative_path(name) {
            let base = book
                .options
                .get_relative_path("resources.base_path")
                .ok()
                .filter(|s| !s.is_empty())
                .map(|s| s.to_string())
                .or_else(|| book.options.get_relative_path("resources.base_path.templates").ok().map(|s| s.to_string()))
                .unwrap_or_else(|| ".".to_string());
            let rel = format!("{}/{}", base.trim_end_matches('/'), path);
            let full = book.root.join(&rel);
            return std::fs::read_to_string(&full).map_err(|_| {
                Error::config_parser(
                    book.source_without_line(),
                    crate::lang::lformat2("file '{file}' could not be read", &[("file", &rel)]),
                )
            });
        }
    }
    default_template(name)
        .map(|s| s.to_string())
        .ok_or_else(|| Error::default(Source::empty(), format!("no template {}", name)))
}

fn render_template(book: &Book, name: &str, ctx: &Context) -> Result<String> {
    let src = get_template(book, name)?;
    let tpl = Template::compile(&src, &HTML_SYNTAX).map_err(|e| Error::template(book.source.clone(), e.to_string()))?;
    tpl.render(ctx).map_err(|e| Error::template(book.source.clone(), e.to_string()))
}

/// Render the CSS (html.css) with its sub-templates
pub fn render_css(book: &Book, css_name: &str) -> Result<String> {
    let mut ctx = Context::new();
    ctx.insert("lang", book.options.get_str("lang").unwrap_or("en"));
    let additional = book.options.get_str(&format!("{}.add", css_name)).unwrap_or("").to_string();
    ctx.insert("additional_code", additional);
    if css_name == "html.css" {
        let colors = render_template(book, "html.css.colors", &Context::new())?;
        ctx.insert("colors", colors);
    }
    render_template(book, css_name, &ctx)
}

/// The JSON-LD metadata block
pub fn json_data(book: &Book) -> String {
    let get = |k: &str| book.options.get_str(k).ok().map(|s| s.to_string());
    let opt = |k: &str, field: &str| -> String {
        match get(k) {
            Some(v) => format!("    \"{}\": \"{}\",\n", field, v),
            None => "    \n".to_string(),
        }
    };
    format!(
        "\n<script type = 'application/ld+json'>\n{{\n    \"@context\": \"http://schema.org/\",\n    \"@type\": \"Book\",\n    \"author\": \"{}\",\n    \"name\": \"{}\",\n{}{}{}{}{}    \"inLanguage\": \"{}\"\n}}\n</script>\n",
        get("author").unwrap_or_default(),
        get("title").unwrap_or_default(),
        opt("version", "version"),
        opt("subtitle", "alternateName"),
        opt("subject", "keywords"),
        opt("license", "license"),
        opt("description", "about"),
        get("lang").unwrap_or_default(),
    )
}

/// Render metadata (title, author...) as HTML and raw text
pub fn metadata(renderer: &mut HtmlRenderer, key: &str) -> (String, String) {
    match renderer.book.get_metadata_tokens(key) {
        Some(tokens) => {
            let html = renderer.render_vec(&tokens);
            let raw = HtmlRenderer::view_as_text(&tokens);
            (html, raw)
        }
        None => (String::new(), String::new()),
    }
}

pub fn render(book: &Book) -> Result<String> {
    let mut r = HtmlRenderer::new(book, ImageMode::Base64)?;
    let one_chapter = book.options.get_bool("html.standalone.one_chapter").unwrap_or(false);
    let inline_toc = book.options.get_bool("rendering.inline_toc").unwrap_or(false);

    // Render chapters
    let mut content = String::new();
    for (i, chapter) in book.chapters.iter().enumerate() {
        r.start_chapter(i, chapter);
        let mut tokens = chapter.content.clone();
        crate::html::mark_standalone_images(&mut tokens);
        let body = r.render_vec(&tokens);
        let notes = r.render_footnotes();
        content.push_str(&format!("<div id = \"chapter-{}\" class = \"chapter\">\n  {}{}\n</div>", i, body, notes));
        if let Some(e) = r.error.take() {
            return Err(e);
        }
    }
    // inline toc
    let toc_html = r.toc.render(false);
    if inline_toc {
        let toc_title = render_toc_name(book);
        content = format!("<div id = \"toc\">\n  <h1>{}</h1>\n  {}</div>\n{}", toc_title, toc_html, content);
    }
    // header / footer
    let footer = match book.options.get_str("html.footer") {
        Ok(_) => {
            let tokens = book.get_metadata_tokens("html.footer").unwrap_or_default();
            let tokens = vec![crate::token::Token::Paragraph(tokens)];
            format!("<footer id = \"footer\">{}</footer>", r.render_vec(&tokens))
        }
        Err(_) => String::new(),
    };
    let header = match book.options.get_str("html.header") {
        Ok(_) => {
            let tokens = book.get_metadata_tokens("html.header").unwrap_or_default();
            let tokens = vec![crate::token::Token::Paragraph(tokens)];
            format!("<div id = \"top\">{}</div>", r.render_vec(&tokens))
        }
        Err(_) => String::new(),
    };

    let mut ctx = Context::new();
    ctx.insert("lang", book.options.get_str("lang").unwrap_or("en"));
    let (title, title_raw) = metadata(&mut r, "title");
    let (author, author_raw) = metadata(&mut r, "author");
    let (subtitle, _) = metadata(&mut r, "subtitle");
    let (autograph, _) = metadata(&mut r, "autograph");
    ctx.insert("title", title);
    ctx.insert("title_raw", title_raw);
    ctx.insert("author", author);
    ctx.insert("author_raw", author_raw);
    ctx.insert_bool("has_subtitle", book.options.is_set("subtitle"));
    ctx.insert("subtitle", subtitle);
    ctx.insert_bool("has_autograph", book.options.is_set("autograph"));
    ctx.insert("autograph", autograph);
    ctx.insert("content", content);
    ctx.insert("header", header);
    ctx.insert("footer", footer);
    ctx.insert("toc", toc_html);
    ctx.insert_bool("has_toc", r.toc.len() > 1);
    ctx.insert_bool("one_chapter", one_chapter);
    ctx.insert("loc_toc", book_lformat(book, "Table of contents"));
    ctx.insert("loc_display_all", book_lformat(book, "Display all chapters"));
    ctx.insert("loc_display_one", book_lformat(book, "Display one chapter"));
    ctx.insert("book_svg", format!("data:image/svg+xml;base64,{}", base64_encode(BOOK_SVG.as_bytes())));
    ctx.insert("menu_svg", format!("data:image/svg+xml;base64,{}", base64_encode(MENU_SVG.as_bytes())));
    ctx.insert("json_data", json_data(book));
    // favicon
    let favicon = match book.options.get_relative_path("html.icon") {
        Ok(icon) => {
            let base = book
                .options
                .get_relative_path("resources.base_path")
                .ok()
                .filter(|s| !s.is_empty())
                .map(|s| s.to_string())
                .or_else(|| book.options.get_relative_path("resources.base_path.images").ok().map(|s| s.to_string()))
                .unwrap_or_else(|| ".".to_string());
            let rel = format!("{}/{}", base.trim_end_matches('/'), icon);
            let full = book.root.join(&rel);
            match std::fs::read(&full) {
                Ok(data) => format!(
                    "<link rel = \"icon\" href = \"data:{};base64,{}\">",
                    mime_type(icon),
                    base64_encode(&data)
                ),
                Err(_) => {
                    return Err(Error::file_not_found(book.source.clone(), "icon".to_string(), rel));
                }
            }
        }
        Err(_) => String::new(),
    };
    ctx.insert("favicon", favicon);
    // style
    let style = render_css(book, "html.css")?;
    ctx.insert("style", style);
    let print_style = render_template(book, "html.css.print", &Context::new())?;
    ctx.insert("print_style", print_style);
    // highlighting
    let highlight = book.options.get_str("rendering.highlight").unwrap_or("syntect");
    let highlight_code = highlight == "highlight.js";
    ctx.insert_bool("highlight_code", highlight_code);
    if highlight_code {
        let css = get_template(book, "html.highlight.css")?;
        let js = get_template(book, "html.highlight.js")?;
        ctx.insert("highlight_css", css);
        ctx.insert(
            "highlight_js",
            format!("data:text/javascript;base64,{}", base64_encode(js.as_bytes())),
        );
    } else {
        ctx.insert("highlight_css", "");
        ctx.insert("highlight_js", "");
    }
    // script
    let common = get_template(book, "html.js")?;
    let mut sctx = Context::new();
    sctx.insert("common_script", common);
    sctx.insert_bool("one_chapter", one_chapter);
    sctx.insert("pages_svg", format!("data:image/svg+xml;base64,{}", base64_encode(PAGES_SVG.as_bytes())));
    sctx.insert("book_svg", format!("data:image/svg+xml;base64,{}", base64_encode(BOOK_SVG.as_bytes())));
    sctx.insert("loc_display_one", book_lformat(book, "Display one chapter"));
    sctx.insert("loc_display_all", book_lformat(book, "Display all chapters"));
    let script = render_template(book, "html.standalone.js", &sctx)?;
    ctx.insert("script", script);

    render_template(book, "html.standalone.template", &ctx)
}

/// Render the name of the inline TOC (rendering.inline_toc.name)
pub fn render_toc_name(book: &Book) -> String {
    let src = book.options.get_str("rendering.inline_toc.name").unwrap_or("{{loc_toc}}");
    let mut ctx = Context::new();
    ctx.insert("loc_toc", book_lformat(book, "Table of contents"));
    match Template::compile(src, &HTML_SYNTAX).and_then(|t| t.render(&ctx)) {
        Ok(s) => s,
        Err(_) => src.to_string(),
    }
}
