    ctx.insert("menu_svg", format!("data:image/svg+xml;base64,{}", base64_encode(MENU_SVG.as_bytes())));
    ctx.insert("json_data", json_data(book));
    // favicon
    let favicon = match book.options.get_relative_path("html.icon") {
        Ok(icon) => {
            let base = book
                .options
                .get_relative_path("resources.base_path")
                .ok()
                .filter(|s| !s.is_empty())
                .map(|s| s.to_string())
                .or_else(|| book.options.get_relative_path("resources.base_path.images").ok().map(|s| s.to_string()))
                .unwrap_or_else(|| ".".to_string());
            let rel = format!("{}/{}", base.trim_end_matches('/'), icon);
            let full = book.root.join(&rel);
            match std::fs::read(&full) {
                Ok(data) => format!(
                    "<link rel = \"icon\" href = \"data:{};base64,{}\">",
                    mime_type(icon),
                    base64_encode(&data)
                ),
                Err(_) => {
                    return Err(Error::file_not_found(book.source.clone(), "icon".to_string(), rel));
                }
            }
        }
        Err(_) => String::new(),
    };
    ctx.insert("favicon", favicon);
    // style
    let style = render_css(book, "html.css")?;
    ctx.insert("style", style);
    let print_style = render_template(book, "html.css.print", &Context::new())?;
    ctx.insert("print_style", print_style);
    // highlighting
    let highlight = book.options.get_str("rendering.highlight").unwrap_or("syntect");
    let highlight_code = highlight == "highlight.js";
    ctx.insert_bool("highlight_code", highlight_code);
    if highlight_code {
        let css = get_template(book, "html.highlight.css")?;
        let js = get_template(book, "html.highlight.js")?;
        ctx.insert("highlight_css", css);
        ctx.insert(
            "highlight_js",
            format!("data:text/javascript;base64,{}", base64_encode(js.as_bytes())),
        );
    } else {
        ctx.insert("highlight_css", "");
        ctx.insert("highlight_js", "");
    }
    // script
    let common = get_template(book, "html.js")?;
    let mut sctx = Context::new();
    sctx.insert("common_script", common);
    sctx.insert_bool("one_chapter", one_chapter);
    sctx.insert("pages_svg", format!("data:image/svg+xml;base64,{}", base64_encode(PAGES_SVG.as_bytes())));
    sctx.insert("book_svg", format!("data:image/svg+xml;base64,{}", base64_encode(BOOK_SVG.as_bytes())));
    sctx.insert("loc_display_one", book_lformat(book, "Display one chapter"));
    sctx.insert("loc_display_all", book_lformat(book, "Display all chapters"));
    let script = render_template(book, "html.standalone.js", &sctx)?;
    ctx.insert("script", script);

    render_template(book, "html.standalone.template", &ctx)
}

/// Render the name of the inline TOC (rendering.inline_toc.name)
pub fn render_toc_name(book: &Book) -> String {
    let src = book.options.get_str("rendering.inline_toc.name").unwrap_or("{{loc_toc}}");
    let mut ctx = Context::new();
    ctx.insert("loc_toc", book_lformat(book, "Table of contents"));
    match Template::compile(src, &HTML_SYNTAX).and_then(|t| t.render(&ctx)) {
        Ok(s) => s,
        Err(_) => src.to_string(),
    }
}
