/// Render a single format
fn render_to(book: &book::Book, format: &str, output: Option<&str>) {
    let key = format!("output.{}", format);
    match output {
        Some("-") | None if output.is_some() || !book.options.is_set(&key) => {
            // to stdout
            match render_format_to_string(book, format) {
                Ok(Some(s)) => {
                    let stdout = std::io::stdout();
                    let mut lock = stdout.lock();
                    let _ = lock.write_all(s.as_bytes());
                    let _ = lock.flush();
                }
                Ok(None) => {}
                Err(e) => {
                    logger::print_error(&e.to_string());
                }
            }
        }
        Some(path) => {
            if let Err(e) = render_format_to_file(book, format, path, false) {
                logger::print_error(&e.to_string());
            }
        }
        None => {
            let path = book.options.get_relative_path(&key).unwrap_or("").to_string();
            let full = book.output_path(&path);
            if let Err(e) = render_format_to_file(book, format, &full.to_string_lossy(), true) {
                logger::print_error(&e.to_string());
            }
        }
    }
}

fn render_format_to_string(book: &book::Book, format: &str) -> error::Result<Option<String>> {
    match format {
        "html" => html_single::render(book).map(Some),
        "tex" => latex::render(book).map(Some),
        "html.dir" => Err(error::Error::render(
            error::Source::empty(),
            lang::lformat("can only render HTML directory to a path, not to a stream"),
        )),
        "pdf" => Err(error::Error::zipper(
            error::Source::empty(),
            lang::lformat2(
                "failed to run command '{command}'",
                &[("command", book.options.get_str("tex.command").unwrap_or("xelatex"))],
            ),
        )),
        "epub" => Err(error::Error::render(
            error::Source::empty(),
            lang::lformat("can only render EPUB to a path, not to a stream"),
        )),
        other => Err(error::Error::default(
            error::Source::empty(),
            lang::lformat2("unknown format {format}", &[("format", other)]),
        )),
    }
}

fn format_description(format: &str, path: &str) -> String {
    match format {
        "html" => format!("Succesfully generated HTML (standalone page): {}", path),
        "tex" => format!("Succesfully generated LaTeX: {}", path),
        "epub" => format!("Succesfully generated EPUB: {}", path),
        "pdf" => format!("Succesfully generated PDF: {}", path),
        "html.dir" => format!("Succesfully generated HTML directory: {}", path),
        _ => format!("Succesfully generated {}: {}", format, path),
    }
}

fn render_format_to_file(book: &book::Book, format: &str, path: &str, _from_options: bool) -> error::Result<()> {
    match format {
        "html" | "tex" => {
            let s = render_format_to_string(book, format)?.unwrap_or_default();
            std::fs::write(path, s).map_err(|e| {
                error::Error::render(
                    error::Source::empty(),
                    lang::lformat2("could not write to file '{file}': {error}", &[("file", path), ("error", &e.to_string())]),
                )
            })?;
            logger::info("book", &format_description(format, path));
            logger::print_success(&format!("{}: generated {}", format, path));
            Ok(())
        }
        "pdf" => Err(error::Error::zipper(
            error::Source::empty(),
            lang::lformat2(
                "failed to run command '{command}'",
                &[("command", book.options.get_str("tex.command").unwrap_or("xelatex"))],
            ),
        )),
        other => Err(error::Error::default(
            error::Source::empty(),
            lang::lformat2("unknown format {format}", &[("format", other)]),
        )),
    }
}

fn render_all(book: &book::Book) {
    let formats = book.formats_to_render();
    for (fmt, path) in formats {
        let full = book.output_path(&path);
        logger::debug("book", &format!("Attempting to generate {}...", fmt));
        if let Err(e) = render_format_to_file(book, &fmt, &full.to_string_lossy(), true) {
            logger::error(
                "book",
                &lang::lformat2("Error rendering {format}: {error}", &[("format", &fmt), ("error", &e.to_string())]),
            );
        }
    }
    if logger::mode() == logger::Mode::Collect {
        logger::print_success("Finished");
    }
}

fn create_book(args: &cli::Args, files: &[String]) {
    let mut content = String::new();
    content.push_str("\"author: Your name\"\n\"title: Your title\"\n\"lang: en\"\n\n\"## Output formats\"\n\n\"# Uncomment and fill to generate files\"\n\"# output.html: some_file.html\"\n\"# output.epub: some_file.epub\"\n\"# output.pdf: some_file.pdf\"\n\n\"# Or uncomment the following to generate PDF, HTML and EPUB files based on this file's name\"\n\"# output: [pdf, epub, html]\"\n\n\"# Uncomment and fill to set cover image (for EPUB)\"\n\"# cover: some_cover.png\"\n\n## List of chapters\n");
    for f in files {
        content.push_str(&format!("+ {}\n", f));
    }
    match &args.book {
        Some(path) => {
            if std::path::Path::new(path).exists() {
                logger::print_error(&lang::lformat2(
                    "{file} already exists, it won't be overwritten!",
                    &[("file", path)],
                ));
                return;
            }
            if let Err(e) = std::fs::write(path, &content) {
                logger::print_error(&e.to_string());
                return;
            }
            println!(
                "{}",
                lang::lformat2("Created {file}, now you'll have to complete it!", &[("file", path)])
            );
        }
        None => {
            print!("{}", content);
        }
    }
}

fn print_stats(book: &book::Book) {
    let mut total_chars = 0usize;
    let mut total_words = 0usize;
    let mut rows: Vec<(String, usize, usize)> = Vec::new();
    for ch in &book.chapters {
        let text = html::HtmlRenderer::view_as_text(&ch.content);
        let chars = text.chars().count();
        let words = text.split_whitespace().count();
        total_chars += chars;
        total_words += words;
        rows.push((ch.filename.clone(), chars, words));
    }
    let name_width = rows.iter().map(|r| r.0.chars().count()).max().unwrap_or(7).max(7);
    println!(
        "{:<w$} {:>10} {:>10} {:>11}",
        "Chapter",
        "Chars",
        "Words",
        "Chars/Word",
        w = name_width
    );
    println!("---------");
    for (name, chars, words) in &rows {
        let ratio = if *words > 0 { *chars as f64 / *words as f64 } else { 0.0 };
        println!("{:<w$} {:>10} {:>10} {:>11.2}", name, chars, words, ratio, w = name_width);
    }
    println!("---------");
    let ratio = if total_words > 0 { total_chars as f64 / total_words as f64 } else { 0.0 };
    println!("{:<w$} {:>10} {:>10} {:>11.2}", "TOTAL:", total_chars, total_words, ratio, w = name_width);
    println!();
}
