pub struct LatexRenderer<'a> {
    book: &'a Book,
    cleaner: Cleaner,
    current_chapter: i32,
    is_book: bool,
    hyperref: bool,
    links_as_footnotes: bool,
    escape_nb_spaces: bool,
    footnotes: Vec<(String, Vec<Token>)>,
    first_header_done: bool,
    chapter_index: usize,
    numbered: bool,
    hidden: bool,
    is_part: bool,
    table_head: bool,
    in_header: bool,
    image_counter: usize,
    pub images: Vec<(String, String)>,
    source: Source,
    pub error: Option<Error>,
    link_map: Vec<(String, String)>,
}

impl<'a> LatexRenderer<'a> {
    pub fn new(book: &'a Book) -> LatexRenderer<'a> {
        let class = book.options.get_str("tex.class").unwrap_or("book").to_string();
        LatexRenderer {
            book,
            cleaner: book.cleaner(),
            current_chapter: 0,
            is_book: class == "book",
            hyperref: book.options.get_bool("tex.hyperref").unwrap_or(true),
            links_as_footnotes: book.options.get_bool("tex.links_as_footnotes").unwrap_or(true),
            escape_nb_spaces: book.options.get_bool("tex.escape_nb_spaces").unwrap_or(true),
            footnotes: Vec::new(),
            first_header_done: false,
            chapter_index: 0,
            numbered: true,
            hidden: false,
            is_part: false,
            table_head: false,
            in_header: false,
            image_counter: 0,
            images: Vec::new(),
            source: book.source.clone(),
            error: None,
            link_map: book
                .chapters
                .iter()
                .enumerate()
                .filter(|(_, c)| !c.filename.is_empty())
                .map(|(i, c)| (c.filename.clone(), format!("chapter-{}", i)))
                .collect(),
        }
    }

    fn text(&self, s: &str) -> String {
        let cleaned = self.cleaner.clean(s, true);
        let mut escaped = escape_tex(&cleaned);
        if self.escape_nb_spaces {
            escaped = escaped.replace('\u{a0}', "~").replace('\u{202f}', "\\,");
        }
        escaped
    }

    pub fn render_vec(&mut self, tokens: &[Token]) -> String {
        let mut out = String::new();
        for t in tokens {
            out.push_str(&self.render_token(t));
        }
        out
    }

    fn header_cmd(&self, level: i32) -> &'static str {
        if self.is_book {
            match level {
                1 => "chapter",
                2 => "section",
                3 => "subsection",
                4 => "subsubsection",
                _ => "paragraoh",
            }
        } else {
            match level {
                1 | 2 => "section",
                3 => "subsection",
                4 => "subsubsection",
                _ => "paragraoh",
            }
        }
    }

    fn render_header(&mut self, level: i32, inner: &[Token]) -> String {
        self.in_header = true;
        let content = self.render_vec(inner);
        self.in_header = false;
        let mut out = String::new();
        if level == 1 && self.is_part {
            if self.book.options.get_bool("rendering.part.reset_counter").unwrap_or(true) {
                out.push_str("\\setcounter{chapter}{0}");
            }
            if self.numbered {
                out.push_str(&format!("\\part{{{}}}\n", content));
            } else {
                out.push_str(&format!("\\part*{{{}}}\n", content));
            }
            if !self.first_header_done {
                out.push_str(&format!("\\label{{chapter-{}}}\n", self.chapter_index));
                self.first_header_done = true;
            }
            return out;
        }
        let cmd = self.header_cmd(level);
        if self.hidden {
            if level == 1 {
                out.push_str(&format!("\\{}*{{}}", cmd));
                if !self.first_header_done {
                    out.push_str(&format!("\\label{{chapter-{}}}\n", self.chapter_index));
                    self.first_header_done = true;
                } else {
                    out.push('\n');
                }
            } else {
                out.push_str(&format!("\\{}*{{{}}}\n", cmd, content));
            }
            return out;
        }
        if self.numbered {
            if level == 1 {
                if let Number::Specified(n) = self.book.chapters[self.chapter_index].number {
                    if !self.first_header_done {
                        out.push_str(&format!("\\setcounter{{chapter}}{{{}}}\n", n - 1));
                    }
                }
            }
            out.push_str(&format!("\\{}{{{}}}\n", cmd, content));
        } else {
            out.push_str(&format!("\\{}*{{{}}}\n", cmd, content));
            out.push_str(&format!("\\addcontentsline{{toc}}{{{}}}{{{}}}\n", cmd, content));
        }
        if level == 1 && !self.first_header_done {
            out.push_str(&format!("\\label{{chapter-{}}}\n", self.chapter_index));
            self.first_header_done = true;
        }
        out
    }

    fn resolve_link(&self, url: &str) -> Option<String> {
        if url.contains("://") {
            return None;
        }
        if let Some((_, t)) = self.link_map.iter().find(|(f, _)| f == url) {
            return Some(t.clone());
        }
        let alt = std::path::Path::new(url).with_extension("md").to_string_lossy().to_string();
        if let Some((_, t)) = self.link_map.iter().find(|(f, _)| *f == alt) {
            return Some(t.clone());
        }
        crate::logger::warn(
            "resource_handler",
            &crate::lang::lformat2(
                "Resources: could not find an in-book match for link {url} or {alt}",
                &[("url", url), ("alt", &alt)],
            ),
        );
        None
    }

    fn image_path(&mut self, url: &str) -> Option<String> {
        if !is_local(url) {
            return Some(url.to_string());
        }
        let base = self
            .book
            .options
            .get_relative_path("resources.base_path")
            .ok()
            .filter(|s| !s.is_empty())
            .map(|s| s.to_string())
            .or_else(|| self.book.options.get_relative_path("resources.base_path.images").ok().map(|s| s.to_string()))
            .unwrap_or_else(|| ".".to_string());
        let rel = format!("{}/{}", base.trim_end_matches('/'), url);
        let full = self.book.root.join(&rel);
        if !full.exists() {
            self.error = Some(Error::file_not_found(self.source.clone(), crate::lang::lformat("image"), rel));
            return None;
        }
        let ext = std::path::Path::new(url)
            .extension()
            .map(|e| format!(".{}", e.to_string_lossy()))
            .unwrap_or_default();
        let dest = format!("images/image_{}{}", self.image_counter, ext);
        self.image_counter += 1;
        self.images.push((full.to_string_lossy().to_string(), dest.clone()));
        Some(dest)
    }

    pub fn render_token(&mut self, token: &Token) -> String {
        match token {
            Token::Str(s) => self.text(s),
            Token::Paragraph(inner) => format!("{}\n\n", self.render_vec(inner)),
            Token::Header(level, inner) => self.render_header(*level, inner),
            Token::Emphasis(inner) => format!("\\emph{{{}}}", self.render_vec(inner)),
            Token::Strong(inner) => format!("\\mdstrong{{{}}}", self.render_vec(inner)),
            Token::Strikethrough(inner) => format!("\\sout{{{}}}", self.render_vec(inner)),
            Token::Superscript(inner) => format!("\\textsuperscript{{{}}}", self.render_vec(inner)),
            Token::Subscript(inner) => format!("\\textsubscript{{{}}}", self.render_vec(inner)),
            Token::Code(s) => format!("\\mdcode{{{}}}", escape_tex(s)),
            Token::BlockQuote(inner) => {
                format!("\\begin{{mdblockquote}}\n{}\n\\end{{mdblockquote}}\n", self.render_vec(inner))
            }
            Token::CodeBlock(lang, code) => {
                let content = crate::syntax::highlight_tex(lang, code);
                format!("\\begin{{mdcodeblock}}\n{}\\end{{mdcodeblock}}", content)
            }
            Token::Rule => "\\mdrule\n".to_string(),
            Token::SoftBreak => " ".to_string(),
            Token::HardBreak => "\\mdhardbreak\n".to_string(),
            Token::List(items) => format!("\\begin{{itemize}}\n{}\\end{{itemize}}", self.render_vec(items)),
            Token::OrderedList(start, items) => {
                let counter = if *start == 1 {
                    String::new()
                } else {
                    format!("\\setcounter{{enumi}}{{{}}}\n", start - 1)
                };
                format!("\\begin{{enumerate}}\n{}{}\n\\end{{enumerate}}\n", counter, self.render_vec(items))
            }
            Token::Item(inner) => format!("\\item {}\n", self.render_vec(inner)),
            Token::TaskItem(checked, inner) => {
                let mark = if *checked { "$\\boxtimes$" } else { "$\\square$" };
                format!("[{}] {}", mark, self.render_vec(inner))
            }
            Token::Table(cols, rows) => {
                let spec: String = std::iter::repeat("X|").take(*cols as usize).collect();
                let inner = self.render_vec(rows);
                format!("\\begin{{mdtable}}{{|{}}}\n\\hline\n{}\n\\hline\n\\end{{mdtable}}\n\n", spec, inner)
            }
            Token::TableHead(cells) => {
                self.table_head = true;
                let s = self.render_row(cells);
                self.table_head = false;
                format!("{}\\hline\n", s)
            }
            Token::TableRow(cells) => self.render_row(cells),
            Token::TableCell(inner) => self.render_vec(inner),
            Token::Footnote(label, content) => {
                if !self.footnotes.iter().any(|(l, _)| l == label) {
                    self.footnotes.push((label.clone(), content.to_vec()));
                }
                format!("\\footnotemark[{}]", label)
            }
            Token::Link(url, _title, inner) => {
                let content = self.render_vec(inner);
                if self.hyperref {
                    if let Some(target) = self.resolve_link(url) {
                        return format!("\\hyperref[{}]{{{}}}", target, content);
                    }
                }
                let u = escape_url(url);
                if self.links_as_footnotes && !self.in_header {
                    format!("\\href{{{}}}{{{}}}\\protect\\footnote{{\\url{{{}}}}}", u, content, u)
                } else {
                    format!("\\href{{{}}}{{{}}}", u, content)
                }
            }
            Token::Image(url, _, _) => match self.image_path(url) {
                Some(p) => format!("\\mdimage{{{}}}", p),
                None => String::new(),
            },
            Token::StandaloneImage(url, _, _) => match self.image_path(url) {
                Some(p) => format!("\\mdstandaloneimage{{{}}}\n", p),
                None => String::new(),
            },
            Token::DescriptionList(inner) => format!(
                "\\begin{{description}}[style=nextline, labelwidth=0pt]\n{}\\end{{description}}",
                self.render_vec(inner)
            ),
            Token::DescriptionItem(inner) => self.render_vec(inner),
            Token::DescriptionTerm(inner) => format!("\\item[{}]\n", self.render_vec(inner)),
            Token::DescriptionDetails(inner) => format!("{}\n", self.render_vec(inner)),
            Token::Annotation(_, inner) => self.render_vec(inner),
        }
    }

    fn render_row(&mut self, cells: &[Token]) -> String {
        let rendered: Vec<String> = cells.iter().map(|c| self.render_token(c)).collect();
        format!("{}\\\\ \n", rendered.join(" & "))
    }

    fn render_footnotes(&mut self) -> String {
        let notes = std::mem::take(&mut self.footnotes);
        let mut out = String::new();
        for (label, content) in notes {
            let rendered = self.render_vec(&content);
            out.push_str(&format!("\\footnotetext[{}]{{{}}}", label, rendered));
        }
        out
    }

    pub fn start_chapter(&mut self, i: usize, chapter: &Chapter) {
        self.chapter_index = i;
        self.first_header_done = false;
        self.source = Source::new(&chapter.filename);
        self.numbered = chapter.number.is_numbered();
        self.hidden = chapter.number.is_hidden();
        self.is_part = chapter.number.is_part();
        if let Number::Specified(n) = chapter.number {
            self.current_chapter = n;
        }
    }
}

/// Render metadata as LaTeX
fn metadata(r: &mut LatexRenderer, key: &str) -> String {
    match r.book.get_metadata_tokens(key) {
        Some(tokens) => r.render_vec(&tokens),
        None => String::new(),
    }
}

pub fn render(book: &Book) -> Result<String> {
    let mut r = LatexRenderer::new(book);
    let mut content = String::new();
    for (i, chapter) in book.chapters.iter().enumerate() {
        r.start_chapter(i, chapter);
        let mut tokens = chapter.content.clone();
        mark_standalone_images(&mut tokens);
        content.push_str(&r.render_vec(&tokens));
        if let Some(e) = r.error.take() {
            return Err(e);
        }
    }
    content.push_str(&r.render_footnotes());

    let tex_command = book.options.get_str("tex.command").unwrap_or("xelatex").to_string();
    let class = book.options.get_str("tex.class").unwrap_or("book").to_string();
    let is_book = class == "book";
    let lang = book.options.get_str("lang").unwrap_or("en").to_string();

    let mut ctx = Context::new();
    ctx.insert("content", content);
    ctx.insert("class", class.clone());
    ctx.insert_bool("book", is_book);
    ctx.insert_bool("xelatex", tex_command == "xelatex");
    ctx.insert("tex_lang", babel_lang(&lang));
    ctx.insert_bool("use_strikethrough", book.features.strikethrough);
    ctx.insert_bool("use_taskitem", book.features.taskitem);
    ctx.insert_bool("use_codeblocks", book.features.codeblocks);
    ctx.insert_bool("use_images", book.features.images);
    ctx.insert_bool("use_tables", book.features.tables);
    ctx.insert_bool("initials", book.options.get_bool("rendering.initials").unwrap_or(false));
    ctx.insert_bool("stdpage", book.options.get_bool("tex.stdpage").unwrap_or(false));
    ctx.insert("papersize", book.options.get_str("tex.paper.size").unwrap_or("a5paper"));
    ctx.insert("margin_top", book.options.get_str("tex.margin.top").unwrap_or("2cm"));
    ctx.insert("margin_bottom", book.options.get_str("tex.margin.bottom").unwrap_or("1.5cm"));
    let (def_left, def_right) = if is_book { ("2.5cm", "1.5cm") } else { ("2cm", "2cm") };
    ctx.insert("margin_left", book.options.get_str("tex.margin.left").unwrap_or(def_left));
    ctx.insert("margin_right", book.options.get_str("tex.margin.right").unwrap_or(def_right));
    match book.options.get_i32("tex.font.size") {
        Ok(size) => {
            ctx.insert_bool("has_tex_size", true);
            ctx.insert("tex_size", size.to_string());
        }
        Err(_) => {
            ctx.insert_bool("has_tex_size", false);
            ctx.insert("tex_size", "");
        }
    }
    ctx.insert_bool("tex_title", book.options.get_bool("tex.title").unwrap_or(true));
    ctx.insert_bool("inline_toc", book.options.get_bool("rendering.inline_toc").unwrap_or(false));
    let author = metadata(&mut r, "author");
    let title = metadata(&mut r, "title");
    ctx.insert_bool("has_author", !author.is_empty());
    ctx.insert("author", author);
    ctx.insert("title", title);
    ctx.insert("description", metadata(&mut r, "description"));
    ctx.insert("subtitle", metadata(&mut r, "subtitle"));
    ctx.insert_bool("has_autograph", book.options.is_set("autograph"));
    ctx.insert("autograph", metadata(&mut r, "autograph"));
    ctx.insert_bool("has_date", book.options.is_set("date"));
    ctx.insert("date", metadata(&mut r, "date"));
    ctx.insert_bool("has_version", book.options.is_set("version"));
    ctx.insert("version", metadata(&mut r, "version"));
    ctx.insert_bool("has_license", book.options.is_set("license"));
    ctx.insert("license", metadata(&mut r, "license"));
    ctx.insert("additional_code", book.options.get_str("tex.template.add").unwrap_or(""));
    // chapter / part names
    match book.options.get_str("rendering.chapter") {
        Ok(name) => ctx.insert("chapter_name", name),
        Err(_) => ctx.insert_bool("chapter_name", false),
    }
    match book.options.get_str("rendering.part") {
        Ok(name) => ctx.insert("part_name", name),
        Err(_) => ctx.insert_bool("part_name", false),
    }
    // cover
    let use_cover = book.options.get_bool("tex.cover").unwrap_or(false) && book.options.is_set("cover");
    ctx.insert_bool("use_cover", use_cover);
    if use_cover {
        let cover = book.options.get_relative_path("cover").unwrap_or("").to_string();
        match r.image_path(&cover) {
            Some(p) => ctx.insert("cover_path", p),
            None => {
                if let Some(e) = r.error.take() {
                    return Err(e);
                }
                ctx.insert("cover_path", "");
            }
        }
    } else {
        ctx.insert("cover_path", "");
    }

    let src = get_template(book, "tex.template")?;
    let tpl = Template::compile(&src, &TEX_SYNTAX).map_err(|e| Error::template(book.source.clone(), e.to_string()))?;
    tpl.render(&ctx).map_err(|e| Error::template(book.source.clone(), e.to_string()))
}
