/// Escape a string for LaTeX text
pub fn escape_tex(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    let mut prev_dash = false;
    for c in s.chars() {
        let mut dash = false;
        match c {
            '&' => out.push_str("\\&"),
            '%' => out.push_str("\\%"),
            '$' => out.push_str("\\$"),
            '#' => out.push_str("\\#"),
            '_' => out.push_str("\\_"),
            '{' => out.push_str("\\{"),
            '}' => out.push_str("\\}"),
            '~' => out.push_str("\\textasciitilde{}"),
            '^' => out.push_str("\\textasciicircum{}"),
            '\\' => out.push_str("\\textbackslash{}"),
            '<' => out.push_str("\\textless{}"),
            '>' => out.push_str("\\textgreater{}"),
            '!' => out.push_str("!{}"),
            '-' => {
                if prev_dash {
                    out.push_str("{}-");
                } else {
                    out.push('-');
                }
                dash = true;
            }
            _ => out.push(c),
        }
        prev_dash = dash;
    }
    out
}

/// Escape a string for LaTeX code (inside \texttt)
pub fn escape_tex_code(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            ' ' => out.push_str("\\hphantom{ }\\allowbreak{}"),
            '&' => out.push_str("\\&"),
            '%' => out.push_str("\\%"),
            '$' => out.push_str("\\$"),
            '#' => out.push_str("\\#"),
            '_' => out.push_str("\\_\\allowbreak{}"),
            '{' => out.push_str("\\{"),
            '}' => out.push_str("\\}"),
            '~' => out.push_str("\\textasciitilde{}"),
            '^' => out.push_str("\\textasciicircum{}"),
            '\\' => out.push_str("\\textbackslash{}"),
            '<' => out.push_str("\\textless{}"),
            '>' => out.push_str("\\textgreater{}"),
            '!' => out.push_str("!{}"),
            '(' => out.push_str("(\\allowbreak{}"),
            ')' => out.push_str(")\\allowbreak{}"),
            ':' => out.push_str(":\\allowbreak{}"),
            '.' => out.push_str(".\\allowbreak{}"),
            '-' => out.push_str("-\\allowbreak{}"),
            '/' => out.push_str("/\\allowbreak{}"),
            '[' => out.push_str("{[}"),
            ']' => out.push_str("{]}"),
            _ => out.push(c),
        }
    }
    out
}

/// Escape a URL for \href / \url
fn escape_url(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '&' => out.push_str("\\&"),
            '%' => out.push_str("\\%"),
            '#' => out.push_str("\\#"),
            '_' => out.push_str("\\_"),
            '{' => out.push_str("\\{"),
            '}' => out.push_str("\\}"),
            '$' => out.push_str("\\$"),
            _ => out.push(c),
        }
    }
    out
}

