//! Minimal ZIP file writer (stored entries), sufficient for EPUB files.

use std::io::Write;

pub struct ZipWriter {
    data: Vec<u8>,
    entries: Vec<(String, u32, u32, u32, u16, u16)>, // name, crc, size, offset, time, date
}

fn crc32(data: &[u8]) -> u32 {
    let mut table = [0u32; 256];
    for i in 0..256u32 {
        let mut c = i;
        for _ in 0..8 {
            c = if c & 1 != 0 { 0xEDB88320 ^ (c >> 1) } else { c >> 1 };
        }
        table[i as usize] = c;
    }
    let mut crc = 0xFFFFFFFFu32;
    for &b in data {
        crc = table[((crc ^ b as u32) & 0xFF) as usize] ^ (crc >> 8);
    }
    crc ^ 0xFFFFFFFF
}

fn dos_time() -> (u16, u16) {
    let secs = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0);
    let (y, mo, d, h, mi, s) = crate::misc::civil_from_unix(secs as i64);
    let time = ((h as u16) << 11) | ((mi as u16) << 5) | ((s as u16) / 2);
    let year = if y < 1980 { 1980 } else { y };
    let date = (((year - 1980) as u16) << 9) | ((mo as u16) << 5) | (d as u16);
    (time, date)
}

impl ZipWriter {
    pub fn new() -> ZipWriter {
        ZipWriter {
            data: Vec::new(),
            entries: Vec::new(),
        }
    }

    pub fn add_file(&mut self, name: &str, content: &[u8]) {
        let (time, date) = dos_time();
        let crc = crc32(content);
        let offset = self.data.len() as u32;
        let name_bytes = name.as_bytes();
        // local file header
        self.data.extend_from_slice(&0x04034b50u32.to_le_bytes());
        self.data.extend_from_slice(&20u16.to_le_bytes()); // version needed
        self.data.extend_from_slice(&0x0800u16.to_le_bytes()); // flags: utf8
        self.data.extend_from_slice(&0u16.to_le_bytes()); // method: stored
        self.data.extend_from_slice(&time.to_le_bytes());
        self.data.extend_from_slice(&date.to_le_bytes());
        self.data.extend_from_slice(&crc.to_le_bytes());
        self.data.extend_from_slice(&(content.len() as u32).to_le_bytes());
        self.data.extend_from_slice(&(content.len() as u32).to_le_bytes());
        self.data.extend_from_slice(&(name_bytes.len() as u16).to_le_bytes());
        self.data.extend_from_slice(&0u16.to_le_bytes()); // extra len
        self.data.extend_from_slice(name_bytes);
        self.data.extend_from_slice(content);
        self.entries.push((name.to_string(), crc, content.len() as u32, offset, time, date));
    }

    pub fn finish(mut self) -> Vec<u8> {
        let cd_offset = self.data.len() as u32;
        for (name, crc, size, offset, time, date) in &self.entries {
            let name_bytes = name.as_bytes();
            self.data.extend_from_slice(&0x02014b50u32.to_le_bytes());
            self.data.extend_from_slice(&(20u16 | (3 << 8)).to_le_bytes()); // version made by (unix)
            self.data.extend_from_slice(&20u16.to_le_bytes());
            self.data.extend_from_slice(&0x0800u16.to_le_bytes());
            self.data.extend_from_slice(&0u16.to_le_bytes());
            self.data.extend_from_slice(&time.to_le_bytes());
            self.data.extend_from_slice(&date.to_le_bytes());
            self.data.extend_from_slice(&crc.to_le_bytes());
            self.data.extend_from_slice(&size.to_le_bytes());
            self.data.extend_from_slice(&size.to_le_bytes());
            self.data.extend_from_slice(&(name_bytes.len() as u16).to_le_bytes());
            self.data.extend_from_slice(&0u16.to_le_bytes()); // extra
            self.data.extend_from_slice(&0u16.to_le_bytes()); // comment
            self.data.extend_from_slice(&0u16.to_le_bytes()); // disk
            self.data.extend_from_slice(&0u16.to_le_bytes()); // internal attrs
            self.data.extend_from_slice(&0x81A40000u32.to_le_bytes()); // external attrs (0644)
            self.data.extend_from_slice(&offset.to_le_bytes());
            self.data.extend_from_slice(name_bytes);
        }
        let cd_size = self.data.len() as u32 - cd_offset;
        self.data.extend_from_slice(&0x06054b50u32.to_le_bytes());
        self.data.extend_from_slice(&0u16.to_le_bytes());
        self.data.extend_from_slice(&0u16.to_le_bytes());
        self.data.extend_from_slice(&(self.entries.len() as u16).to_le_bytes());
        self.data.extend_from_slice(&(self.entries.len() as u16).to_le_bytes());
        self.data.extend_from_slice(&cd_size.to_le_bytes());
        self.data.extend_from_slice(&cd_offset.to_le_bytes());
        self.data.extend_from_slice(&0u16.to_le_bytes());
        self.data
    }

    pub fn write_to(self, path: &str) -> std::io::Result<()> {
        let data = self.finish();
        let mut f = std::fs::File::create(path)?;
        f.write_all(&data)
    }
}
