        opf.push_str(&format!("    <itemref idref=\"id_{}\"/>\n", s.href));
    }
    opf.push_str("  </spine>\n  <guide>\n");
    opf.push_str(&format!("    <reference type=\"toc\" title=\"{}\" href=\"nav.xhtml\"/>\n", loc_toc));
    let mut text_done = false;
    for s in &spine {
        if s.guide_type == "text" {
            if text_done {
                continue;
            }
            text_done = true;
        }
        opf.push_str(&format!(
            "    <reference type=\"{}\" title=\"{}\" href=\"{}\"/>\n",
            s.guide_type, s.title, s.href
        ));
    }
    opf.push_str("  </guide>\n</package>\n");

    // toc.ncx
    let mut ncx = String::new();
    ncx.push_str("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<ncx version=\"2005-1\" xmlns=\"http://www.daisy.org/z3986/2005/ncx/\">\n  <head>\n");
    ncx.push_str(&format!("    <meta name=\"dtb:depth\" content=\"{}\" />\n", full_toc.depth().max(1)));
    ncx.push_str("    <meta name=\"dtb:totalPageCount\" content=\"0\" />\n    <meta name=\"dtb:maxPageNumber\" content=\"0\" />\n  </head>\n");
    ncx.push_str(&format!("  <docTitle>\n    <text>{}</text>\n  </docTitle>\n  <navMap>\n", loc_toc));
    ncx.push_str(&full_toc.render_ncx());
    ncx.push_str("  </navMap>\n</ncx>\n");

    for (name, data) in &files {
        zip.add_file(&format!("OEBPS/{}", name), data);
    }
    zip.add_file("OEBPS/content.opf", opf.as_bytes());
    zip.add_file("OEBPS/toc.ncx", ncx.as_bytes());
    zip.add_file("OEBPS/nav.xhtml", nav.as_bytes());

    crate::logger::warn("epub", &crate::lang::lformat("Could not run zip command, falling back to zip library"));
    zip.write_to(output).map_err(|e| {
        Error::render(
            Source::empty(),
            crate::lang::lformat2("could not write to file '{file}': {error}", &[("file", output), ("error", &e.to_string())]),
        )
    })
}

/// Chapters' first toc entries should link to the file without anchor
fn fix_toc_urls(elements: &mut [crate::toc::TocElement]) {
    for e in elements.iter_mut() {
        if e.level <= 1 {
            if let Some(pos) = e.url.find('#') {
                let anchor = &e.url[pos + 1..];
                if anchor.starts_with("link-") {
                    // only the first header of a chapter file gets the bare file url;
                    // this is marked by the renderer with `first_in_file`
                }
            }
        }
        fix_toc_urls(&mut e.children);
    }
}

/// Clone a toc element using raw titles
fn raw_toc(e: &crate::toc::TocElement) -> crate::toc::TocElement {
    let mut n = crate::toc::TocElement::new(e.level, &e.url, &e.raw_title);
    n.raw_title = e.raw_title.clone();
    n.children = e.children.iter().map(raw_toc).collect();
    n
}
