struct Item {
    href: String,
    mime: String,
    id: String,
    properties: String,
}

struct SpineEntry {
    href: String,
    title: String,
    guide_type: String,
}

pub fn render(book: &Book, output: &str) -> Result<()> {
    let version = book.options.get_i32("epub.version").unwrap_or(2);
    let epub3 = version == 3;
    let lang = book.options.get_str("lang").unwrap_or("en").to_string();
    let inline_toc = book.options.get_bool("rendering.inline_toc").unwrap_or(false);
    let toc_extras = book.options.get_bool("epub.toc.extras").unwrap_or(true);

    let mut r = HtmlRenderer::new(book, ImageMode::Files)?;
    r.epub = true;
    r.epub3 = epub3;
    r.escape_nb_spaces = book.options.get_bool("epub.escape_nb_spaces").unwrap_or(true);
    let targets: Vec<(String, String)> = book
        .chapters
        .iter()
        .enumerate()
        .filter(|(_, c)| !c.filename.is_empty())
        .map(|(i, c)| (c.filename.clone(), format!("chapter_{:03}.xhtml", i)))
        .collect();
    r.set_link_targets(targets);

    let mut zip = ZipWriter::new();
    zip.add_file("mimetype", b"application/epub+zip");
    zip.add_file("META-INF/container.xml", CONTAINER_XML.as_bytes());
    zip.add_file("META-INF/com.apple.ibooks.display-options.xml", IBOOKS_XML.as_bytes());

    let mut items: Vec<Item> = Vec::new();
    let mut spine: Vec<SpineEntry> = Vec::new();
    let mut files: Vec<(String, Vec<u8>)> = Vec::new();

    // metadata
    let (title, title_raw) = metadata(&mut r, "title");
    let (author, _author_raw) = metadata(&mut r, "author");
    let (subtitle, _) = metadata(&mut r, "subtitle");
    let (autograph, _) = metadata(&mut r, "autograph");

    let loc_toc = book_lformat(book, "Table of contents");
    let loc_cover = book_lformat(book, "Cover");
    let loc_title = book_lformat(book, "Title");

    // cover
    let mut cover_image: Option<String> = None;
    if book.options.is_set("cover") {
        let cover = book.options.get_relative_path("cover").unwrap_or("").to_string();
        match r.image_src_pub(&cover) {
            Some(dest) => {
                cover_image = Some(dest.clone());
                let mut ctx = Context::new();
                ctx.insert("lang", lang.clone());
                ctx.insert("title_raw", title_raw.clone());
                ctx.insert("cover", dest);
                ctx.insert("loc_cover", loc_cover.clone());
                let tpl = Template::compile(if epub3 { COVER_V3 } else { COVER_V2 }, &HTML_SYNTAX)
                    .map_err(|e| Error::template(book.source.clone(), e.to_string()))?;
                let s = tpl.render(&ctx).map_err(|e| Error::template(book.source.clone(), e.to_string()))?;
                files.push(("cover.xhtml".to_string(), s.into_bytes()));
                items.push(Item {
                    href: "cover.xhtml".into(),
                    mime: "application/xhtml+xml".into(),
                    id: "id_cover.xhtml".into(),
                    properties: String::new(),
                });
                spine.push(SpineEntry {
                    href: "cover.xhtml".into(),
                    title: loc_cover.clone(),
                    guide_type: "cover".into(),
                });
            }
            None => {
                if let Some(e) = r.error.take() {
                    return Err(e);
                }
            }
        }
    }

    // title page
    {
        let mut ctx = Context::new();
        ctx.insert("lang", lang.clone());
        ctx.insert("title", title.clone());
        ctx.insert("title_raw", title_raw.clone());
        ctx.insert("author", author.clone());
        ctx.insert_bool("has_subtitle", book.options.is_set("subtitle"));
        ctx.insert("subtitle", subtitle.clone());
        ctx.insert_bool("has_autograph", book.options.is_set("autograph"));
        ctx.insert("autograph", autograph.clone());
        let src = if epub3 {
            TITLEPAGE_V3.to_string()
        } else {
            get_template(book, "epub.titlepage.xhtml")?
        };
        let tpl = Template::compile(&src, &HTML_SYNTAX).map_err(|e| Error::template(book.source.clone(), e.to_string()))?;
        let s = tpl.render(&ctx).map_err(|e| Error::template(book.source.clone(), e.to_string()))?;
        files.push(("title_page.xhtml".to_string(), s.into_bytes()));
        items.push(Item {
            href: "title_page.xhtml".into(),
            mime: "application/xhtml+xml".into(),
            id: "id_title_page.xhtml".into(),
            properties: String::new(),
        });
        spine.push(SpineEntry {
            href: "title_page.xhtml".into(),
            title: loc_title.clone(),
            guide_type: "title-page".into(),
        });
    }

    // toc page placeholder (rendered after chapters, but placed here)
    let toc_index = if inline_toc {
        items.push(Item {
            href: "toc.xhtml".into(),
            mime: "application/xhtml+xml".into(),
            id: "id_toc.xhtml".into(),
            properties: String::new(),
        });
        spine.push(SpineEntry {
            href: "toc.xhtml".into(),
            title: loc_toc.clone(),
            guide_type: "toc".into(),
        });
        Some(files.len())
    } else {
        None
    };
    if inline_toc {
        files.push(("toc.xhtml".to_string(), Vec::new()));
    }

    // chapters
    let chapter_src = if epub3 {
        CHAPTER_V3.to_string()
    } else {
        get_template(book, "epub.chapter.xhtml")?
    };
    let chapter_tpl =
        Template::compile(&chapter_src, &HTML_SYNTAX).map_err(|e| Error::template(book.source.clone(), e.to_string()))?;
    let mut chapter_titles: Vec<String> = Vec::new();
    for (i, chapter) in book.chapters.iter().enumerate() {
        r.start_chapter(i, chapter);
        let filename = format!("chapter_{:03}.xhtml", i);
        r.link_prefix = filename.clone();
        let mut tokens = chapter.content.clone();
        mark_standalone_images(&mut tokens);
        let toc_before = r.toc.len();
        let _ = toc_before;
        let body = r.render_vec(&tokens);
        let notes = r.render_footnotes();
        if let Some(e) = r.error.take() {
            return Err(e);
        }
        // chapter title: the toc title of the first header (raw)
        let chapter_title = r.last_chapter_title_raw.clone().unwrap_or_default();
        r.last_chapter_title_raw = None;
        chapter_titles.push(chapter_title.clone());
        let mut ctx = Context::new();
        ctx.insert("lang", lang.clone());
        ctx.insert("chapter_title_raw", chapter_title.clone());
        ctx.insert("content", format!("{}{}", body, notes));
        let s = chapter_tpl.render(&ctx).map_err(|e| Error::template(book.source.clone(), e.to_string()))?;
        files.push((filename.clone(), s.into_bytes()));
        items.push(Item {
            href: filename.clone(),
            mime: "application/xhtml+xml".into(),
            id: format!("id_{}", filename),
            properties: String::new(),
        });
        spine.push(SpineEntry {
            href: filename.clone(),
            title: chapter_title,
            guide_type: "text".into(),
        });
    }

    // Fix toc element urls: the first element of each chapter points to the file without anchor
    let mut toc = r.toc.clone();
    fix_toc_urls(&mut toc.elements);

    // stylesheet
    let css = crate::html_single::render_css(book, "epub.css")?;
    files.push(("stylesheet.css".to_string(), css.into_bytes()));
    items.push(Item {
        href: "stylesheet.css".into(),
        mime: "text/css".into(),
        id: "id_stylesheet.css".into(),
        properties: String::new(),
    });

    // images
    for (src, dest) in &r.images {
        let data = std::fs::read(src).unwrap_or_default();
        files.push((dest.clone(), data));
        let is_cover = cover_image.as_deref() == Some(dest.as_str());
        items.push(Item {
            href: dest.clone(),
            mime: mime_type(dest).to_string(),
            id: if is_cover {
                "cover-image".to_string()
            } else {
                format!("id_{}", dest.replace('/', "_"))
            },
            properties: if is_cover { "cover-image".to_string() } else { String::new() },
        });
    }

    // additional resources
    if let Ok(list) = book.options.get_str_vec("resources.files") {
        let out_path = book.options.get_relative_path("resources.out_path").unwrap_or("data").to_string();
        let base = book
            .options
            .get_relative_path("resources.base_path")
            .ok()
            .filter(|s| !s.is_empty())
            .map(|s| s.to_string())
            .or_else(|| book.options.get_relative_path("resources.base_path.files").ok().map(|s| s.to_string()))
            .unwrap_or_else(|| ".".to_string());
        for f in list {
            let rel = format!("{}/{}", base.trim_end_matches('/'), f);
            let full = book.root.join(&rel);
            let data = std::fs::read(&full).map_err(|_| {
                Error::file_not_found(book.source.clone(), "additional resource from resources.files".to_string(), rel.clone())
            })?;
            let dest = format!("{}/{}", out_path.trim_end_matches('/'), f);
            files.push((dest.clone(), data));
            let mime = if f.ends_with(".md") { "text/markdown".to_string() } else { mime_type(f).to_string() };
            items.push(Item {
                href: dest.clone(),
                mime,
                id: format!("id_{}", dest.replace('/', "_")),
                properties: String::new(),
            });
        }
    }

    // TOC pages (nav.xhtml, toc.xhtml)
    let mut full_toc = crate::toc::Toc::new();
    if toc_extras {
        if cover_image.is_some() {
            full_toc.add(crate::toc::TocElement::new(1, "cover.xhtml", &loc_cover));
        }
        full_toc.add(crate::toc::TocElement::new(1, "title_page.xhtml", &loc_title));
    }
    if inline_toc {
        full_toc.add(crate::toc::TocElement::new(1, "toc.xhtml", &loc_toc));
    }
    for e in &toc.elements {
        full_toc.elements.push(raw_toc(e));
    }
    let nav_src = if epub3 { NAV_V3 } else { NAV_V2 };
    let nav_tpl = Template::compile(nav_src, &HTML_SYNTAX).map_err(|e| Error::template(book.source.clone(), e.to_string()))?;
    let landmarks = {
        let mut out = Vec::new();
        for s in &spine {
            let typ = match s.guide_type.as_str() {
                "cover" => "cover",
                "title-page" => "titlepage",
                "toc" => "toc",
                _ => "bodymatter",
            };
            if typ == "bodymatter" && out.iter().any(|l: &String| l.contains("bodymatter")) {
                continue;
            }
            out.push(format!("      <li><a epub:type=\"{}\" href=\"{}\">{}</a></li>", typ, s.href, s.title));
        }
        out.join("\n")
    };
    let mut ctx = Context::new();
    ctx.insert("toc_name", loc_toc.clone());
    ctx.insert("toc", full_toc.render(true));
    ctx.insert("landmarks", landmarks.clone());
    let nav = nav_tpl.render(&ctx).map_err(|e| Error::template(book.source.clone(), e.to_string()))?;
    if let Some(idx) = toc_index {
        let mut ctx2 = Context::new();
        ctx2.insert("toc_name", loc_toc.clone());
        ctx2.insert("toc", full_toc.render(false));
        ctx2.insert("landmarks", landmarks);
        let toc_page = nav_tpl.render(&ctx2).map_err(|e| Error::template(book.source.clone(), e.to_string()))?;
        files[idx].1 = toc_page.into_bytes();
    }

    // content.opf
    let uuid = crate::misc::uuid_v4();
    let mut opf = String::new();
    opf.push_str("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n");
    opf.push_str(&format!(
        "<package version=\"{}\" xmlns=\"http://www.idpf.org/2007/opf\" unique-identifier=\"epub-id-1\">\n",
        if epub3 { "3.0" } else { "2.0" }
    ));
    opf.push_str("  <metadata xmlns:dc=\"http://purl.org/dc/elements/1.1/\"\n            xmlns:opf=\"http://www.idpf.org/2007/opf\">\n");
    opf.push_str(&format!("    <dc:identifier id=\"epub-id-1\">urn:uuid:{}</dc:identifier>\n", uuid));
    opf.push_str(&format!("    <dc:title>{}</dc:title>\n", title_raw));
    opf.push_str("    \n    \n");
    if epub3 {
        opf.push_str(&format!("    <dc:language id=\"epub-creator-0\">{}</dc:language>\n", lang));
    } else {
        opf.push_str(&format!("    <dc:language>{}</dc:language>\n", lang));
    }
    opf.push_str("    \n    \n    \n");
    if epub3 {
        opf.push_str(&format!("    <dc:creator id=\"epub-creator-0\">{}</dc:creator>\n", author));
        opf.push_str("    <meta refines=\"#epub-creator-0\" property=\"role\" scheme=\"marc:relators\">aut</meta>\n");
    } else {
        opf.push_str(&format!("    <dc:creator opf:role=\"aut\">{}</dc:creator>\n", author));
    }
    opf.push_str("    \n    \n");
    if epub3 {
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_secs())
            .unwrap_or(0);
        let (y, mo, d, h, mi, s) = crate::misc::civil_from_unix(now as i64);
        opf.push_str(&format!(
            "    <meta property=\"dcterms:modified\">{:04}-{:02}-{:02}T{:02}:{:02}:{:02}Z</meta>\n",
            y, mo, d, h, mi, s
        ));
    }
    if let Ok(d) = book.options.get_str("description") {
        opf.push_str(&format!("    <dc:description>{}</dc:description>\n", d));
    }
    if let Ok(s) = book.options.get_str("subject") {
        opf.push_str(&format!("    <dc:subject>{}</dc:subject>\n", s));
    }
    if cover_image.is_some() {
        opf.push_str("    <meta name=\"cover\" content=\"cover-image\"/>\n");
    }
    if !epub3 {
        opf.push('\n');
    }
    opf.push_str("  </metadata>\n  <manifest>\n");
    opf.push_str("    <item id=\"ncx\" href=\"toc.ncx\" media-type=\"application/x-dtbncx+xml\"/>\n");
    if epub3 {
        opf.push_str("    <item id=\"nav\" href=\"nav.xhtml\" media-type=\"application/xhtml+xml\" properties=\"nav\"/>\n");
    } else {
        opf.push_str("    <item id=\"nav\" href=\"nav.xhtml\" media-type=\"application/xhtml+xml\"/>\n");
    }
    for it in &items {
        if it.properties.is_empty() {
            opf.push_str(&format!(
                "    <item media-type=\"{}\" id=\"{}\" href=\"{}\"/>\n",
                it.mime, it.id, it.href
            ));
        } else {
            opf.push_str(&format!(
                "    <item media-type=\"{}\" properties=\"{}\" id=\"{}\" href=\"{}\"/>\n",
                it.mime, it.properties, it.id, it.href
            ));
        }
    }
    opf.push_str("  </manifest>\n");
    if epub3 {
        opf.push_str("  <spine toc=\"ncx\" page-progression-direction=\"ltr\">\n");
    } else {
        opf.push_str("  <spine toc=\"ncx\">\n");
    }
    for s in &spine {
        opf.push_str(&format!("    <itemref idref=\"id_{}\"/>\n", s.href));
    }
    opf.push_str("  </spine>\n  <guide>\n");
    opf.push_str(&format!("    <reference type=\"toc\" title=\"{}\" href=\"nav.xhtml\"/>\n", loc_toc));
    let mut text_done = false;
    for s in &spine {
        if s.guide_type == "text" {
            if text_done {
                continue;
            }
            text_done = true;
        }
        opf.push_str(&format!(
            "    <reference type=\"{}\" title=\"{}\" href=\"{}\"/>\n",
            s.guide_type, s.title, s.href
        ));
    }
    opf.push_str("  </guide>\n</package>\n");

    // toc.ncx
    let mut ncx = String::new();
    ncx.push_str("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<ncx version=\"2005-1\" xmlns=\"http://www.daisy.org/z3986/2005/ncx/\">\n  <head>\n");
    ncx.push_str(&format!("    <meta name=\"dtb:depth\" content=\"{}\" />\n", full_toc.depth().max(1)));
    ncx.push_str("    <meta name=\"dtb:totalPageCount\" content=\"0\" />\n    <meta name=\"dtb:maxPageNumber\" content=\"0\" />\n  </head>\n");
    ncx.push_str(&format!("  <docTitle>\n    <text>{}</text>\n  </docTitle>\n  <navMap>\n", loc_toc));
    ncx.push_str(&full_toc.render_ncx());
    ncx.push_str("  </navMap>\n</ncx>\n");

    for (name, data) in &files {
        zip.add_file(&format!("OEBPS/{}", name), data);
    }
    zip.add_file("OEBPS/content.opf", opf.as_bytes());
    zip.add_file("OEBPS/toc.ncx", ncx.as_bytes());
    zip.add_file("OEBPS/nav.xhtml", nav.as_bytes());

    crate::logger::warn("epub", &crate::lang::lformat("Could not run zip command, falling back to zip library"));
    zip.write_to(output).map_err(|e| {
        Error::render(
            Source::empty(),
            crate::lang::lformat2("could not write to file '{file}': {error}", &[("file", output), ("error", &e.to_string())]),
        )
    })
}

/// Chapters' first toc entries should link to the file without anchor
fn fix_toc_urls(elements: &mut [crate::toc::TocElement]) {
    for e in elements.iter_mut() {
        if e.level <= 1 {
            if let Some(pos) = e.url.find('#') {
                let anchor = &e.url[pos + 1..];
                if anchor.starts_with("link-") {
                    // only the first header of a chapter file gets the bare file url;
                    // this is marked by the renderer with `first_in_file`
                }
            }
        }
        fix_toc_urls(&mut e.children);
    }
}

/// Clone a toc element using raw titles
fn raw_toc(e: &crate::toc::TocElement) -> crate::toc::TocElement {
    let mut n = crate::toc::TocElement::new(e.level, &e.url, &e.raw_title);
    n.raw_title = e.raw_title.clone();
    n.children = e.children.iter().map(raw_toc).collect();
    n
}
